fn sanitize_merge_cache_capacity(capacity: usize) -> usize {
    if capacity == 0 {
        MERGE_LEDGER_CACHE_CAPACITY
    } else {
        capacity
    }
}
impl MergeLedgerLog {
    fn open_at(path: &Path, cache_capacity: usize) -> Result<Self> {
        let cache_capacity = sanitize_merge_cache_capacity(cache_capacity);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)
                .map_err(|err| Error::MkDir(err, parent.to_path_buf()))?;
        }
        let mut file = FileWrap::open_with(path.to_path_buf(), |opts| {
            opts.read(true).create(true).append(true);
        })?;
        let (entries, total_entries, frames_by_hash, frames_by_epoch, latest_execution_entries) =
            Self::load_entries(&mut file, cache_capacity)?;
        file.try_io(|f| f.seek(SeekFrom::End(0)))?;
        Ok(Self {
            history_deferred: false,
            file: Some(file),
            entries,
            cache_capacity,
            total_entries,
            frames_by_hash,
            frames_by_epoch,
            in_memory_entries: BTreeMap::new(),
            latest_execution_entries,
            append_recovery_offset: None,
            #[cfg(test)]
            full_history_scans: 0,
            #[cfg(test)]
            indexed_lookups: 0,
            #[cfg(test)]
            indexed_membership_checks: 0,
            #[cfg(test)]
            complete_execution_scans: 0,
            #[cfg(test)]
            fail_next_append: false,
            #[cfg(test)]
            fail_next_append_after: None,
        })
    }
    fn in_memory(cache_capacity: usize) -> Self {
        let cache_capacity = sanitize_merge_cache_capacity(cache_capacity);
        Self {
            history_deferred: false,
            file: None,
            entries: Vec::new(),
            cache_capacity,
            total_entries: 0,
            frames_by_hash: BTreeMap::new(),
            frames_by_epoch: BTreeMap::new(),
            in_memory_entries: BTreeMap::new(),
            latest_execution_entries: BTreeMap::new(),
            append_recovery_offset: None,
            #[cfg(test)]
            full_history_scans: 0,
            #[cfg(test)]
            indexed_lookups: 0,
            #[cfg(test)]
            indexed_membership_checks: 0,
            #[cfg(test)]
            complete_execution_scans: 0,
            #[cfg(test)]
            fail_next_append: false,
            #[cfg(test)]
            fail_next_append_after: None,
        }
    }
    /// Construct an opaque merge-log placeholder without opening or scanning the durable file.
    fn deferred(cache_capacity: usize) -> Self {
        let mut log = Self::in_memory(cache_capacity);
        log.history_deferred = true;
        log
    }
    fn ensure_history_available(&self) -> Result<()> {
        if self.history_deferred {
            return Err(Error::EmergencyFastAuxiliaryUnavailable {
                subsystem: "merge ledger",
            });
        }
        Ok(())
    }
    fn append(&mut self, entry: &MergeLedgerEntry) -> Result<bool> {
        self.ensure_history_available()?;
        if self.preflight_append(entry)? {
            self.append_preflighted(entry)?;
            return Ok(true);
        }
        Ok(false)
    }
    /// Validate an append without mutating the durable log.
    ///
    /// Returns `false` when the exact entry is already present and `true` when
    /// it is the next contiguous frame.
    fn preflight_append(&mut self, entry: &MergeLedgerEntry) -> Result<bool> {
        self.ensure_history_available()?;
        self.recover_failed_append_tail()?;
        if !entry.has_current_version() {
            return Err(Error::MergeCarrierConflict(format!(
                "unsupported merge ledger entry version {}",
                entry.version
            )));
        }
        let entry_hash = entry.canonical_hash();
        if let Some(existing) = self.entry_by_hash(entry_hash)? {
            return if existing == *entry {
                Ok(false)
            } else {
                Err(Error::MergeCarrierConflict(
                    "committed merge log contains different bytes for the same entry hash"
                        .to_owned(),
                ))
            };
        }
        let expected_epoch = u64::try_from(self.total_entries)
            .unwrap_or(u64::MAX)
            .saturating_add(1);
        if entry.epoch_id != expected_epoch {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "merge ledger epoch must be contiguous: expected {expected_epoch}, got {}",
                entry.epoch_id
            ))));
        }
        if !entry.canonical_size_within_limit() {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "merge ledger entry exceeds {MAX_MERGE_LEDGER_ENTRY_BYTES} bytes"
            ))));
        }
        if self.frames_by_hash.contains_key(&entry_hash)
            || self.frames_by_epoch.contains_key(&entry.epoch_id)
        {
            return Err(Error::MergeCarrierConflict(
                "merge ledger append duplicates an indexed hash or epoch".to_owned(),
            ));
        }
        Self::validate_execution_entry_index_update(&self.latest_execution_entries, entry)?;
        Ok(true)
    }
    fn recover_failed_append_tail(&mut self) -> Result<()> {
        self.ensure_history_available()?;
        let Some(frame_offset) = self.append_recovery_offset else {
            return Ok(());
        };
        let Some(file) = self.file.as_mut() else {
            self.append_recovery_offset = None;
            return Ok(());
        };
        file.try_io(|inner| inner.set_len(frame_offset))?;
        file.try_io(|inner| inner.sync_data())?;
        file.try_io(|inner| inner.seek(SeekFrom::End(0)))?;
        self.append_recovery_offset = None;
        Ok(())
    }
    #[cfg(test)]
    fn injected_append_boundary_error(point: MergeLedgerAppendFailurePoint) -> Error {
        Error::IO(
            std::io::Error::other(format!(
                "merge-ledger append failed after {point:?} for test injection"
            )),
            PathBuf::from("merge_log_test_fail"),
        )
    }
    fn append_preflighted(&mut self, entry: &MergeLedgerEntry) -> Result<()> {
        self.ensure_history_available()?;
        let entry_hash = entry.canonical_hash();
        let encoded = Encode::encode(entry);
        let len: u32 = encoded.len().try_into().map_err(|_| {
            Error::NoritoFrame(norito::core::Error::Message(
                "merge ledger entry exceeds 4 GiB".into(),
            ))
        })?;
        #[cfg(test)]
        if self.fail_next_append {
            self.fail_next_append = false;
            return Err(Error::IO(
                std::io::Error::other("merge-ledger append failed for test injection"),
                PathBuf::from("merge_log_test_fail"),
            ));
        }
        #[cfg(test)]
        let fail_after = self.fail_next_append_after.take();
        let frame_offset = if let Some(file) = self.file.as_mut() {
            let frame_offset = file.try_io(|f| f.seek(SeekFrom::End(0)))?;
            let append_result = (|| {
                file.try_io(|f| f.write_all(&len.to_le_bytes()))?;
                #[cfg(test)]
                if fail_after == Some(MergeLedgerAppendFailurePoint::AfterLength) {
                    return Err(Self::injected_append_boundary_error(
                        MergeLedgerAppendFailurePoint::AfterLength,
                    ));
                }
                file.try_io(|f| f.write_all(&encoded))?;
                #[cfg(test)]
                if fail_after == Some(MergeLedgerAppendFailurePoint::AfterPayload) {
                    return Err(Self::injected_append_boundary_error(
                        MergeLedgerAppendFailurePoint::AfterPayload,
                    ));
                }
                file.try_io(|f| f.sync_data())?;
                #[cfg(test)]
                if fail_after == Some(MergeLedgerAppendFailurePoint::AfterSync) {
                    return Err(Self::injected_append_boundary_error(
                        MergeLedgerAppendFailurePoint::AfterSync,
                    ));
                }
                Ok(())
            })();
            if let Err(append_error) = append_result {
                self.append_recovery_offset = Some(frame_offset);
                if let Err(recovery_error) = self.recover_failed_append_tail() {
                    return Err(Error::MergeCarrierConflict(format!(
                        "merge-ledger append failed ({append_error}) and exact tail recovery failed ({recovery_error})"
                    )));
                }
                return Err(append_error);
            }
            frame_offset
        } else {
            u64::try_from(self.total_entries).unwrap_or(u64::MAX)
        };
        self.total_entries = self.total_entries.saturating_add(1);
        let frame = MergeLedgerFrameIndex {
            frame_offset,
            payload_len: len,
            epoch_id: entry.epoch_id,
            entry_hash,
        };
        self.frames_by_hash.insert(entry_hash, frame);
        self.frames_by_epoch.insert(entry.epoch_id, frame);
        if self.file.is_none() {
            self.in_memory_entries.insert(entry_hash, entry.clone());
        }
        Self::record_execution_entry_unchecked(&mut self.latest_execution_entries, entry);
        self.entries.push(entry.clone());
        self.trim_cache();
        Ok(())
    }
    fn read_indexed_frame(
        file: &mut FileWrap,
        frame: MergeLedgerFrameIndex,
    ) -> Result<MergeLedgerEntry> {
        file.try_io(|inner| inner.seek(SeekFrom::Start(frame.frame_offset)))?;
        let mut len_buf = [0u8; 4];
        file.try_io(|inner| inner.read_exact(&mut len_buf))?;
        let payload_len = u32::from_le_bytes(len_buf);
        if payload_len != frame.payload_len
            || usize::try_from(payload_len).unwrap_or(usize::MAX) > MAX_MERGE_LEDGER_ENTRY_BYTES
        {
            return Err(Error::MergeCarrierConflict(
                "indexed merge frame length changed after startup validation".to_owned(),
            ));
        }
        let mut bytes = vec![0u8; usize::try_from(payload_len)?];
        file.try_io(|inner| inner.read_exact(&mut bytes))?;
        let mut input = bytes.as_slice();
        let entry = MergeLedgerEntry::decode_all(&mut input).map_err(|err| {
            Error::MergeCarrierConflict(format!(
                "indexed merge frame failed exact Norito decode: {err}"
            ))
        })?;
        if !entry.has_current_version() {
            return Err(Error::MergeCarrierConflict(format!(
                "indexed merge frame has unsupported merge ledger entry version {}",
                entry.version
            )));
        }
        if entry.encode() != bytes
            || !entry.canonical_size_within_limit()
            || entry.epoch_id != frame.epoch_id
            || entry.canonical_hash() != frame.entry_hash
        {
            return Err(Error::MergeCarrierConflict(
                "indexed merge frame bytes or identity changed after startup validation".to_owned(),
            ));
        }
        Ok(entry)
    }
    fn all_entries(&mut self) -> Result<Vec<MergeLedgerEntry>> {
        self.ensure_history_available()?;
        self.recover_failed_append_tail()?;
        #[cfg(test)]
        {
            self.full_history_scans = self.full_history_scans.saturating_add(1);
        }
        let frames = self.frames_by_epoch.values().copied().collect::<Vec<_>>();
        let Some(file) = self.file.as_mut() else {
            return Ok(self
                .frames_by_epoch
                .values()
                .filter_map(|frame| self.in_memory_entries.get(&frame.entry_hash).cloned())
                .collect());
        };
        let indexed_len = frames.last().map_or(0, |frame| {
            frame
                .frame_offset
                .saturating_add(4)
                .saturating_add(u64::from(frame.payload_len))
        });
        let actual_len = file.try_io(|inner| inner.metadata().map(|metadata| metadata.len()))?;
        if actual_len != indexed_len {
            return Err(Error::MergeCarrierConflict(format!(
                "merge ledger length changed after index construction: indexed {indexed_len}, actual {actual_len}"
            )));
        }
        let entries_result = frames
            .into_iter()
            .map(|frame| Self::read_indexed_frame(file, frame))
            .collect::<Result<Vec<_>>>();
        let restore = file.try_io(|inner| inner.seek(SeekFrom::End(0)));
        restore?;
        let entries = entries_result?;
        self.entries = entries
            .iter()
            .rev()
            .take(self.cache_capacity)
            .cloned()
            .collect::<Vec<_>>();
        self.entries.reverse();
        Ok(entries)
    }
    fn validate_indexed_file_length(&mut self) -> Result<()> {
        self.ensure_history_available()?;
        self.recover_failed_append_tail()?;
        let Some(file) = self.file.as_mut() else {
            return Ok(());
        };
        let indexed_len = self
            .frames_by_epoch
            .last_key_value()
            .map_or(0, |(_, frame)| {
                frame
                    .frame_offset
                    .saturating_add(4)
                    .saturating_add(u64::from(frame.payload_len))
            });
        let actual_len = file.try_io(|inner| inner.metadata().map(|metadata| metadata.len()))?;
        if actual_len != indexed_len {
            return Err(Error::MergeCarrierConflict(format!(
                "merge ledger length changed after index construction: indexed {indexed_len}, actual {actual_len}"
            )));
        }
        Ok(())
    }
    fn load_entries(
        file: &mut FileWrap,
        cache_capacity: usize,
    ) -> Result<(
        Vec<MergeLedgerEntry>,
        usize,
        BTreeMap<HashOf<MergeLedgerEntry>, MergeLedgerFrameIndex>,
        BTreeMap<u64, MergeLedgerFrameIndex>,
        BTreeMap<(LaneId, DataSpaceId, Hash), (u64, HashOf<MergeLedgerEntry>)>,
    )> {
        file.try_io(|f| f.seek(SeekFrom::Start(0)))?;
        let file_len = file.try_io(|f| f.metadata().map(|meta| meta.len()))?;
        let mut entries = Vec::new();
        let mut total_entries = 0usize;
        let mut valid_len = 0u64;
        let mut frames_by_hash = BTreeMap::new();
        let mut frames_by_epoch = BTreeMap::new();
        let mut latest_execution_entries: BTreeMap<
            (LaneId, DataSpaceId, Hash),
            (u64, HashOf<MergeLedgerEntry>),
        > = BTreeMap::new();
        let truncated = loop {
            let mut len_buf = [0u8; 4];
            match file.try_io(|f| f.read_exact(&mut len_buf)) {
                Ok(()) => {
                    let len = u32::from_le_bytes(len_buf) as usize;
                    if len == 0 {
                        return Err(Error::MergeCarrierConflict(
                            "merge ledger contains a zero-length complete frame".to_owned(),
                        ));
                    }
                    if len > MAX_MERGE_LEDGER_ENTRY_BYTES {
                        return Err(Error::MergeCarrierConflict(format!(
                            "merge ledger frame length {len} exceeds {MAX_MERGE_LEDGER_ENTRY_BYTES} bytes"
                        )));
                    }
                    let mut buf = vec![0u8; len];
                    match file.try_io(|f| f.read_exact(&mut buf)) {
                        Ok(()) => {}
                        Err(Error::IO(err, _)) if err.kind() == ErrorKind::UnexpectedEof => {
                            break true;
                        }
                        Err(err) => return Err(err),
                    }
                    let mut input = &buf[..];
                    let entry = MergeLedgerEntry::decode_all(&mut input).map_err(|err| {
                        Error::MergeCarrierConflict(format!(
                            "merge ledger frame {total_entries} failed exact Norito decode: {err}"
                        ))
                    })?;
                    if !entry.has_current_version() {
                        return Err(Error::MergeCarrierConflict(format!(
                            "merge ledger frame {total_entries} has unsupported merge ledger entry version {}",
                            entry.version
                        )));
                    }
                    if entry.encode() != buf {
                        return Err(Error::MergeCarrierConflict(format!(
                            "merge ledger frame {total_entries} is not canonical Norito"
                        )));
                    }
                    if !entry.canonical_size_within_limit() {
                        return Err(Error::MergeCarrierConflict(format!(
                            "merge ledger frame {total_entries} exceeds the canonical framed size limit"
                        )));
                    }
                    let expected_epoch = u64::try_from(total_entries)
                        .unwrap_or(u64::MAX)
                        .saturating_add(1);
                    let entry_hash = entry.canonical_hash();
                    if entry.epoch_id != expected_epoch
                        || frames_by_hash.contains_key(&entry_hash)
                        || frames_by_epoch.contains_key(&entry.epoch_id)
                    {
                        return Err(Error::MergeCarrierConflict(format!(
                            "merge ledger frame {} has a non-contiguous epoch or duplicate hash",
                            total_entries
                        )));
                    }
                    let frame = MergeLedgerFrameIndex {
                        frame_offset: valid_len,
                        payload_len: u32::try_from(len).map_err(|_| {
                            Error::MergeCarrierConflict(
                                "merge ledger frame length does not fit its index".to_owned(),
                            )
                        })?,
                        epoch_id: entry.epoch_id,
                        entry_hash,
                    };
                    frames_by_hash.insert(entry_hash, frame);
                    frames_by_epoch.insert(entry.epoch_id, frame);
                    Self::record_execution_entry(&mut latest_execution_entries, &entry)?;
                    total_entries = total_entries.saturating_add(1);
                    entries.push(entry);
                    valid_len = valid_len.saturating_add(4 + len as u64);
                    if entries.len() > cache_capacity {
                        let overflow = entries.len() - cache_capacity;
                        entries.drain(0..overflow);
                    }
                }
                Err(Error::IO(err, _)) if err.kind() == ErrorKind::UnexpectedEof => {
                    break file_len > valid_len;
                }
                Err(err) => return Err(err),
            }
        };
        if truncated && file_len > valid_len {
            warn!(
                path = %file.path.display(),
                file_len,
                valid_len,
                "truncating merge ledger log after partial entry"
            );
            file.try_io(|f| f.set_len(valid_len))?;
            file.try_io(|f| f.sync_data())?;
        }
        Ok((
            entries,
            total_entries,
            frames_by_hash,
            frames_by_epoch,
            latest_execution_entries,
        ))
    }
    fn truncate_to_len(&mut self, keep: usize) -> Result<()> {
        self.ensure_history_available()?;
        self.recover_failed_append_tail()?;
        if keep >= self.total_entries {
            return Ok(());
        }
        if let Some(file) = self.file.as_mut() {
            let new_len = if keep == 0 {
                0
            } else {
                let epoch = u64::try_from(keep)?;
                let frame = self.frames_by_epoch.get(&epoch).ok_or_else(|| {
                    Error::MergeCarrierConflict(
                        "merge truncate index is missing its retained terminal epoch".to_owned(),
                    )
                })?;
                frame
                    .frame_offset
                    .checked_add(4)
                    .and_then(|offset| offset.checked_add(u64::from(frame.payload_len)))
                    .ok_or_else(|| {
                        Error::MergeCarrierConflict(
                            "merge truncate frame offset overflow".to_owned(),
                        )
                    })?
            };
            file.try_io(|f| f.set_len(new_len))?;
            let sync_result = file.try_io(|f| f.sync_data());
            let (entries, total_entries, frames_by_hash, frames_by_epoch, latest_execution_entries) =
                Self::load_entries(file, self.cache_capacity)?;
            file.try_io(|inner| inner.seek(SeekFrom::End(0)))?;
            self.entries = entries;
            self.total_entries = total_entries;
            self.frames_by_hash = frames_by_hash;
            self.frames_by_epoch = frames_by_epoch;
            self.latest_execution_entries = latest_execution_entries;
            sync_result?;
        } else {
            self.frames_by_epoch
                .retain(|epoch, _| usize::try_from(*epoch).is_ok_and(|epoch| epoch <= keep));
            let removed_hashes = self
                .frames_by_hash
                .iter()
                .filter_map(|(hash, frame)| {
                    (!usize::try_from(frame.epoch_id).is_ok_and(|epoch| epoch <= keep))
                        .then_some(*hash)
                })
                .collect::<Vec<_>>();
            self.frames_by_hash.retain(|_, frame| {
                usize::try_from(frame.epoch_id).is_ok_and(|epoch| epoch <= keep)
            });
            for hash in removed_hashes {
                self.in_memory_entries.remove(&hash);
            }
            self.entries = self
                .frames_by_epoch
                .values()
                .filter_map(|frame| self.in_memory_entries.get(&frame.entry_hash).cloned())
                .collect();
            self.total_entries = keep;
            self.latest_execution_entries = Self::execution_index_for_entries(&self.entries)?;
        }
        self.trim_cache();
        Ok(())
    }
    fn trim_cache(&mut self) {
        if self.entries.len() > self.cache_capacity {
            let overflow = self.entries.len() - self.cache_capacity;
            self.entries.drain(0..overflow);
        }
    }
}
