    /// Shared bounded-history budget for durable per-route Native AMX evidence.
    ///
    /// Native manifests and receipts use the operator-configured Kura lane
    /// history retention rather than introducing an environment-only or
    /// consensus-divergent limit. One extra entry may exist transiently while
    /// a strict append is being compacted or recovered.
    fn native_amx_participant_evidence_retention(&self) -> NonZeroUsize {
        self.lane_history_retention
    }
    /// Configured stable aggregate for both Native artifact families combined.
    ///
    /// The historical method name is retained to keep geometry callers on one
    /// source of truth; this value is not a per-file or per-family allowance.
    fn native_amx_participant_evidence_file_bytes(&self) -> u64 {
        u64::try_from(self.pending_control_sidecar_limits.aggregate_bytes)
            .expect("configured pending-control sidecar bytes fit u64")
    }
    /// Maximum combined Native manifest/receipt payload bytes admitted while
    /// one complete pair is crossing its crash-safe publication barriers.
    ///
    /// Stable retained evidence consumes at most the configured shared
    /// pending-control budget. An incoming manifest/receipt pair must itself
    /// fit that same budget, so one additional budget is sufficient and
    /// necessary transient headroom without granting either artifact family a
    /// separate allowance.
    fn native_amx_participant_evidence_startup_bytes(&self) -> Result<u64> {
        self.native_amx_participant_evidence_file_bytes()
            .checked_mul(2)
            .ok_or_else(|| {
                Error::PruneIntentConflict(
                    "configured Native AMX evidence startup byte bound overflowed".to_owned(),
                )
            })
    }
    fn native_amx_participant_evidence_pair_fits_stable_bytes(
        &self,
        manifest_bytes: usize,
        receipt_bytes: usize,
    ) -> bool {
        manifest_bytes != 0
            && receipt_bytes != 0
            && manifest_bytes
                .checked_add(receipt_bytes)
                .is_some_and(|bytes| {
                    u64::try_from(bytes).is_ok_and(|bytes| {
                        bytes <= self.native_amx_participant_evidence_file_bytes()
                    })
                })
    }
    fn validate_native_amx_participant_application_pair_byte_lengths(
        &self,
        manifest_bytes: usize,
        receipt_bytes: usize,
        standalone_limit: u64,
    ) -> std::result::Result<(), NativeAmxParticipantApplicationEvidenceByteBudgetError> {
        if manifest_bytes == 0 {
            return Err(
                NativeAmxParticipantApplicationEvidenceByteBudgetError::Budget(
                    "Native AMX participant manifest framing is empty".to_owned(),
                ),
            );
        }
        if receipt_bytes == 0 {
            return Err(
                NativeAmxParticipantApplicationEvidenceByteBudgetError::Budget(
                    "Native AMX participant receipt framing is empty".to_owned(),
                ),
            );
        }
        let manifest_bytes_u64 = u64::try_from(manifest_bytes).map_err(|_| {
            NativeAmxParticipantApplicationEvidenceByteBudgetError::Budget(
                "Native AMX participant manifest length does not fit u64".to_owned(),
            )
        })?;
        let receipt_bytes_u64 = u64::try_from(receipt_bytes).map_err(|_| {
            NativeAmxParticipantApplicationEvidenceByteBudgetError::Budget(
                "Native AMX participant receipt length does not fit u64".to_owned(),
            )
        })?;
        if manifest_bytes_u64 > standalone_limit {
            return Err(
                NativeAmxParticipantApplicationEvidenceByteBudgetError::Budget(format!(
                    "Native AMX participant manifest is {manifest_bytes_u64} bytes, exceeding the standalone payload budget of {standalone_limit} bytes"
                )),
            );
        }
        if receipt_bytes_u64 > standalone_limit {
            return Err(
                NativeAmxParticipantApplicationEvidenceByteBudgetError::Budget(format!(
                    "Native AMX participant receipt is {receipt_bytes_u64} bytes, exceeding the standalone payload budget of {standalone_limit} bytes"
                )),
            );
        }
        let pair_bytes = checked_native_amx_participant_application_pair_bytes(
            manifest_bytes_u64,
            receipt_bytes_u64,
        )?;
        if !self
            .native_amx_participant_evidence_pair_fits_stable_bytes(manifest_bytes, receipt_bytes)
        {
            return Err(
                NativeAmxParticipantApplicationEvidenceByteBudgetError::Budget(format!(
                    "Native AMX participant manifest/receipt pair is {pair_bytes} bytes, exceeding the configured shared stable aggregate byte bound of {} bytes",
                    self.native_amx_participant_evidence_file_bytes()
                )),
            );
        }
        Ok(())
    }
    /// Validate the exact framed Native AMX evidence pair for every route
    /// without locks, filesystem access, inventory reads, or telemetry.
    ///
    /// Candidate validation supplies `None`, which selects a typed fixed-width
    /// finality placeholder. Decided-block validation supplies the actual
    /// durable finality hash and rechecks the same byte geometry before any
    /// staging or persistence begins.
    pub(crate) fn validate_native_amx_participant_application_evidence_byte_budget(
        &self,
        manifest: &crate::sumeragi::exec::NativeAmxApplicationManifestV1,
        finality_artifact_hash: Option<HashOf<V2FinalityArtifact>>,
    ) -> std::result::Result<(), NativeAmxParticipantApplicationEvidenceByteBudgetError> {
        let finality_artifact_hash = finality_artifact_hash
            .unwrap_or_else(native_amx_participant_application_finality_placeholder_hash);
        let artifacts =
            native_amx_participant_application_artifacts(manifest, finality_artifact_hash).ok_or(
                NativeAmxParticipantApplicationEvidenceByteBudgetError::ArtifactConstruction,
            )?;
        for (manifest, receipt) in artifacts {
            let (manifest_bytes, receipt_bytes) =
                native_amx_participant_application_pair_framed_bytes(&manifest, &receipt).map_err(
                    NativeAmxParticipantApplicationEvidenceByteBudgetError::ArtifactFraming,
                )?;
            self.validate_native_amx_participant_application_pair_byte_lengths(
                manifest_bytes.len(),
                receipt_bytes.len(),
                STRICT_INIT_MAX_BLOCK_BYTES,
            )?;
        }
        Ok(())
    }
    fn native_amx_evidence_stable_payload_bytes(
        inventory: &NativeAmxEvidenceInventory,
    ) -> Option<u64> {
        inventory
            .stable_bytes(NativeAmxEvidenceKind::Manifest)
            .checked_add(inventory.stable_bytes(NativeAmxEvidenceKind::Receipt))
    }
    fn native_amx_evidence_total_payload_bytes(
        inventory: &NativeAmxEvidenceInventory,
    ) -> Option<u64> {
        inventory.temporaries.values().try_fold(
            Self::native_amx_evidence_stable_payload_bytes(inventory)?,
            |total, file| total.checked_add(file.metadata.file.len()),
        )
    }
    /// Validate the retained per-route evidence window independently of its
    /// oldest pruned predecessor.
    ///
    /// The retained union must be one participant-height suffix. Retirement,
    /// archive, and pair pruning require a complete manifest/receipt pair at
    /// every retained height. Startup may additionally retain exactly one
    /// highest half-pair while its authenticated carrier repairs the other
    /// half. Every adjacent retained successor is bound to the preceding
    /// manifest's exact descriptor identity.
    fn validate_native_amx_retained_history_continuity(
        manifests: &BTreeMap<u64, NativeAmxParticipantApplicationManifestArtifactV1>,
        receipts: &BTreeMap<u64, NativeAmxParticipantApplicationReceiptArtifact>,
        allow_highest_partial: bool,
    ) -> std::result::Result<(), &'static str> {
        let manifest_heights = manifests.keys().copied().collect::<BTreeSet<_>>();
        let receipt_heights = receipts.keys().copied().collect::<BTreeSet<_>>();
        let retained_heights = manifest_heights
            .union(&receipt_heights)
            .copied()
            .collect::<Vec<_>>();
        if retained_heights.windows(2).any(|pair| {
            pair[0]
                .checked_add(1)
                .is_none_or(|successor| successor != pair[1])
        }) {
            return Err(
                "retained Native AMX evidence is not a contiguous participant-height suffix",
            );
        }
        let manifest_only = manifest_heights
            .difference(&receipt_heights)
            .copied()
            .collect::<Vec<_>>();
        let receipt_only = receipt_heights
            .difference(&manifest_heights)
            .copied()
            .collect::<Vec<_>>();
        let partial_count = manifest_only.len().saturating_add(receipt_only.len());
        if (!allow_highest_partial && partial_count != 0)
            || partial_count > usize::from(allow_highest_partial)
            || manifest_only
                .first()
                .or_else(|| receipt_only.first())
                .is_some_and(|height| retained_heights.last() != Some(height))
        {
            return Err(
                "retained Native AMX evidence does not contain exact complete pairs plus at most one highest repair half",
            );
        }
        for (height, manifest) in manifests {
            let Some(receipt) = receipts.get(height) else {
                continue;
            };
            if receipt.manifest_artifact_hash != HashOf::new(manifest)
                || receipt.finality_artifact_hash != manifest.finality_artifact_hash
                || !Self::native_amx_participant_receipt_matches_manifest_leaf(
                    receipt,
                    &manifest.leaf,
                )
            {
                return Err(
                    "retained Native AMX manifest/receipt pair has conflicting exact identities",
                );
            }
        }
        for pair in retained_heights.windows(2) {
            let predecessor_height = pair[0];
            let successor_height = pair[1];
            let predecessor = manifests
                .get(&predecessor_height)
                .ok_or("retained Native AMX successor has no preceding manifest descriptor")?;
            let (lane_id, dataspace_id, lane_incarnation, previous_height, previous_hash) =
                if let Some(successor) = manifests.get(&successor_height) {
                    (
                        successor.leaf.lane_id,
                        successor.leaf.dataspace_id,
                        successor.leaf.lane_incarnation,
                        successor.leaf.predecessor_height,
                        successor.leaf.predecessor_descriptor_hash,
                    )
                } else {
                    let successor = receipts
                        .get(&successor_height)
                        .ok_or("retained Native AMX successor has neither manifest nor receipt")?;
                    let descriptor = &successor.participant_proposal.descriptor;
                    (
                        descriptor.lane_id,
                        descriptor.dataspace_id,
                        descriptor.lane_incarnation,
                        descriptor.previous_lane_block_height,
                        descriptor.previous_lane_block_descriptor_hash,
                    )
                };
            if lane_id != predecessor.leaf.lane_id
                || dataspace_id != predecessor.leaf.dataspace_id
                || lane_incarnation != predecessor.leaf.lane_incarnation
                || previous_height != predecessor_height
                || previous_hash != Some(predecessor.leaf.descriptor_hash)
            {
                return Err(
                    "retained Native AMX successor predecessor identity differs from the preceding manifest",
                );
            }
        }
        Ok(())
    }
    fn native_amx_evidence_prune_intent_max_entries(retention: NonZeroUsize) -> Result<usize> {
        retention
            .get()
            .checked_add(1)
            .and_then(|count| count.checked_mul(2))
            .ok_or_else(|| {
                Error::PruneIntentConflict(
                    "configured Native AMX evidence prune-intent entry bound overflowed".to_owned(),
                )
            })
    }
    fn native_amx_evidence_prune_intent_max_bytes_for_retention(
        retention: NonZeroUsize,
        pending_control_sidecar_bytes: usize,
    ) -> Result<usize> {
        let max_entries = Self::native_amx_evidence_prune_intent_max_entries(retention)?;
        let shared_budget = pending_control_sidecar_bytes;
        let allocation_bytes = max_entries
            .checked_mul(std::mem::size_of::<NativeAmxEvidencePruneEntryV2>())
            .and_then(|bytes| {
                bytes.checked_add(std::mem::size_of::<NativeAmxEvidencePruneProtectedLatestV2>())
            })
            .ok_or_else(|| {
                Error::PruneIntentConflict(
                    "configured Native AMX evidence prune-intent allocation overflowed".to_owned(),
                )
            })?;
        if allocation_bytes > shared_budget {
            return Err(Error::PruneIntentConflict(
                "configured Native AMX evidence retention requires a prune journal larger than the shared sidecar budget"
                    .to_owned(),
            ));
        }
        let maximum_hash = Hash::prehashed([u8::MAX; Hash::LENGTH]);
        let maximum_entry = NativeAmxEvidencePruneEntryV2 {
            kind: NativeAmxEvidencePruneIntentV2::RECEIPT_KIND,
            participant_height: u64::MAX,
            artifact_hash: maximum_hash,
        };
        let mut entries = Vec::new();
        entries.try_reserve_exact(max_entries)?;
        entries.resize(max_entries, maximum_entry);
        let maximum_intent = NativeAmxEvidencePruneIntentV2 {
            version: NativeAmxEvidencePruneIntentV2::VERSION,
            lane_id: LaneId::new(u32::MAX),
            dataspace_id: DataSpaceId::new(u64::MAX),
            lane_incarnation: maximum_hash,
            protected_latest: NativeAmxEvidencePruneProtectedLatestV2 {
                identity: NativeAmxParticipantReceiptLatestIndexV2 {
                    version: NativeAmxParticipantReceiptLatestIndexV2::VERSION,
                    lane_id: LaneId::new(u32::MAX),
                    dataspace_id: DataSpaceId::new(u64::MAX),
                    lane_incarnation: maximum_hash,
                    lane_block_height: u64::MAX,
                    participant_proposal_hash: maximum_hash,
                    participant_settlement_hash: HashOf::from_untyped_unchecked(maximum_hash),
                    application_block_height: u64::MAX,
                    application_block_hash: HashOf::from_untyped_unchecked(maximum_hash),
                    executed_block_wire_hash: maximum_hash,
                    finality_artifact_hash: HashOf::from_untyped_unchecked(maximum_hash),
                    manifest_artifact_hash: HashOf::from_untyped_unchecked(maximum_hash),
                },
                receipt_artifact_hash: HashOf::from_untyped_unchecked(maximum_hash),
            },
            entries,
        };
        let encoded_len = norito::encode_canonical(&maximum_intent)?.len();
        if encoded_len == 0 || encoded_len > shared_budget {
            return Err(Error::PruneIntentConflict(
                "configured Native AMX evidence retention encodes a prune journal larger than the shared sidecar budget"
                    .to_owned(),
            ));
        }
        Ok(encoded_len)
    }
    fn native_amx_evidence_prune_intent_max_bytes(&self) -> usize {
        self.native_amx_evidence_prune_intent_max_bytes
    }
    fn lane_storage_entries_from_config(
        lane_config: &LaneConfig,
    ) -> BTreeMap<LaneId, LaneConfigEntry> {
        lane_config
            .entries()
            .iter()
            .cloned()
            .map(|entry| (entry.lane_id, entry))
            .collect()
    }
    #[cfg(test)]
    fn set_lane_storage_entry(&self, entry: &LaneConfigEntry) {
        self.lane_storage_entries
            .lock()
            .insert(entry.lane_id, entry.clone());
    }
    #[cfg(test)]
    fn remove_lane_storage_entry(&self, lane_id: LaneId) {
        self.lane_storage_entries.lock().remove(&lane_id);
    }
    fn lane_storage_entry(&self, lane_id: LaneId) -> Result<LaneConfigEntry> {
        self.lane_storage_entries
            .lock()
            .get(&lane_id)
            .cloned()
            .ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        format!("no Kura storage segment configured for lane {lane_id:?}"),
                    ),
                    self.store_root
                        .join("blocks")
                        .join(format!("lane_{:03}", lane_id.as_u32())),
                )
            })
    }
    fn ensure_lane_directories(
        store_dir: &Path,
        lane_config: &LaneConfig,
        active_blocks_dir: &Path,
        active_merge_path: &Path,
    ) -> Result<()> {
        let primary_lane = lane_config.primary().lane_id;
        for entry in lane_config.entries() {
            // The primary binding was already resolved from the durable geometry journal and
            // opened above. Recreating its configured alias here would resurrect the stale side
            // of an interrupted relabel and make the next recovery ambiguous.
            let is_primary = entry.lane_id == primary_lane;
            let blocks_dir = if is_primary {
                active_blocks_dir.to_path_buf()
            } else {
                entry.blocks_dir(store_dir)
            };
            if !is_primary && blocks_dir.as_path() != active_blocks_dir {
                std::fs::create_dir_all(&blocks_dir)
                    .map_err(|err| Error::MkDir(err, blocks_dir.clone()))?;
            }
            let lane_artifacts_dir = Self::lane_artifact_dir(&blocks_dir);
            std::fs::create_dir_all(&lane_artifacts_dir)
                .map_err(|err| Error::MkDir(err, lane_artifacts_dir))?;
            if is_primary {
                continue;
            }
            let merge_path = entry.merge_log_path(store_dir);
            if merge_path.as_path() != active_merge_path {
                if let Some(parent) = merge_path.parent() {
                    std::fs::create_dir_all(parent)
                        .map_err(|err| Error::MkDir(err, parent.to_path_buf()))?;
                }
                if !merge_path.exists() {
                    FileWrap::open_with(merge_path.clone(), |opts| {
                        opts.read(true).write(true).create(true).append(true);
                    })?;
                }
            }
        }
        Ok(())
    }
    /// Provision an unauthenticated lane-storage fixture for unit tests.
    ///
    /// Production topology changes must use the authenticated geometry journal.
    /// This helper is absent from release builds and exists only for consensus
    /// tests whose subject is unrelated to storage lifecycle authentication.
    ///
    /// # Errors
    /// Returns an [`Error`] if preparing or retiring storage directories fails for any entry.
    #[cfg(test)]
    pub(crate) fn reconcile_lane_segments_for_testing(
        &self,
        added: &[&LaneConfigEntry],
        retired: &[&LaneConfigEntry],
        replacements: &[(&LaneConfigEntry, &LaneConfigEntry)],
    ) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        if self.store_root.as_os_str().is_empty() {
            return Ok(());
        }
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        let mut changed = false;
        for (previous, _) in replacements {
            self.retire_lane_storage(previous)?;
            self.remove_lane_storage_entry(previous.lane_id);
            changed = true;
        }
        for entry in added {
            self.prepare_lane_storage_resolved(entry)?;
            self.set_lane_storage_entry(entry);
            changed = true;
        }
        for (_, current) in replacements {
            self.prepare_lane_storage_resolved(current)?;
            self.set_lane_storage_entry(current);
            changed = true;
        }
        for entry in retired {
            self.retire_lane_storage(entry)?;
            self.remove_lane_storage_entry(entry.lane_id);
            changed = true;
        }
        if changed {
            if let Err(err) = self.refresh_disk_usage_bytes() {
                warn!(
                    ?err,
                    "failed to refresh disk usage after lane reconciliation"
                );
            }
        }
        Ok(())
    }
    /// Restore the effective lane catalog recorded in a trusted WSV snapshot.
    ///
    /// Kura is opened before the WSV snapshot is decoded, so its in-memory lane
    /// map initially reflects static configuration. This operation provisions all
    /// snapshot lanes and atomically replaces that map without archiving inactive
    /// static-config directories; those directories may contain data needed for an
    /// operator-directed rollback. The primary lane must retain the active block
    /// and merge-log paths selected when Kura was opened.
    ///
    /// # Errors
    /// Returns an [`Error`] if the snapshot changes the active primary storage
    /// paths or any restored lane storage cannot be validated or provisioned.
    pub fn restore_lane_segments(&self, lane_config: &LaneConfig) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let restored_entries = Self::lane_storage_entries_from_config(lane_config);
        if self.store_root.as_os_str().is_empty() {
            *self.lane_storage_entries.lock() = restored_entries;
            return Ok(());
        }
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        let primary = lane_config.primary();
        let primary_blocks_dir = primary.blocks_dir(&self.store_root);
        let active_blocks_dir = self.active_blocks_dir.lock().clone();
        if primary_blocks_dir != active_blocks_dir {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "snapshot primary lane block path differs from the active Kura path",
                ),
                primary_blocks_dir,
            ));
        }
        let primary_merge_path = primary.merge_log_path(&self.store_root);
        let active_merge_path = self.active_merge_path.lock().clone();
        if primary_merge_path != active_merge_path {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "snapshot primary lane merge path differs from the active Kura path",
                ),
                primary_merge_path,
            ));
        }
        for entry in lane_config.entries() {
            self.preflight_prepare_lane_storage(entry)?;
        }
        for entry in lane_config.entries() {
            self.prepare_lane_storage_resolved(entry)?;
        }
        *self.lane_storage_entries.lock() = restored_entries;
        drop(_canonical_chain_guard);
        drop(_prune_guard);
        if self.emergency_fast_startup_enabled() {
            warn!(
                "Kura emergency Fast mode skipped historical lane repair and capacity audits after snapshot lane restore"
            );
            return Ok(());
        }
        self.recover_lane_block_execution_input_pairs_on_startup()?;
        self.reconcile_historical_autonomous_recovery_atomic_temps_on_startup()?;
        self.rebuild_post_wsv_lane_artifact_budget_reservations_on_startup()?;
        self.rebuild_certified_bundle_capacity_reservations_on_startup()?;
        self.repair_lane_merge_application_frontiers_on_startup()?;
        self.rebuild_autonomous_lane_route_latest_attempt_indexes_on_startup()?;
        self.repair_autonomous_lane_merge_bundles_on_startup()?;
        self.rebuild_native_amx_participant_receipt_latest_indexes_on_startup()?;
        self.validate_configured_kura_capacity_after_startup_recovery()?;
        if let Err(err) = self.refresh_disk_usage_bytes() {
            warn!(
                ?err,
                "failed to refresh disk usage after snapshot lane restore"
            );
        }
        Ok(())
    }
    /// Restore snapshot lane storage at an exact committed transition height
    /// and retained-lineage commitment.
    pub(crate) fn restore_lane_segments_with_geometry_at_height_and_lineage_root(
        &self,
        lane_config: &LaneConfig,
        incarnations: &BTreeMap<LaneId, Hash>,
        activation_heights: &BTreeMap<LaneId, u64>,
        authoritative_height: u64,
        lineage_root: Hash,
    ) -> Result<()> {
        self.recover_lane_geometry_journal_at_height_with_lineage_root(
            lane_config,
            incarnations,
            activation_heights,
            authoritative_height,
            lineage_root,
        )?;
        self.finish_restored_lane_segments_with_geometry(lane_config)
    }
    /// Restore lane storage to the cursor before every transition at one committed height.
    ///
    /// Startup replay uses this for the genesis/configuration height, where more than one
    /// transition can legitimately share the same height and must be retried in journal order.
    pub(crate) fn restore_lane_segments_with_geometry_before_first_transition_at_height(
        &self,
        lane_config: &LaneConfig,
        incarnations: &BTreeMap<LaneId, Hash>,
        activation_heights: &BTreeMap<LaneId, u64>,
        lineage_root: Hash,
        transition_height: u64,
    ) -> Result<()> {
        self.recover_lane_geometry_journal_before_first_transition_at_height_with_lineage_root(
            lane_config,
            incarnations,
            activation_heights,
            lineage_root,
            transition_height,
        )?;
        self.finish_restored_lane_segments_with_geometry(lane_config)
    }
    fn finish_restored_lane_segments_with_geometry(&self, lane_config: &LaneConfig) -> Result<()> {
        if self.store_root.as_os_str().is_empty() {
            return Ok(());
        }
        let primary = lane_config.primary();
        let primary_blocks_dir = primary.blocks_dir(&self.store_root);
        if primary_blocks_dir != *self.active_blocks_dir.lock() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "recovered primary lane block path differs from the active Kura path",
                ),
                primary_blocks_dir,
            ));
        }
        let primary_merge_path = primary.merge_log_path(&self.store_root);
        if primary_merge_path != *self.active_merge_path.lock() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "recovered primary lane merge path differs from the active Kura path",
                ),
                primary_merge_path,
            ));
        }
        if self.emergency_fast_startup_enabled() {
            warn!(
                "Kura emergency Fast mode skipped historical lane repair and capacity audits after geometry restore"
            );
            return Ok(());
        }
        self.recover_lane_block_execution_input_pairs_on_startup()?;
        self.reconcile_historical_autonomous_recovery_atomic_temps_on_startup()?;
        self.rebuild_post_wsv_lane_artifact_budget_reservations_on_startup()?;
        self.rebuild_certified_bundle_capacity_reservations_on_startup()?;
        self.repair_lane_merge_application_frontiers_on_startup()?;
        self.rebuild_autonomous_lane_route_latest_attempt_indexes_on_startup()?;
        self.repair_autonomous_lane_merge_bundles_on_startup()?;
        self.rebuild_native_amx_participant_receipt_latest_indexes_on_startup()?;
        self.validate_configured_kura_capacity_after_startup_recovery()?;
        if let Err(err) = self.refresh_disk_usage_bytes() {
            warn!(
                ?err,
                "failed to refresh disk usage after journaled snapshot lane restore"
            );
        }
        Ok(())
    }
    /// Validate lane storage topology changes that can fail without mutating Kura state.
    ///
    /// This catches deterministic path-shape conflicts before callers reconcile
    /// other lane-scoped storage backends.
    ///
    /// # Errors
    /// Returns an [`Error`] if an existing file or directory would make lane
    /// storage provisioning, retirement, or relabeling fail.
    pub fn preflight_lane_segments(
        &self,
        added: &[&LaneConfigEntry],
        retired: &[&LaneConfigEntry],
        replacements: &[(&LaneConfigEntry, &LaneConfigEntry)],
        relabelled: &[(&LaneConfigEntry, &LaneConfigEntry)],
    ) -> Result<()> {
        if self.store_root.as_os_str().is_empty() {
            return Ok(());
        }
        for (previous, current) in replacements {
            self.preflight_replace_lane_storage(previous, current)?;
        }
        for entry in added {
            self.preflight_prepare_lane_storage(entry)?;
        }
        for entry in retired {
            self.preflight_retire_lane_storage(entry)?;
        }
        for (previous, current) in relabelled {
            self.preflight_relabel_lane_storage(previous, current)?;
        }
        Ok(())
    }
    fn preflight_replace_lane_storage(
        &self,
        previous: &LaneConfigEntry,
        current: &LaneConfigEntry,
    ) -> Result<()> {
        self.preflight_retire_lane_storage(previous)?;
        let old_dir = previous.blocks_dir(&self.store_root);
        let new_dir = current.blocks_dir(&self.store_root);
        if old_dir != new_dir && new_dir.exists() {
            return Err(Error::MkDir(
                std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    "lane storage replacement target already exists",
                ),
                new_dir,
            ));
        }
        let old_merge = previous.merge_log_path(&self.store_root);
        let new_merge = current.merge_log_path(&self.store_root);
        if old_merge != new_merge && new_merge.exists() {
            return Err(Error::IO(
                std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    "lane merge-ledger replacement target already exists",
                ),
                new_merge,
            ));
        }
        self.preflight_prepare_lane_storage(current)
    }
    /// Test the low-level rollback mechanics for a direct lane-path move.
    ///
    /// Production relabels exclusively use the durable lane-geometry journal; this helper is not
    /// compiled into a node binary and cannot create an unjournaled first-release path.
    ///
    /// # Errors
    /// Returns an error if preparing lane storage, creating directories, renaming,
    /// or retargeting the block store fails.
    #[cfg(test)]
    fn relabel_lane_segments(
        &self,
        migrations: &[(&LaneConfigEntry, &LaneConfigEntry)],
    ) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        if self.store_root.as_os_str().is_empty() {
            return Ok(());
        }
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        for (previous, current) in migrations {
            self.preflight_relabel_lane_storage(previous, current)?;
        }
        // Provisioning an entirely absent prior path is not a rename and can be
        // completed before taking the block-store writer lock. A lone prior merge
        // log is inconsistent and must not be silently orphaned.
        let mut moves = Vec::new();
        for (previous, current) in migrations {
            let old_dir = previous.blocks_dir(&self.store_root);
            let new_dir = current.blocks_dir(&self.store_root);
            let old_merge = previous.merge_log_path(&self.store_root);
            let new_merge = current.merge_log_path(&self.store_root);
            if old_dir == new_dir && old_merge == new_merge {
                self.set_lane_storage_entry(current);
                continue;
            }
            if !old_dir.exists() {
                if old_merge.exists() {
                    return Err(Error::IO(
                        std::io::Error::new(
                            ErrorKind::InvalidData,
                            "lane relabel found a merge log without its prior block directory",
                        ),
                        old_merge,
                    ));
                }
                self.prepare_lane_storage_resolved(current)?;
                self.set_lane_storage_entry(current);
                continue;
            }
            moves.push((*previous, *current));
        }
        let _write_guard = self.block_store_write_lock.lock();
        let mut merge_log = self.merge_log.lock();
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        for (previous, current) in moves {
            let old_dir = previous.blocks_dir(&self.store_root);
            let new_dir = current.blocks_dir(&self.store_root);
            let old_merge = previous.merge_log_path(&self.store_root);
            let new_merge = current.merge_log_path(&self.store_root);
            if let Some(parent) = new_dir.parent() {
                create_dir_all_with_context(parent)?;
            }
            let active_blocks = *self.active_blocks_dir.lock() == old_dir;
            let active_merge = *self.active_merge_path.lock() == old_merge;
            let mut block_store = active_blocks.then(|| self.block_store.lock());
            if let Some(store) = block_store.as_mut() {
                store.drop_cached_handles();
            }
            let mut canonical_path_moved = false;
            let move_result: Result<()> = (|| {
                if old_dir != new_dir {
                    std::fs::rename(&old_dir, &new_dir)
                        .map_err(|err| Error::IO(err, old_dir.clone()))?;
                    canonical_path_moved = true;
                    let new_parent = new_dir.parent();
                    let old_parent = old_dir.parent();
                    if let Some(parent) = new_parent {
                        sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
                    }
                    if let Some(parent) = old_parent
                        && Some(parent) != new_parent
                    {
                        sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
                    }
                    #[cfg(test)]
                    if self
                        .fail_next_relabel_after_block_move
                        .swap(false, Ordering::AcqRel)
                    {
                        return Err(Error::IO(
                            std::io::Error::other(
                                "injected direct lane-relabel failure after block move",
                            ),
                            new_dir.clone(),
                        ));
                    }
                }
                if old_merge != new_merge {
                    canonical_path_moved |= old_merge.exists();
                    self.relabel_merge_log(previous, current)?;
                }
                Ok(())
            })();
            if let Err(error) = move_result {
                if canonical_path_moved {
                    let restoration = (|| {
                        if old_merge != new_merge {
                            match (old_merge.exists(), new_merge.exists()) {
                                (false, true) => std::fs::rename(&new_merge, &old_merge)
                                    .map_err(|restore| Error::IO(restore, new_merge.clone()))?,
                                (true, false) => {}
                                _ => {
                                    return Err(Error::IO(
                                        std::io::Error::new(
                                            ErrorKind::InvalidData,
                                            "lane merge-log rollback has an ambiguous path state",
                                        ),
                                        old_merge.clone(),
                                    ));
                                }
                            }
                        }
                        if old_dir != new_dir {
                            match (old_dir.exists(), new_dir.exists()) {
                                (false, true) => std::fs::rename(&new_dir, &old_dir)
                                    .map_err(|restore| Error::IO(restore, new_dir.clone()))?,
                                (true, false) => {}
                                _ => {
                                    return Err(Error::IO(
                                        std::io::Error::new(
                                            ErrorKind::InvalidData,
                                            "lane block-directory rollback has an ambiguous path state",
                                        ),
                                        old_dir.clone(),
                                    ));
                                }
                            }
                        }
                        for parent in [
                            old_dir.parent(),
                            new_dir.parent(),
                            old_merge.parent(),
                            new_merge.parent(),
                        ]
                        .into_iter()
                        .flatten()
                        {
                            sync_dir(parent)
                                .map_err(|restore| Error::IO(restore, parent.to_path_buf()))?;
                        }
                        Ok(())
                    })();
                    if let Err(restoration) = restoration {
                        let poison = Error::LaneGeometryPublicationRestoreFailed {
                            publication: error.to_string(),
                            restoration: restoration.to_string(),
                        };
                        drop(block_store);
                        drop(merge_log);
                        self.poison_canonical_storage("lane storage relabel rollback", &poison);
                        return Err(Error::CanonicalStoragePoisoned);
                    }
                }
                return Err(error);
            }
            if let Some(store) = block_store.as_mut() {
                store.retarget_existing_path(new_dir.clone());
                *self.active_blocks_dir.lock() = new_dir.clone();
                self.invalidate_durable_budget_snapshot();
            }
            if active_merge {
                if let Some(file) = merge_log.file.as_mut() {
                    file.path.clone_from(&new_merge);
                }
                *self.active_merge_path.lock() = new_merge.clone();
            }
            if old_dir != new_dir {
                let mut plain_text = self.block_plain_text_path.lock();
                if let Some(path) = plain_text.as_mut()
                    && let Ok(suffix) = path.strip_prefix(&old_dir)
                {
                    *path = new_dir.join(suffix);
                }
            }
            self.set_lane_storage_entry(current);
            iroha_logger::info!(
                lane = %current.lane_id.as_u32(),
                alias_before = previous.alias,
                alias_after = current.alias,
                source = %old_dir.display(),
                target = %new_dir.display(),
                "lane storage relabelled to match updated alias"
            );
        }
        accounting_mutation.finish();
        Ok(())
    }
    #[cfg(test)]
    fn relabel_merge_log(
        &self,
        previous: &LaneConfigEntry,
        current: &LaneConfigEntry,
    ) -> Result<()> {
        let old_path = previous.merge_log_path(&self.store_root);
        let new_path = current.merge_log_path(&self.store_root);
        if old_path == new_path {
            return Ok(());
        }
        if !old_path.exists() {
            if let Some(parent) = new_path.parent() {
                create_dir_all_with_context(parent)?;
            }
            if !new_path.exists() {
                FileWrap::open_with(new_path.clone(), |opts| {
                    opts.read(true).write(true).create(true).append(true);
                })?;
            }
            return Ok(());
        }
        if let Some(parent) = new_path.parent() {
            create_dir_all_with_context(parent)?;
        }
        if new_path.exists() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::AlreadyExists,
                    "lane merge-ledger relabel target already exists",
                ),
                new_path,
            ));
        }
        std::fs::rename(&old_path, &new_path).map_err(|err| Error::IO(err, old_path.clone()))?;
        let new_parent = new_path.parent();
        let old_parent = old_path.parent();
        if let Some(parent) = new_parent {
            sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
        }
        if let Some(parent) = old_parent {
            if Some(parent) != new_parent {
                sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
            }
        }
        iroha_logger::info!(
            lane = %current.lane_id.as_u32(),
            alias_before = previous.alias,
            alias_after = current.alias,
            source = %old_path.display(),
            target = %new_path.display(),
            "lane merge-ledger relabelled"
        );
        Ok(())
    }
    fn prepare_lane_storage_resolved(&self, entry: &LaneConfigEntry) -> Result<()> {
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let blocks_dir = entry.blocks_dir(&self.store_root);
        let active = {
            let active_dir = self.active_blocks_dir.lock();
            blocks_dir == *active_dir
        };
        if active {
            let _write_guard = self.block_store_write_lock.lock();
            self.block_store
                .lock()
                .create_files_if_they_do_not_exist()?;
        } else {
            let mut block_store = BlockStore::new(&blocks_dir);
            block_store.create_files_if_they_do_not_exist()?;
        }
        create_dir_all_with_context(&Self::lane_artifact_dir(&blocks_dir))?;
        let merge_path = entry.merge_log_path(&self.store_root);
        if let Some(parent) = merge_path.parent() {
            create_dir_all_with_context(parent)?;
        }
        if !merge_path.exists() {
            FileWrap::open_with(merge_path.clone(), |opts| {
                opts.read(true).write(true).create(true).append(true);
            })?;
        }
        iroha_logger::info!(
            lane = %entry.lane_id.as_u32(),
            alias = entry.alias,
            blocks = %blocks_dir.display(),
            merge = %merge_path.display(),
            "lane storage provisioned"
        );
        accounting_mutation.finish();
        Ok(())
    }
    fn preflight_prepare_lane_storage(&self, entry: &LaneConfigEntry) -> Result<()> {
        let blocks_dir = entry.blocks_dir(&self.store_root);
        Self::preflight_dir_path(&blocks_dir)?;
        Self::preflight_dir_path(&Self::lane_artifact_dir(&blocks_dir))?;
        for name in [INDEX_FILE_NAME, DATA_FILE_NAME, HASHES_FILE_NAME] {
            Self::preflight_file_path(&blocks_dir.join(name))?;
        }
        let merge_path = entry.merge_log_path(&self.store_root);
        if let Some(parent) = merge_path.parent() {
            Self::preflight_dir_path(parent)?;
        }
        Self::preflight_file_path(&merge_path)?;
        Ok(())
    }
    fn preflight_retire_lane_storage(&self, entry: &LaneConfigEntry) -> Result<()> {
        if self.auxiliary_history_deferred {
            return Err(Error::EmergencyFastAuxiliaryUnavailable {
                subsystem: "certified-bundle capacity reservations",
            });
        }
        self.ensure_lane_has_no_certified_bundle_capacity_reservation(entry)?;
        let blocks_dir = entry.blocks_dir(&self.store_root);
        if blocks_dir == *self.active_blocks_dir.lock() {
            return Ok(());
        }
        let merge_path = entry.merge_log_path(&self.store_root);
        if merge_path == *self.active_merge_path.lock() {
            return Ok(());
        }
        let retired_root = self.store_root.join("retired");
        Self::preflight_dir_path(&retired_root.join("blocks"))?;
        Self::preflight_dir_path(&retired_root.join("merge_ledger"))?;
        Ok(())
    }
    fn preflight_relabel_lane_storage(
        &self,
        previous: &LaneConfigEntry,
        current: &LaneConfigEntry,
    ) -> Result<()> {
        let old_dir = previous.blocks_dir(&self.store_root);
        let new_dir = current.blocks_dir(&self.store_root);
        let old_merge = previous.merge_log_path(&self.store_root);
        if old_dir == new_dir {
            return self.preflight_relabel_merge_log(previous, current);
        }
        if !old_dir.exists() {
            if old_merge.exists() {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "lane relabel found a merge log without its prior block directory",
                    ),
                    old_merge,
                ));
            }
            self.preflight_prepare_lane_storage(current)?;
            return Ok(());
        }
        if let Some(parent) = new_dir.parent() {
            Self::preflight_dir_path(parent)?;
        }
        if new_dir.exists() {
            return Err(Error::MkDir(
                std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    "lane storage relabel target already exists",
                ),
                new_dir,
            ));
        }
        self.preflight_relabel_merge_log(previous, current)
    }
    fn preflight_relabel_merge_log(
        &self,
        previous: &LaneConfigEntry,
        current: &LaneConfigEntry,
    ) -> Result<()> {
        let old_path = previous.merge_log_path(&self.store_root);
        let new_path = current.merge_log_path(&self.store_root);
        if old_path == new_path {
            return Ok(());
        }
        if let Some(parent) = new_path.parent() {
            Self::preflight_dir_path(parent)?;
        }
        if !old_path.exists() {
            Self::preflight_file_path(&new_path)?;
            return Ok(());
        }
        if new_path.exists() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::AlreadyExists,
                    "lane merge-ledger relabel target already exists",
                ),
                new_path,
            ));
        }
        Ok(())
    }
    fn preflight_dir_path(path: &Path) -> Result<()> {
        if path.exists() && !path.is_dir() {
            return Err(Error::MkDir(
                std::io::Error::new(std::io::ErrorKind::AlreadyExists, "expected directory path"),
                path.to_path_buf(),
            ));
        }
        Ok(())
    }
    fn preflight_file_path(path: &Path) -> Result<()> {
        if path.exists() && !path.is_file() {
            return Err(Error::IO(
                std::io::Error::new(std::io::ErrorKind::AlreadyExists, "expected file path"),
                path.to_path_buf(),
            ));
        }
        Ok(())
    }
    #[cfg(test)]
    fn retire_lane_storage(&self, entry: &LaneConfigEntry) -> Result<()> {
        let blocks_dir = entry.blocks_dir(&self.store_root);
        {
            let active_dir = self.active_blocks_dir.lock();
            if blocks_dir == *active_dir {
                iroha_logger::warn!(
                    lane = %entry.lane_id.as_u32(),
                    alias = entry.alias,
                    "skipping retirement of active lane block directory"
                );
                return Ok(());
            }
        }
        let merge_path = entry.merge_log_path(&self.store_root);
        if merge_path == *self.active_merge_path.lock() {
            iroha_logger::warn!(
                lane = %entry.lane_id.as_u32(),
                alias = entry.alias,
                "skipping retirement of active lane merge log"
            );
            return Ok(());
        }
        let retired_root = self.store_root.join("retired");
        let retired_blocks_root = retired_root.join("blocks");
        let retired_merge_root = retired_root.join("merge_ledger");
        create_dir_all_with_context(&retired_blocks_root)?;
        create_dir_all_with_context(&retired_merge_root)?;
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        if blocks_dir.exists() {
            let dest = unique_retired_path(&retired_blocks_root, &entry.kura_segment, None::<&str>);
            std::fs::rename(&blocks_dir, &dest)
                .map_err(|err| Error::IO(err, blocks_dir.clone()))?;
            let dest_parent = dest.parent();
            let blocks_parent = blocks_dir.parent();
            if let Some(parent) = dest_parent {
                sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
            }
            if let Some(parent) = blocks_parent {
                if Some(parent) != dest_parent {
                    sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
                }
            }
            iroha_logger::info!(
                lane = %entry.lane_id.as_u32(),
                alias = entry.alias,
                source = %blocks_dir.display(),
                target = %dest.display(),
                "retired lane block directory"
            );
        }
        if merge_path.exists() {
            let dest = unique_retired_path(&retired_merge_root, &entry.merge_segment, Some("log"));
            std::fs::rename(&merge_path, &dest)
                .map_err(|err| Error::IO(err, merge_path.clone()))?;
            let dest_parent = dest.parent();
            let merge_parent = merge_path.parent();
            if let Some(parent) = dest_parent {
                sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
            }
            if let Some(parent) = merge_parent {
                if Some(parent) != dest_parent {
                    sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
                }
            }
            iroha_logger::info!(
                lane = %entry.lane_id.as_u32(),
                alias = entry.alias,
                source = %merge_path.display(),
                target = %dest.display(),
                "retired lane merge log"
            );
        }
        accounting_mutation.finish();
        Ok(())
    }
    /// Append a merge-ledger entry without its mandatory global carrier block for focused tests.
    ///
    /// # Errors
    /// Returns an error if the merge-ledger entry cannot be persisted.
    #[cfg(test)]
    pub(crate) fn append_merge_entry_for_test(&self, entry: &MergeLedgerEntry) -> Result<()> {
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        self.append_merge_entry_after_storage_resolution(entry)
    }
    #[cfg(test)]
    fn append_merge_entry_after_storage_resolution(&self, entry: &MergeLedgerEntry) -> Result<()> {
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let appended = self.merge_log.lock().append(entry)?;
        if appended && !self.store_root.as_os_str().is_empty() {
            let bytes = Self::merge_entry_bytes(entry)?;
            self.add_disk_usage_bytes(bytes);
        }
        accounting_mutation.finish();
        Ok(())
    }
    fn merge_carrier_dir(&self) -> PathBuf {
        self.store_root.join(MERGE_CARRIERS_DIR)
    }
    fn merge_carrier_path(&self, block_height: u64) -> PathBuf {
        self.merge_carrier_dir()
            .join(format!("{block_height}.norito"))
    }
    #[cfg(unix)]
    fn sidecar_metadata_same_object(left: &SecureMetadata, right: &SecureMetadata) -> bool {
        use std::os::unix::fs::MetadataExt as _;
        left.dev() == right.dev() && left.ino() == right.ino()
    }
    #[cfg(windows)]
    fn sidecar_metadata_same_object(left: &SecureMetadata, right: &SecureMetadata) -> bool {
        left.volume_serial_number() == right.volume_serial_number()
            && left.file_index() == right.file_index()
            && left.volume_serial_number().is_some()
            && left.file_index().is_some()
    }
    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_metadata_same_object(_left: &SecureMetadata, _right: &SecureMetadata) -> bool {
        false
    }
    #[cfg(unix)]
    fn sidecar_file_metadata_unchanged(left: &SecureMetadata, right: &SecureMetadata) -> bool {
        use std::os::unix::fs::MetadataExt as _;
        Self::sidecar_metadata_same_object(left, right)
            && left.nlink() == 1
            && right.nlink() == 1
            && left.len() == right.len()
            && left.mtime() == right.mtime()
            && left.mtime_nsec() == right.mtime_nsec()
            && left.ctime() == right.ctime()
            && left.ctime_nsec() == right.ctime_nsec()
    }
    #[cfg(unix)]
    fn sidecar_file_metadata_unchanged_across_rename(
        left: &SecureMetadata,
        right: &SecureMetadata,
    ) -> bool {
        use std::os::unix::fs::MetadataExt as _;
        // Renaming the bound object legitimately advances ctime. Preserve the
        // exact-object, link-count, length, and content-mtime checks that detect
        // replacement or concurrent writes across quarantine publication.
        Self::sidecar_metadata_same_object(left, right)
            && left.nlink() == 1
            && right.nlink() == 1
            && left.len() == right.len()
            && left.mtime() == right.mtime()
            && left.mtime_nsec() == right.mtime_nsec()
    }
    #[cfg(unix)]
    fn sidecar_directory_metadata_unchanged(left: &SecureMetadata, right: &SecureMetadata) -> bool {
        use std::os::unix::fs::MetadataExt as _;
        Self::sidecar_metadata_same_object(left, right)
            && left.mtime() == right.mtime()
            && left.mtime_nsec() == right.mtime_nsec()
            && left.ctime() == right.ctime()
            && left.ctime_nsec() == right.ctime_nsec()
    }
    #[cfg(windows)]
    fn sidecar_directory_metadata_unchanged(left: &SecureMetadata, right: &SecureMetadata) -> bool {
        Self::sidecar_metadata_same_object(left, right)
            && left.last_write_time() == right.last_write_time()
            && left.creation_time() == right.creation_time()
    }
    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_directory_metadata_unchanged(
        _left: &SecureMetadata,
        _right: &SecureMetadata,
    ) -> bool {
        false
    }
    fn sidecar_directory_binding_unchanged(left: &SecureMetadata, right: &SecureMetadata) -> bool {
        // Directory mtime/ctime describe mutations to child entries, not replacement of the
        // directory itself. Progress sidecars are published concurrently, so descriptor binding
        // must compare object identity only. Stable inventory scans deliberately retain the
        // stronger timestamp comparison in `sidecar_directory_metadata_unchanged`.
        Self::sidecar_metadata_same_object(left, right)
    }
    #[cfg(windows)]
    fn sidecar_file_metadata_unchanged(left: &SecureMetadata, right: &SecureMetadata) -> bool {
        Self::sidecar_metadata_same_object(left, right)
            && left.number_of_links() == Some(1)
            && right.number_of_links() == Some(1)
            && left.file_size() == right.file_size()
            && left.last_write_time() == right.last_write_time()
            && left.creation_time() == right.creation_time()
    }
    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_file_metadata_unchanged(left: &SecureMetadata, right: &SecureMetadata) -> bool {
        Self::sidecar_metadata_same_object(left, right)
            && left.len() == right.len()
            && left.modified().ok() == right.modified().ok()
    }
    fn stable_sidecar_metadata_unchanged(
        left: &StableSidecarMetadata,
        right: &StableSidecarMetadata,
    ) -> bool {
        left.canonical_path == right.canonical_path
            && Self::sidecar_file_metadata_unchanged(&left.file, &right.file)
            && Self::sidecar_directory_metadata_unchanged(&left.directory, &right.directory)
    }
    fn stable_sidecar_file_binding_unchanged(
        left: &StableSidecarMetadata,
        right: &StableSidecarMetadata,
    ) -> bool {
        // A sibling publication legitimately advances the directory timestamps
        // without changing this file. Single-file reads bind the directory by
        // object identity; inventory scans use the stronger timestamp check in
        // `stable_sidecar_metadata_unchanged` to detect sibling mutations.
        left.canonical_path == right.canonical_path
            && Self::sidecar_file_metadata_unchanged(&left.file, &right.file)
            && Self::sidecar_directory_binding_unchanged(&left.directory, &right.directory)
    }
    fn stable_sidecar_directory_metadata_unchanged(
        left: &StableSidecarDirectoryMetadata,
        right: &StableSidecarDirectoryMetadata,
    ) -> bool {
        if left.expected_path != right.expected_path || left.canonical_path != right.canonical_path
        {
            return false;
        }
        match (&left.metadata, &right.metadata) {
            (None, None) => true,
            (Some(left), Some(right)) => Self::sidecar_directory_metadata_unchanged(left, right),
            (None, Some(_)) | (Some(_), None) => false,
        }
    }
    #[cfg(unix)]
    fn sidecar_is_single_link(metadata: &SecureMetadata) -> bool {
        use std::os::unix::fs::MetadataExt as _;
        metadata.nlink() == 1
    }
    #[cfg(windows)]
    fn sidecar_is_single_link(metadata: &SecureMetadata) -> bool {
        metadata.number_of_links() == Some(1)
    }
    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_is_single_link(_metadata: &SecureMetadata) -> bool {
        false
    }
    #[cfg(unix)]
    fn sidecar_has_link_count(metadata: &SecureMetadata, expected: u64) -> bool {
        use std::os::unix::fs::MetadataExt as _;
        metadata.nlink() == expected
    }
    #[cfg(windows)]
    fn sidecar_has_link_count(metadata: &SecureMetadata, expected: u64) -> bool {
        u32::try_from(expected)
            .ok()
            .is_some_and(|expected| metadata.number_of_links() == Some(expected))
    }
    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_has_link_count(_metadata: &SecureMetadata, _expected: u64) -> bool {
        false
    }
    fn canonical_sidecar_directory_for(
        store_root: &Path,
        expected_directory: &Path,
    ) -> Result<Option<(PathBuf, SecureMetadata)>> {
        let before = match secure_file_metadata::from_path(expected_directory) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(Error::IO(error, expected_directory.to_path_buf())),
        };
        if before.file_type().is_symlink() || !before.is_dir() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar directory is not a direct directory",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        let relative = expected_directory.strip_prefix(store_root).map_err(|_| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar directory is outside the configured Kura root",
                ),
                expected_directory.to_path_buf(),
            )
        })?;
        let canonical_root = std::fs::canonicalize(store_root)
            .map_err(|error| Error::IO(error, store_root.to_path_buf()))?;
        let canonical_directory = std::fs::canonicalize(expected_directory)
            .map_err(|error| Error::IO(error, expected_directory.to_path_buf()))?;
        if canonical_directory != canonical_root.join(relative) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar directory contains a symlink or escapes the Kura root",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        let after = secure_file_metadata::from_path(expected_directory)
            .map_err(|error| Error::IO(error, expected_directory.to_path_buf()))?;
        if after.file_type().is_symlink()
            || !after.is_dir()
            || !Self::sidecar_directory_binding_unchanged(&before, &after)
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar directory changed during canonical validation",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        Ok(Some((canonical_directory, after)))
    }
    fn canonical_sidecar_directory(
        &self,
        expected_directory: &Path,
    ) -> Result<Option<(PathBuf, SecureMetadata)>> {
        Self::canonical_sidecar_directory_for(&self.store_root, expected_directory)
    }
    fn stable_sidecar_directory_metadata(
        &self,
        expected_directory: &Path,
    ) -> Result<StableSidecarDirectoryMetadata> {
        let current = self.canonical_sidecar_directory(expected_directory)?;
        Ok(StableSidecarDirectoryMetadata {
            expected_path: expected_directory.to_path_buf(),
            canonical_path: current.as_ref().map(|(path, _)| path.clone()),
            metadata: current.map(|(_, metadata)| metadata),
        })
    }
    fn stable_sidecar_directory_inventory(
        &self,
        expected_directory: &Path,
    ) -> Result<StableSidecarDirectoryInventory> {
        self.stable_sidecar_directory_inventory_with_recognized_child(expected_directory, None)
    }
    fn stable_sidecar_directory_inventory_with_recognized_child(
        &self,
        expected_directory: &Path,
        recognized_child: Option<&Path>,
    ) -> Result<StableSidecarDirectoryInventory> {
        if recognized_child.is_some_and(|child| child.parent() != Some(expected_directory)) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "recognized startup replay child is not direct",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        let before = self.stable_sidecar_directory_metadata(expected_directory)?;
        let mut files = BTreeMap::new();
        if before.metadata.is_some() {
            let entries = std::fs::read_dir(expected_directory)
                .map_err(|error| Error::IO(error, expected_directory.to_path_buf()))?;
            for entry in entries {
                let entry =
                    entry.map_err(|error| Error::IO(error, expected_directory.to_path_buf()))?;
                let path = entry.path();
                if recognized_child == Some(path.as_path()) {
                    self.canonical_sidecar_directory(&path)?.ok_or_else(|| {
                        Error::IO(
                            std::io::Error::new(
                                ErrorKind::InvalidData,
                                "recognized startup replay child directory disappeared during identity capture",
                            ),
                            path.clone(),
                        )
                    })?;
                    continue;
                }
                let metadata = self
                    .regular_sidecar_metadata(&path, expected_directory)?
                    .ok_or_else(|| {
                        Error::IO(
                            std::io::Error::new(
                                ErrorKind::InvalidData,
                                "startup replay sidecar disappeared during identity capture",
                            ),
                            path.clone(),
                        )
                    })?;
                files.insert(path, metadata);
            }
        }
        let after = self.stable_sidecar_directory_metadata(expected_directory)?;
        if !Self::stable_sidecar_directory_metadata_unchanged(&before, &after) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "startup replay sidecar directory changed during identity capture",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        Ok(StableSidecarDirectoryInventory {
            directory: after,
            files,
        })
    }
    fn stable_historical_autonomous_recovery_directory_inventory(
        &self,
        expected_directory: &Path,
        record_limit: usize,
        aggregate_byte_limit: u64,
    ) -> Result<(StableSidecarDirectoryInventory, usize, u64)> {
        let before = self.stable_sidecar_directory_metadata(expected_directory)?;
        let mut files = BTreeMap::new();
        let mut encoded_bytes = 0_u64;
        if before.metadata.is_some() {
            let (entries, bytes) = bounded_historical_autonomous_recovery_entries(
                expected_directory,
                record_limit,
                aggregate_byte_limit,
                |path| {
                    let metadata = self
                        .regular_sidecar_metadata(path, expected_directory)?
                        .ok_or_else(|| {
                            Error::IO(
                                std::io::Error::new(
                                    ErrorKind::InvalidData,
                                    "historical autonomous recovery sidecar disappeared during identity capture",
                                ),
                                path.to_path_buf(),
                            )
                        })?;
                    let file_metadata = metadata.file.clone();
                    Ok((metadata, file_metadata))
                },
            )?;
            encoded_bytes = bytes;
            files.extend(entries);
        }
        let after = self.stable_sidecar_directory_metadata(expected_directory)?;
        if !Self::stable_sidecar_directory_metadata_unchanged(&before, &after) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "historical autonomous recovery directory changed during identity capture",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        let record_count = files.len();
        Ok((
            StableSidecarDirectoryInventory {
                directory: after,
                files,
            },
            record_count,
            encoded_bytes,
        ))
    }
    fn stable_sidecar_directory_inventory_unchanged(
        left: &StableSidecarDirectoryInventory,
        right: &StableSidecarDirectoryInventory,
    ) -> bool {
        Self::stable_sidecar_directory_metadata_unchanged(&left.directory, &right.directory)
            && left.files.len() == right.files.len()
            && left.files.iter().all(|(path, metadata)| {
                right.files.get(path).is_some_and(|current| {
                    Self::stable_sidecar_metadata_unchanged(metadata, current)
                })
            })
    }
    fn regular_sidecar_metadata_for(
        store_root: &Path,
        path: &Path,
        expected_directory: &Path,
    ) -> Result<Option<StableSidecarMetadata>> {
        if path.parent() != Some(expected_directory) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path is not an immediate child of its expected directory",
                ),
                path.to_path_buf(),
            ));
        }
        let directory = Self::canonical_sidecar_directory_for(store_root, expected_directory)?;
        let metadata = match secure_file_metadata::from_path(path) {
            Ok(metadata) => metadata,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(None),
            Err(err) => return Err(Error::IO(err, path.to_path_buf())),
        };
        let Some((canonical_directory, directory_metadata)) = directory else {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar exists without its expected direct directory",
                ),
                path.to_path_buf(),
            ));
        };
        if !metadata.file_type().is_file()
            || metadata.file_type().is_symlink()
            || !Self::sidecar_is_single_link(&metadata)
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path is not a single-link regular file",
                ),
                path.to_path_buf(),
            ));
        }
        let canonical_path =
            std::fs::canonicalize(path).map_err(|err| Error::IO(err, path.to_path_buf()))?;
        if canonical_path.parent() != Some(canonical_directory.as_path()) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path escapes its canonical Kura directory",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some(StableSidecarMetadata {
            canonical_path,
            file: metadata,
            directory: directory_metadata,
        }))
    }
    fn regular_sidecar_metadata(
        &self,
        path: &Path,
        expected_directory: &Path,
    ) -> Result<Option<StableSidecarMetadata>> {
        Self::regular_sidecar_metadata_for(&self.store_root, path, expected_directory)
    }
    fn open_bound_progress_file(
        namespace: &BoundProgressNamespace,
        path: &Path,
        expected: &StableSidecarMetadata,
    ) -> Result<std::fs::File> {
        let immediate = namespace.directories.first().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "bound progress namespace has no immediate directory",
                ),
                path.to_path_buf(),
            )
        })?;
        if path.parent() != Some(immediate.expected_path.as_path()) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar file is outside its bound immediate directory",
                ),
                path.to_path_buf(),
            ));
        }
        let file_name = path.file_name().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar file has no entry name",
                ),
                path.to_path_buf(),
            )
        })?;
        #[cfg(unix)]
        let file = std::fs::File::from(
            rustix::fs::openat(
                &immediate.file,
                file_name,
                rustix::fs::OFlags::RDWR
                    | rustix::fs::OFlags::NOFOLLOW
                    | rustix::fs::OFlags::CLOEXEC,
                rustix::fs::Mode::empty(),
            )
            .map_err(std::io::Error::from)
            .map_err(|error| Error::IO(error, path.to_path_buf()))?,
        );
        #[cfg(not(unix))]
        let file = {
            let mut options = std::fs::OpenOptions::new();
            options.read(true).write(true);
            #[cfg(windows)]
            {
                use std::os::windows::fs::OpenOptionsExt as _;
                const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
                options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
            }
            options
                .open(path)
                .map_err(|error| Error::IO(error, path.to_path_buf()))?
        };
        let opened = secure_file_metadata::from_file(&file)
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        if !opened.is_file() || !Self::sidecar_file_metadata_unchanged(&expected.file, &opened) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar file changed while opening",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(file)
    }
    fn open_optional_bound_progress_file(
        &self,
        namespace: &BoundProgressNamespace,
        path: &Path,
    ) -> Result<Option<std::fs::File>> {
        let immediate = namespace.directories.first().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "bound progress namespace has no immediate directory",
                ),
                path.to_path_buf(),
            )
        })?;
        if path.parent() != Some(immediate.expected_path.as_path()) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar file is outside its bound immediate directory",
                ),
                path.to_path_buf(),
            ));
        }
        let Some(expected) =
            Self::regular_sidecar_metadata_for(&self.store_root, path, &immediate.expected_path)?
        else {
            if !Self::progress_mutation_namespace_unchanged(namespace) {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar namespace changed while proving an optional file absent",
                    ),
                    path.to_path_buf(),
                ));
            }
            return Ok(None);
        };
        if !Self::sidecar_metadata_same_object(&immediate.metadata, &expected.directory) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar directory changed while binding an optional file",
                ),
                path.to_path_buf(),
            ));
        }
        let file = Self::open_bound_progress_file(namespace, path, &expected)?;
        if !Self::progress_mutation_namespace_unchanged(namespace) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar namespace changed while binding an optional file",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some(file))
    }
    fn open_direct_sidecar_file_in_namespace(
        path: &Path,
        create: bool,
        append: bool,
        namespace: Option<&BoundProgressNamespace>,
    ) -> std::io::Result<std::fs::File> {
        let before = match secure_file_metadata::from_path(path) {
            Ok(metadata) => Some(metadata),
            Err(error) if error.kind() == ErrorKind::NotFound && create => None,
            Err(error) => return Err(error),
        };
        if before.as_ref().is_some_and(|metadata| {
            metadata.file_type().is_symlink()
                || !metadata.is_file()
                || !Self::sidecar_is_single_link(metadata)
        }) {
            return Err(std::io::Error::new(
                ErrorKind::InvalidData,
                "sidecar path is not a direct single-link regular file",
            ));
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::{MetadataExt as _, OpenOptionsExt as _};
            let parent_path = path.parent().ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "sidecar path has no parent")
            })?;
            let file_name = path.file_name().ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "sidecar path has no file name")
            })?;
            let owned_parent;
            let parent = if let Some(namespace) = namespace {
                let immediate = namespace.directories.first().ok_or_else(|| {
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "bound sidecar namespace has no immediate directory",
                    )
                })?;
                if parent_path != immediate.expected_path {
                    return Err(std::io::Error::new(
                        ErrorKind::InvalidData,
                        "sidecar path is outside its bound namespace",
                    ));
                }
                let opened = immediate.file.metadata()?;
                let current = std::fs::symlink_metadata(parent_path)?;
                if !opened.is_dir()
                    || current.file_type().is_symlink()
                    || !current.is_dir()
                    || !Self::sidecar_metadata_same_object(&immediate.metadata, &opened)
                    || !Self::sidecar_metadata_same_object(&immediate.metadata, &current)
                {
                    return Err(std::io::Error::new(
                        ErrorKind::InvalidData,
                        "bound sidecar namespace changed before mutation",
                    ));
                }
                &immediate.file
            } else {
                let parent_before = std::fs::symlink_metadata(parent_path)?;
                if parent_before.file_type().is_symlink() || !parent_before.is_dir() {
                    return Err(std::io::Error::new(
                        ErrorKind::InvalidData,
                        "sidecar parent is not a direct directory",
                    ));
                }
                let mut options = std::fs::OpenOptions::new();
                options.read(true).custom_flags(
                    (rustix::fs::OFlags::DIRECTORY
                        | rustix::fs::OFlags::NOFOLLOW
                        | rustix::fs::OFlags::CLOEXEC)
                        .bits() as i32,
                );
                owned_parent = options.open(parent_path)?;
                let parent_opened = owned_parent.metadata()?;
                let parent_after = std::fs::symlink_metadata(parent_path)?;
                if !parent_opened.is_dir()
                    || parent_after.file_type().is_symlink()
                    || !parent_after.is_dir()
                    || !Self::sidecar_metadata_same_object(&parent_before, &parent_opened)
                    || !Self::sidecar_metadata_same_object(&parent_before, &parent_after)
                {
                    return Err(std::io::Error::new(
                        ErrorKind::InvalidData,
                        "sidecar parent changed while binding it",
                    ));
                }
                &owned_parent
            };
            let mut flags = rustix::fs::OFlags::RDWR
                | rustix::fs::OFlags::NOFOLLOW
                | rustix::fs::OFlags::CLOEXEC;
            if create {
                flags |= rustix::fs::OFlags::CREATE;
            }
            if append {
                flags |= rustix::fs::OFlags::APPEND;
            }
            let file = std::fs::File::from(
                rustix::fs::openat(
                    parent,
                    file_name,
                    flags,
                    rustix::fs::Mode::RUSR | rustix::fs::Mode::WUSR,
                )
                .map_err(std::io::Error::from)?,
            );
            let opened = file.metadata()?;
            let after =
                rustix::fs::statat(parent, file_name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
                    .map_err(std::io::Error::from)?;
            if !opened.is_file()
                || !Self::sidecar_is_single_link(&opened)
                || after.st_dev as u64 != opened.dev()
                || after.st_ino as u64 != opened.ino()
                || after.st_nlink as u64 != 1
                || before
                    .as_ref()
                    .is_some_and(|metadata| !Self::sidecar_metadata_same_object(metadata, &opened))
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path identity changed while opening",
                ));
            }
            return Ok(file);
        }
        #[cfg(not(unix))]
        {
            let mut options = std::fs::OpenOptions::new();
            options.read(true).write(true).create(create).append(append);
            #[cfg(windows)]
            {
                use std::os::windows::fs::OpenOptionsExt as _;
                const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
                options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
            }
            let file = options.open(path)?;
            let opened = secure_file_metadata::from_file(&file)?;
            let after = secure_file_metadata::from_path(path)?;
            if !opened.is_file()
                || after.file_type().is_symlink()
                || !after.is_file()
                || !Self::sidecar_is_single_link(&opened)
                || !Self::sidecar_is_single_link(&after)
                || !Self::sidecar_metadata_same_object(&opened, &after)
                || before
                    .as_ref()
                    .is_some_and(|metadata| !Self::sidecar_metadata_same_object(metadata, &opened))
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path identity changed while opening",
                ));
            }
            Ok(file)
        }
    }
    fn remove_bound_progress_temp_if_present(
        namespace: &BoundProgressNamespace,
        path: &Path,
    ) -> std::io::Result<()> {
        let immediate = namespace.directories.first().ok_or_else(|| {
            std::io::Error::new(
                ErrorKind::InvalidData,
                "bound progress namespace has no immediate directory",
            )
        })?;
        if path.parent() != Some(immediate.expected_path.as_path()) {
            return Err(std::io::Error::new(
                ErrorKind::InvalidInput,
                "progress temp is outside its bound namespace",
            ));
        }
        let name = path.file_name().ok_or_else(|| {
            std::io::Error::new(ErrorKind::InvalidInput, "progress temp has no entry name")
        })?;
        #[cfg(unix)]
        {
            let entry = match rustix::fs::statat(
                &immediate.file,
                name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            ) {
                Ok(entry) => entry,
                Err(rustix::io::Errno::NOENT) => return Ok(()),
                Err(error) => return Err(std::io::Error::from(error)),
            };
            if rustix::fs::FileType::from_raw_mode(entry.st_mode)
                != rustix::fs::FileType::RegularFile
                || entry.st_nlink as u64 != 1
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp is not a direct single-link regular file",
                ));
            }
            rustix::fs::unlinkat(&immediate.file, name, rustix::fs::AtFlags::empty())
                .map_err(std::io::Error::from)?;
            return Ok(());
        }
        #[cfg(not(unix))]
        {
            match secure_file_metadata::from_path(path) {
                Ok(metadata)
                    if metadata.is_file()
                        && !metadata.file_type().is_symlink()
                        && Self::sidecar_is_single_link(&metadata) =>
                {
                    std::fs::remove_file(path)
                }
                Ok(_) => Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp is not a direct single-link regular file",
                )),
                Err(error) if error.kind() == ErrorKind::NotFound => Ok(()),
                Err(error) => Err(error),
            }
        }
    }
    fn remove_bound_progress_file_if_matches(
        namespace: &BoundProgressNamespace,
        path: &Path,
        expected: &std::fs::File,
        expected_snapshot: &StableSidecarMetadata,
    ) -> std::io::Result<()> {
        let immediate = namespace.directories.first().ok_or_else(|| {
            std::io::Error::new(
                ErrorKind::InvalidData,
                "bound progress namespace has no immediate directory",
            )
        })?;
        if path.parent() != Some(immediate.expected_path.as_path()) {
            return Err(std::io::Error::new(
                ErrorKind::InvalidInput,
                "progress file is outside its bound namespace",
            ));
        }
        let name = path.file_name().ok_or_else(|| {
            std::io::Error::new(ErrorKind::InvalidInput, "progress file has no entry name")
        })?;
        let expected_metadata = secure_file_metadata::from_file(expected)?;
        if !Self::sidecar_file_metadata_unchanged(&expected_snapshot.file, &expected_metadata) {
            return Err(std::io::Error::new(
                ErrorKind::InvalidData,
                "progress file changed after exact-object verification",
            ));
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt as _;
            let entry =
                rustix::fs::statat(&immediate.file, name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
                    .map_err(std::io::Error::from)?;
            if rustix::fs::FileType::from_raw_mode(entry.st_mode)
                != rustix::fs::FileType::RegularFile
                || expected_metadata.nlink() != 1
                || entry.st_dev as u64 != expected_snapshot.file.dev()
                || entry.st_ino as u64 != expected_snapshot.file.ino()
                || entry.st_nlink as u64 != 1
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress file changed before exact-object removal",
                ));
            }
            rustix::fs::unlinkat(&immediate.file, name, rustix::fs::AtFlags::empty())
                .map_err(std::io::Error::from)?;
            return Ok(());
        }
        #[cfg(not(unix))]
        {
            let current = secure_file_metadata::from_path(path)?;
            if current.file_type().is_symlink()
                || !current.is_file()
                || !Self::sidecar_is_single_link(&current)
                || !Self::sidecar_file_metadata_unchanged(&expected_snapshot.file, &current)
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress file changed before exact-object removal",
                ));
            }
            std::fs::remove_file(path)
        }
    }
    fn create_new_bound_progress_temp(
        namespace: &BoundProgressNamespace,
        path: &Path,
    ) -> std::io::Result<std::fs::File> {
        let immediate = namespace.directories.first().ok_or_else(|| {
            std::io::Error::new(
                ErrorKind::InvalidData,
                "bound progress namespace has no immediate directory",
            )
        })?;
        if path.parent() != Some(immediate.expected_path.as_path()) {
            return Err(std::io::Error::new(
                ErrorKind::InvalidInput,
                "progress temp is outside its bound namespace",
            ));
        }
        let name = path.file_name().ok_or_else(|| {
            std::io::Error::new(ErrorKind::InvalidInput, "progress temp has no entry name")
        })?;
        #[cfg(unix)]
        {
            let file = std::fs::File::from(
                rustix::fs::openat(
                    &immediate.file,
                    name,
                    rustix::fs::OFlags::RDWR
                        | rustix::fs::OFlags::CREATE
                        | rustix::fs::OFlags::EXCL
                        | rustix::fs::OFlags::NOFOLLOW
                        | rustix::fs::OFlags::CLOEXEC,
                    rustix::fs::Mode::RUSR | rustix::fs::Mode::WUSR,
                )
                .map_err(std::io::Error::from)?,
            );
            let metadata = secure_file_metadata::from_file(&file)?;
            let entry =
                rustix::fs::statat(&immediate.file, name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
                    .map_err(std::io::Error::from)?;
            use std::os::unix::fs::MetadataExt as _;
            if !metadata.is_file()
                || metadata.nlink() != 1
                || entry.st_dev as u64 != metadata.dev()
                || entry.st_ino as u64 != metadata.ino()
                || entry.st_nlink as u64 != 1
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp identity changed during exclusive creation",
                ));
            }
            return Ok(file);
        }
        #[cfg(not(unix))]
        {
            let mut options = std::fs::OpenOptions::new();
            options.read(true).write(true).create_new(true);
            #[cfg(windows)]
            {
                use std::os::windows::fs::OpenOptionsExt as _;
                const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
                options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
            }
            let file = options.open(path)?;
            let metadata = secure_file_metadata::from_file(&file)?;
            if !metadata.is_file() || !Self::sidecar_is_single_link(&metadata) {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp is not a direct single-link regular file",
                ));
            }
            Ok(file)
        }
    }
    fn promote_bound_progress_temp(
        namespace: &BoundProgressNamespace,
        temp_path: &Path,
        main_path: &Path,
        temp: &std::fs::File,
    ) -> std::result::Result<(), BoundProgressPromotionError> {
        let unpublished = |source| BoundProgressPromotionError {
            published: false,
            source,
        };
        let published = |source| BoundProgressPromotionError {
            published: true,
            source,
        };
        let immediate = namespace
            .directories
            .first()
            .ok_or_else(|| {
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "bound progress namespace has no immediate directory",
                )
            })
            .map_err(unpublished)?;
        if temp_path.parent() != Some(immediate.expected_path.as_path())
            || main_path.parent() != Some(immediate.expected_path.as_path())
        {
            return Err(unpublished(std::io::Error::new(
                ErrorKind::InvalidInput,
                "progress promotion escapes its bound namespace",
            )));
        }
        let temp_name = temp_path
            .file_name()
            .ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "progress temp has no entry name")
            })
            .map_err(unpublished)?;
        let main_name = main_path
            .file_name()
            .ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "progress index has no entry name")
            })
            .map_err(unpublished)?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt as _;
            let metadata = temp.metadata().map_err(unpublished)?;
            let before = rustix::fs::statat(
                &immediate.file,
                temp_name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            )
            .map_err(std::io::Error::from)
            .map_err(unpublished)?;
            if !metadata.is_file()
                || metadata.nlink() != 1
                || before.st_dev as u64 != metadata.dev()
                || before.st_ino as u64 != metadata.ino()
                || before.st_nlink as u64 != 1
            {
                return Err(unpublished(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp changed before promotion",
                )));
            }
            rustix::fs::renameat(&immediate.file, temp_name, &immediate.file, main_name)
                .map_err(std::io::Error::from)
                .map_err(unpublished)?;
            let after = rustix::fs::statat(
                &immediate.file,
                main_name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            )
            .map_err(std::io::Error::from)
            .map_err(published)?;
            if after.st_dev as u64 != metadata.dev()
                || after.st_ino as u64 != metadata.ino()
                || after.st_nlink as u64 != 1
            {
                return Err(published(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "promoted progress index has the wrong identity",
                )));
            }
            return Ok(());
        }
        #[cfg(not(unix))]
        {
            let _ = (namespace, temp_path, main_path, temp);
            Err(BoundProgressPromotionError {
                published: false,
                source: std::io::Error::new(
                    ErrorKind::Unsupported,
                    "descriptor-relative progress prepend promotion is unsupported on this platform",
                ),
            })
        }
    }
    fn bound_progress_append_build_path(index_path: &Path) -> PathBuf {
        index_path.with_extension("index.append.build.tmp")
    }
    fn bound_progress_append_intent_path(index_path: &Path) -> PathBuf {
        index_path.with_extension("index.append.intent.tmp")
    }
    fn sync_bound_progress_intent_directories(
        namespace: &BoundProgressNamespace,
    ) -> std::io::Result<()> {
        #[cfg(test)]
        let fail_at = FAIL_BOUND_PROGRESS_INTENT_DIRECTORY_SYNC.with(|slot| {
            let Some(mut fault) = slot.get() else {
                return None;
            };
            if fault.calls_before_failure > 0 {
                fault.calls_before_failure -= 1;
                slot.set(Some(fault));
                None
            } else {
                Some(fault.target_index)
            }
        });
        #[cfg(not(test))]
        let fail_at: Option<usize> = None;
        for (position, directory) in namespace.directories.iter().enumerate() {
            if fail_at == Some(position) {
                #[cfg(test)]
                FAIL_BOUND_PROGRESS_INTENT_DIRECTORY_SYNC.with(|slot| slot.set(None));
                return Err(std::io::Error::other(
                    "injected bound progress append-intent directory sync failure",
                ));
            }
            directory.file.sync_all()?;
        }
        Ok(())
    }
    fn promote_bound_progress_temp_noreplace(
        namespace: &BoundProgressNamespace,
        temp_path: &Path,
        intent_path: &Path,
        temp: &std::fs::File,
    ) -> std::result::Result<(), BoundProgressPromotionError> {
        let unpublished = |source| BoundProgressPromotionError {
            published: false,
            source,
        };
        let published = |source| BoundProgressPromotionError {
            published: true,
            source,
        };
        let immediate = namespace
            .directories
            .first()
            .ok_or_else(|| {
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "bound progress namespace has no immediate directory",
                )
            })
            .map_err(unpublished)?;
        if temp_path.parent() != Some(immediate.expected_path.as_path())
            || intent_path.parent() != Some(immediate.expected_path.as_path())
        {
            return Err(unpublished(std::io::Error::new(
                ErrorKind::InvalidInput,
                "progress append-intent promotion escapes its bound namespace",
            )));
        }
        let temp_name = temp_path
            .file_name()
            .ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "progress build has no entry name")
            })
            .map_err(unpublished)?;
        let intent_name = intent_path
            .file_name()
            .ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "progress intent has no entry name")
            })
            .map_err(unpublished)?;
        #[cfg(any(target_vendor = "apple", target_os = "linux", target_os = "android"))]
        {
            use std::os::unix::fs::MetadataExt as _;
            let metadata = temp.metadata().map_err(unpublished)?;
            let before = rustix::fs::statat(
                &immediate.file,
                temp_name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            )
            .map_err(std::io::Error::from)
            .map_err(unpublished)?;
            if !metadata.is_file()
                || metadata.nlink() != 1
                || before.st_dev as u64 != metadata.dev()
                || before.st_ino as u64 != metadata.ino()
                || before.st_nlink as u64 != 1
            {
                return Err(unpublished(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress append-intent build changed before promotion",
                )));
            }
            rustix::fs::renameat_with(
                &immediate.file,
                temp_name,
                &immediate.file,
                intent_name,
                rustix::fs::RenameFlags::NOREPLACE,
            )
            .map_err(std::io::Error::from)
            .map_err(unpublished)?;
            let after = rustix::fs::statat(
                &immediate.file,
                intent_name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            )
            .map_err(std::io::Error::from)
            .map_err(published)?;
            if after.st_dev as u64 != metadata.dev()
                || after.st_ino as u64 != metadata.ino()
                || after.st_nlink as u64 != 1
            {
                return Err(published(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "published progress append intent has the wrong identity",
                )));
            }
            return Ok(());
        }
        #[cfg(not(any(target_vendor = "apple", target_os = "linux", target_os = "android")))]
        {
            let _ = (namespace, temp_path, intent_path, temp);
            Err(BoundProgressPromotionError {
                published: false,
                source: std::io::Error::new(
                    ErrorKind::Unsupported,
                    "atomic descriptor-relative append-intent publication is unsupported on this platform",
                ),
            })
        }
    }
    fn publish_bound_progress_append_intent(
        namespace: &BoundProgressNamespace,
        index_path: &Path,
        intent: &BoundProgressAppendIntentV1,
        kind: &str,
    ) -> Option<std::fs::File> {
        let build_path = Self::bound_progress_append_build_path(index_path);
        let intent_path = Self::bound_progress_append_intent_path(index_path);
        let bytes = match norito::encode_canonical(intent) {
            Ok(bytes)
                if !bytes.is_empty() && bytes.len() <= BOUND_PROGRESS_APPEND_INTENT_MAX_BYTES =>
            {
                bytes
            }
            Ok(bytes) => {
                warn!(
                    len = bytes.len(),
                    ?intent_path,
                    kind,
                    "bound progress append intent exceeds its hard byte limit"
                );
                return None;
            }
            Err(error) => {
                warn!(
                    ?error,
                    ?intent_path,
                    kind,
                    "failed to encode progress append intent"
                );
                return None;
            }
        };
        let mut build = match Self::create_new_bound_progress_temp(namespace, &build_path) {
            Ok(build) => build,
            Err(error) => {
                warn!(
                    ?error,
                    ?build_path,
                    kind,
                    "failed to create progress append-intent build"
                );
                return None;
            }
        };
        if let Err(error) = build
            .write_all(&bytes)
            .and_then(|_| build.flush())
            .and_then(|_| sync_bound_progress_intent_file(&build))
        {
            warn!(
                ?error,
                ?build_path,
                kind,
                "failed to persist progress append-intent build"
            );
            drop(build);
            let _ = Self::remove_bound_progress_temp_if_present(namespace, &build_path);
            let _ = Self::sync_bound_progress_intent_directories(namespace);
            return None;
        }
        #[cfg(test)]
        if should_fail_after_bound_progress_append_build_for_tests() {
            return None;
        }
        if let Err(error) = Self::promote_bound_progress_temp_noreplace(
            namespace,
            &build_path,
            &intent_path,
            &build,
        ) {
            warn!(
                source = ?error.source,
                published = error.published,
                ?build_path,
                ?intent_path,
                kind,
                "failed to publish progress append intent"
            );
            drop(build);
            if !error.published {
                let _ = Self::remove_bound_progress_temp_if_present(namespace, &build_path);
                let _ = Self::sync_bound_progress_intent_directories(namespace);
            }
            return None;
        }
        if let Err(error) = Self::sync_bound_progress_intent_directories(namespace) {
            warn!(
                ?error,
                ?intent_path,
                kind,
                "failed to sync progress append-intent publication"
            );
            return None;
        }
        Some(build)
    }
    fn open_bound_progress_directory(
        store_root: &Path,
        expected_path: &Path,
    ) -> Result<BoundProgressDirectory> {
        let (canonical_path, metadata) =
            Self::canonical_sidecar_directory_for(store_root, expected_path)?.ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "progress sidecar directory disappeared while binding it",
                    ),
                    expected_path.to_path_buf(),
                )
            })?;
        let mut options = std::fs::OpenOptions::new();
        options.read(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt as _;
            options.custom_flags(
                (rustix::fs::OFlags::DIRECTORY | rustix::fs::OFlags::NOFOLLOW).bits() as i32,
            );
        }
        #[cfg(windows)]
        {
            use std::os::windows::fs::OpenOptionsExt as _;
            const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
            const FILE_FLAG_BACKUP_SEMANTICS: u32 = 0x0200_0000;
            options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT | FILE_FLAG_BACKUP_SEMANTICS);
        }
        let file = options
            .open(expected_path)
            .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
        let opened = secure_file_metadata::from_file(&file)
            .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
        let after = Self::canonical_sidecar_directory_for(store_root, expected_path)?;
        if !opened.is_dir()
            || !Self::sidecar_directory_binding_unchanged(&metadata, &opened)
            || !after.as_ref().is_some_and(|(after_path, after_metadata)| {
                *after_path == canonical_path
                    && Self::sidecar_directory_binding_unchanged(&metadata, after_metadata)
            })
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar directory changed while opening",
                ),
                expected_path.to_path_buf(),
            ));
        }
        Ok(BoundProgressDirectory {
            expected_path: expected_path.to_path_buf(),
            canonical_path,
            entry_name: None,
            file,
            metadata,
        })
    }
    fn open_bound_progress_child_directory(
        store_root: &Path,
        parent: &BoundProgressDirectory,
        expected_path: &Path,
    ) -> Result<BoundProgressDirectory> {
        #[cfg(unix)]
        let _ = store_root;
        if expected_path.parent() != Some(parent.expected_path.as_path()) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar directory is not a direct child of its bound parent",
                ),
                expected_path.to_path_buf(),
            ));
        }
        let name = expected_path.file_name().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar child directory has no entry name",
                ),
                expected_path.to_path_buf(),
            )
        })?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt as _;
            let before =
                rustix::fs::statat(&parent.file, name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
                    .map_err(std::io::Error::from)
                    .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
            if rustix::fs::FileType::from_raw_mode(before.st_mode)
                != rustix::fs::FileType::Directory
            {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar path component is not a direct directory",
                    ),
                    expected_path.to_path_buf(),
                ));
            }
            let file = std::fs::File::from(
                rustix::fs::openat(
                    &parent.file,
                    name,
                    rustix::fs::OFlags::RDONLY
                        | rustix::fs::OFlags::DIRECTORY
                        | rustix::fs::OFlags::NOFOLLOW
                        | rustix::fs::OFlags::CLOEXEC,
                    rustix::fs::Mode::empty(),
                )
                .map_err(std::io::Error::from)
                .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?,
            );
            let metadata = secure_file_metadata::from_file(&file)
                .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
            let after =
                rustix::fs::statat(&parent.file, name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
                    .map_err(std::io::Error::from)
                    .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
            let canonical_path = parent.canonical_path.join(name);
            let canonical_after = std::fs::canonicalize(expected_path)
                .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
            if !metadata.is_dir()
                || before.st_dev as u64 != metadata.dev()
                || before.st_ino as u64 != metadata.ino()
                || after.st_dev as u64 != metadata.dev()
                || after.st_ino as u64 != metadata.ino()
                || canonical_after != canonical_path
            {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar directory changed during descriptor-relative binding",
                    ),
                    expected_path.to_path_buf(),
                ));
            }
            return Ok(BoundProgressDirectory {
                expected_path: expected_path.to_path_buf(),
                canonical_path,
                entry_name: Some(name.to_os_string()),
                file,
                metadata,
            });
        }
        #[cfg(not(unix))]
        {
            let mut child = Self::open_bound_progress_directory(store_root, expected_path)?;
            child.entry_name = Some(name.to_os_string());
            Ok(child)
        }
    }
    fn open_bound_progress_namespace(
        &self,
        data_path: &Path,
        index_path: &Path,
    ) -> Result<BoundProgressNamespace> {
        let sidecar_dir = data_path.parent().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar data path has no parent",
                ),
                data_path.to_path_buf(),
            )
        })?;
        if index_path.parent() != Some(sidecar_dir) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar files do not share one parent directory",
                ),
                index_path.to_path_buf(),
            ));
        }
        let mut directory_paths = vec![sidecar_dir.to_path_buf()];
        let mut ancestor = sidecar_dir;
        loop {
            if ancestor == self.store_root {
                break;
            }
            ancestor = ancestor.parent().ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar durability chain did not reach the Kura root",
                    ),
                    ancestor.to_path_buf(),
                )
            })?;
            directory_paths.push(ancestor.to_path_buf());
        }
        directory_paths.reverse();
        let Some(root_path) = directory_paths.first() else {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar durability chain is empty",
                ),
                sidecar_dir.to_path_buf(),
            ));
        };
        let root = Self::open_bound_progress_directory(&self.store_root, root_path)?;
        let mut directories = Vec::with_capacity(directory_paths.len());
        directories.push(root);
        for path in directory_paths.iter().skip(1) {
            let parent = directories
                .last()
                .expect("bound progress directory chain starts at Kura root");
            let child = Self::open_bound_progress_child_directory(&self.store_root, parent, path)?;
            directories.push(child);
        }
        directories.reverse();
        let namespace = BoundProgressNamespace {
            data_path: data_path.to_path_buf(),
            index_path: index_path.to_path_buf(),
            directories,
        };
        if !self.bound_progress_namespace_unchanged(&namespace) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar namespace changed while binding durability handles",
                ),
                sidecar_dir.to_path_buf(),
            ));
        }
        Ok(namespace)
    }
    fn open_bound_progress_pair(
        &self,
        data_path: &Path,
        index_path: &Path,
    ) -> Result<BoundProgressPair> {
        let namespace = self.open_bound_progress_namespace(data_path, index_path)?;
        let sidecar_dir = namespace
            .data_path
            .parent()
            .expect("bound progress namespace always has an immediate parent");
        let data_metadata =
            Self::regular_sidecar_metadata_for(&self.store_root, data_path, sidecar_dir)?;
        let index_metadata =
            Self::regular_sidecar_metadata_for(&self.store_root, index_path, sidecar_dir)?;
        let (data_metadata, index_metadata) = match (data_metadata, index_metadata) {
            (None, None) => {
                if !self.bound_progress_namespace_unchanged(&namespace) {
                    return Err(Error::IO(
                        std::io::Error::new(
                            ErrorKind::InvalidData,
                            "progress sidecar namespace changed while attesting absence",
                        ),
                        sidecar_dir.to_path_buf(),
                    ));
                }
                return Ok(BoundProgressPair::Absent(namespace));
            }
            (Some(data), Some(index)) => (data, index),
            _ => {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar data and index are only partially present",
                    ),
                    sidecar_dir.to_path_buf(),
                ));
            }
        };
        let data = Self::open_bound_progress_file(&namespace, data_path, &data_metadata)?;
        let index = Self::open_bound_progress_file(&namespace, index_path, &index_metadata)?;
        let bound = BoundProgressSidecar {
            namespace,
            data,
            index,
            data_metadata,
            index_metadata,
        };
        if !self.bound_progress_sidecar_unchanged(&bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed while binding its durability handles",
                ),
                data_path.to_path_buf(),
            ));
        }
        Ok(BoundProgressPair::Present(bound))
    }
    fn open_bound_progress_sidecar(
        &self,
        data_path: &Path,
        index_path: &Path,
    ) -> Result<BoundProgressSidecar> {
        match self.open_bound_progress_pair(data_path, index_path)? {
            BoundProgressPair::Present(bound) => Ok(bound),
            BoundProgressPair::Absent(namespace) => Err(Error::IO(
                std::io::Error::new(ErrorKind::NotFound, "progress sidecar pair is absent"),
                namespace.data_path,
            )),
        }
    }
    fn bound_progress_namespace_unchanged(&self, namespace: &BoundProgressNamespace) -> bool {
        namespace
            .directories
            .iter()
            .enumerate()
            .all(|(index, directory)| {
                let Ok(opened) = secure_file_metadata::from_file(&directory.file) else {
                    return false;
                };
                #[cfg(unix)]
                if let Some(name) = directory.entry_name.as_deref() {
                    use std::os::unix::fs::MetadataExt as _;
                    let Some(parent) = namespace.directories.get(index.saturating_add(1)) else {
                        return false;
                    };
                    let Ok(entry) = rustix::fs::statat(
                        &parent.file,
                        name,
                        rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
                    ) else {
                        return false;
                    };
                    if rustix::fs::FileType::from_raw_mode(entry.st_mode)
                        != rustix::fs::FileType::Directory
                        || entry.st_dev as u64 != opened.dev()
                        || entry.st_ino as u64 != opened.ino()
                    {
                        return false;
                    }
                }
                let opened_matches =
                    Self::sidecar_directory_binding_unchanged(&directory.metadata, &opened);
                if !opened.is_dir() || !opened_matches {
                    return false;
                }
                Self::canonical_sidecar_directory_for(&self.store_root, &directory.expected_path)
                    .ok()
                    .flatten()
                    .is_some_and(|(canonical_path, metadata)| {
                        let path_matches = Self::sidecar_directory_binding_unchanged(
                            &directory.metadata,
                            &metadata,
                        );
                        canonical_path == directory.canonical_path && path_matches
                    })
            })
    }
    fn bound_progress_sidecar_unchanged(&self, bound: &BoundProgressSidecar) -> bool {
        let Some(sidecar_dir) = bound.namespace.data_path.parent() else {
            return false;
        };
        if bound.namespace.index_path.parent() != Some(sidecar_dir) {
            return false;
        }
        let Ok(data_opened) = secure_file_metadata::from_file(&bound.data) else {
            return false;
        };
        let Ok(index_opened) = secure_file_metadata::from_file(&bound.index) else {
            return false;
        };
        if !Self::sidecar_file_metadata_unchanged(&bound.data_metadata.file, &data_opened)
            || !Self::sidecar_file_metadata_unchanged(&bound.index_metadata.file, &index_opened)
        {
            return false;
        }
        let Ok(data_after) = Self::regular_sidecar_metadata_for(
            &self.store_root,
            &bound.namespace.data_path,
            sidecar_dir,
        ) else {
            return false;
        };
        let Ok(index_after) = Self::regular_sidecar_metadata_for(
            &self.store_root,
            &bound.namespace.index_path,
            sidecar_dir,
        ) else {
            return false;
        };
        if !data_after.as_ref().is_some_and(|after| {
            Self::stable_sidecar_metadata_unchanged(&bound.data_metadata, after)
        }) || !index_after.as_ref().is_some_and(|after| {
            Self::stable_sidecar_metadata_unchanged(&bound.index_metadata, after)
        }) {
            return false;
        }
        self.bound_progress_namespace_unchanged(&bound.namespace)
    }
    fn sync_bound_progress_namespace(
        &self,
        namespace: &BoundProgressNamespace,
        kind: &str,
    ) -> bool {
        for (index, directory) in namespace.directories.iter().enumerate() {
            let result = if index == 0 {
                sync_indexed_sidecar_dir_handle(&directory.file)
            } else {
                sync_progress_sidecar_ancestor_dir_handle(&directory.file)
            };
            if let Err(err) = result {
                iroha_logger::warn!(
                    ?err,
                    path = ?directory.expected_path,
                    kind,
                    "failed to sync bound progress sidecar namespace"
                );
                return false;
            }
        }
        self.bound_progress_namespace_unchanged(namespace)
    }
    fn sync_bound_progress_absence(&self, namespace: &BoundProgressNamespace, kind: &str) -> bool {
        if !self.sync_bound_progress_namespace(namespace, kind) {
            return false;
        }
        let Some(sidecar_dir) = namespace.data_path.parent() else {
            return false;
        };
        if namespace.index_path.parent() != Some(sidecar_dir) {
            return false;
        }
        matches!(
            Self::regular_sidecar_metadata_for(&self.store_root, &namespace.data_path, sidecar_dir,),
            Ok(None)
        ) && matches!(
            Self::regular_sidecar_metadata_for(
                &self.store_root,
                &namespace.index_path,
                sidecar_dir,
            ),
            Ok(None)
        ) && self.bound_progress_namespace_unchanged(namespace)
    }
    fn sync_bound_progress_sidecar(&self, bound: &BoundProgressSidecar, kind: &str) -> bool {
        if let Err(err) = sync_indexed_sidecar_data(&bound.data) {
            iroha_logger::warn!(?err, path = ?bound.namespace.data_path, kind, "failed to sync progress sidecar payload");
            return false;
        }
        if let Err(err) = sync_indexed_sidecar_index(&bound.index) {
            iroha_logger::warn!(?err, path = ?bound.namespace.index_path, kind, "failed to sync progress sidecar index");
            return false;
        }
        self.sync_bound_progress_namespace(&bound.namespace, kind)
            && self.bound_progress_sidecar_unchanged(bound)
    }
    fn bound_indexed_sidecar_payload_heights(
        &self,
        bound: &mut BoundProgressSidecar,
        kind: &str,
        limit: usize,
    ) -> Result<BTreeSet<u64>> {
        if !self.bound_progress_sidecar_unchanged(bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed before index enumeration",
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        let index_len = bound
            .index
            .metadata()
            .map_err(|error| Error::IO(error, bound.namespace.index_path.clone()))?
            .len();
        let layout =
            SidecarIndexLayout::read_from(&mut bound.index, index_len).map_err(|reason| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        format!("{kind} index is malformed: {reason}"),
                    ),
                    bound.namespace.index_path.clone(),
                )
            })?;
        if layout.aligned_len != index_len
            || usize::try_from(layout.entry_count).unwrap_or(usize::MAX) > limit
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    format!("{kind} index is misaligned or exceeds its bounded entry count"),
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        let data_len = bound
            .data
            .metadata()
            .map_err(|error| Error::IO(error, bound.namespace.data_path.clone()))?
            .len();
        bound
            .index
            .seek(SeekFrom::Start(layout.entries_offset))
            .map_err(|error| Error::IO(error, bound.namespace.index_path.clone()))?;
        let mut heights = BTreeSet::new();
        let mut indexed_end = 0_u64;
        let mut encoded = [0_u8; PIPELINE_INDEX_ENTRY_SIZE];
        for offset in 0..layout.entry_count {
            bound
                .index
                .read_exact(&mut encoded)
                .map_err(|error| Error::IO(error, bound.namespace.index_path.clone()))?;
            let entry = SidecarIndexEntry::from_bytes(encoded);
            if entry.len == 0 {
                continue;
            }
            if entry.len > STRICT_INIT_MAX_BLOCK_BYTES
                || entry
                    .offset
                    .checked_add(entry.len)
                    .is_none_or(|end| end > data_len)
            {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        format!("{kind} index contains an invalid payload range"),
                    ),
                    bound.namespace.index_path.clone(),
                ));
            }
            indexed_end = indexed_end.max(
                entry
                    .offset
                    .checked_add(entry.len)
                    .expect("validated sidecar range cannot overflow"),
            );
            let height = layout.base_height.checked_add(offset).ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        format!("{kind} index height overflows"),
                    ),
                    bound.namespace.index_path.clone(),
                )
            })?;
            heights.insert(height);
        }
        if data_len != indexed_end {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    format!("{kind} data has an unindexed suffix and requires writer recovery"),
                ),
                bound.namespace.data_path.clone(),
            ));
        }
        if !self.bound_progress_sidecar_unchanged(bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed during index enumeration",
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        Ok(heights)
    }
    fn bound_indexed_sidecar_height_range(
        &self,
        bound: &mut BoundProgressSidecar,
        kind: &str,
    ) -> Result<Option<core::ops::RangeInclusive<u64>>> {
        if !self.bound_progress_sidecar_unchanged(bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed before range enumeration",
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        let index_len = bound
            .index
            .metadata()
            .map_err(|error| Error::IO(error, bound.namespace.index_path.clone()))?
            .len();
        let layout =
            SidecarIndexLayout::read_from(&mut bound.index, index_len).map_err(|reason| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        format!("{kind} index is malformed: {reason}"),
                    ),
                    bound.namespace.index_path.clone(),
                )
            })?;
        if layout.aligned_len != index_len {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    format!("{kind} index has trailing or partial bytes"),
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        if !self.bound_progress_sidecar_unchanged(bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed during range enumeration",
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        Ok(layout.height_range())
    }
    fn read_regular_sidecar_bytes_for(
        store_root: &Path,
        path: &Path,
        expected_directory: &Path,
        byte_limit: usize,
    ) -> Result<Option<Vec<u8>>> {
        Ok(Self::read_regular_sidecar_snapshot_for(
            store_root,
            path,
            expected_directory,
            byte_limit,
        )?
        .map(|snapshot| snapshot.bytes))
    }
    fn read_regular_sidecar_snapshot_for(
        store_root: &Path,
        path: &Path,
        expected_directory: &Path,
        byte_limit: usize,
    ) -> Result<Option<StableSidecarRead>> {
        Self::read_regular_sidecar_snapshot_for_with_admission_hook(
            store_root,
            path,
            expected_directory,
            byte_limit,
            || {},
        )
    }
    /// Perform one stable, no-follow bounded read after invoking a post-admission hook.
    ///
    /// Production passes a no-op hook. Tests use the seam to grow a file after
    /// its capped metadata has been admitted, proving that the reader allocates
    /// only the admitted length and rejects the max-plus-one race.
    fn read_regular_sidecar_snapshot_for_with_admission_hook<F>(
        store_root: &Path,
        path: &Path,
        expected_directory: &Path,
        byte_limit: usize,
        after_admission: F,
    ) -> Result<Option<StableSidecarRead>>
    where
        F: FnOnce(),
    {
        let directory_before =
            Self::canonical_sidecar_directory_for(store_root, expected_directory)?;
        let Some(metadata) =
            Self::regular_sidecar_metadata_for(store_root, path, expected_directory)?
        else {
            return Ok(None);
        };
        let Some((_, directory_before)) = directory_before else {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar exists without a stable direct directory",
                ),
                path.to_path_buf(),
            ));
        };
        if !Self::sidecar_directory_binding_unchanged(&directory_before, &metadata.directory) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar directory changed before bounded read",
                ),
                path.to_path_buf(),
            ));
        }
        if metadata.file.len() > u64::try_from(byte_limit)? {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar exceeds its hard byte limit",
                ),
                path.to_path_buf(),
            ));
        }
        after_admission();
        let mut file =
            std::fs::File::open(path).map_err(|err| Error::IO(err, path.to_path_buf()))?;
        let opened_metadata = secure_file_metadata::from_file(&file)
            .map_err(|err| Error::IO(err, path.to_path_buf()))?;
        if !opened_metadata.is_file()
            || !Self::sidecar_file_metadata_unchanged(&metadata.file, &opened_metadata)
        {
            return Err(Error::IO(
                std::io::Error::new(ErrorKind::InvalidData, "sidecar file changed while opening"),
                path.to_path_buf(),
            ));
        }
        let mut bytes = Vec::new();
        let expected_len = usize::try_from(metadata.file.len())?;
        bytes.try_reserve_exact(expected_len)?;
        bytes.resize(expected_len, 0);
        file.read_exact(&mut bytes)
            .map_err(|err| Error::IO(err, path.to_path_buf()))?;
        let mut growth_probe = [0_u8; 1];
        if file
            .read(&mut growth_probe)
            .map_err(|err| Error::IO(err, path.to_path_buf()))?
            != 0
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar grew beyond its admitted length while reading",
                ),
                path.to_path_buf(),
            ));
        }
        let opened_after = secure_file_metadata::from_file(&file)
            .map_err(|err| Error::IO(err, path.to_path_buf()))?;
        let path_after = Self::regular_sidecar_metadata_for(store_root, path, expected_directory)?;
        if bytes.len() > byte_limit
            || u64::try_from(bytes.len())? != metadata.file.len()
            || !Self::sidecar_file_metadata_unchanged(&metadata.file, &opened_after)
            || !path_after.as_ref().is_some_and(|after| {
                Self::stable_sidecar_file_binding_unchanged(&metadata, after)
                    && Self::sidecar_metadata_same_object(&directory_before, &after.directory)
            })
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar changed or exceeded its hard byte limit while reading",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some(StableSidecarRead {
            bytes_hash: Hash::new(&bytes),
            bytes,
            metadata: path_after.expect("validated stable sidecar metadata exists"),
        }))
    }
    fn read_regular_sidecar_snapshot(
        &self,
        path: &Path,
        expected_directory: &Path,
        byte_limit: usize,
    ) -> Result<Option<StableSidecarRead>> {
        Self::read_regular_sidecar_snapshot_for(
            &self.store_root,
            path,
            expected_directory,
            byte_limit,
        )
    }
    fn read_regular_sidecar_bytes(
        &self,
        path: &Path,
        expected_directory: &Path,
        byte_limit: usize,
    ) -> Result<Option<Vec<u8>>> {
        Self::read_regular_sidecar_bytes_for(&self.store_root, path, expected_directory, byte_limit)
    }
    #[cfg(test)]
    fn record_startup_replay_historical_payload_read(&self) {
        self.startup_replay_historical_payload_reads
            .fetch_add(1, Ordering::Relaxed);
    }
    #[cfg(not(test))]
    fn record_startup_replay_historical_payload_read(&self) {}
    fn block_merge_reference(
        block: &SignedBlock,
    ) -> Option<&iroha_data_model::block::CertifiedMergeLedgerReference> {
        block.execution_context()?.merge_entry.as_ref()
    }
    fn carrier_record_for_block_entry(
        block: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) -> Result<MergeLedgerCarrierRecord> {
        let reference = Self::block_merge_reference(block).ok_or_else(|| {
            Error::MergeReferenceMismatch(
                "merge entry supplied for a block without a compact reference".to_owned(),
            )
        })?;
        if !reference.matches_entry(entry) {
            return Err(Error::MergeReferenceMismatch(
                "compact block reference does not match the resolved full entry".to_owned(),
            ));
        }
        if entry.merge_qc.carrier_height != block.header().height().get()
            || Some(entry.merge_qc.carrier_parent_hash) != block.header().prev_block_hash()
            || entry.merge_qc.view != block.header().view_change_index()
        {
            return Err(Error::MergeReferenceMismatch(
                "merge QC carrier height, parent, or view does not match the referencing block"
                    .to_owned(),
            ));
        }
        Ok(MergeLedgerCarrierRecord::new(entry, block))
    }
    fn read_merge_carrier_path(&self, path: &Path) -> Result<Option<MergeLedgerCarrierRecord>> {
        let Some(bytes) = self.read_regular_sidecar_bytes(
            path,
            &self.merge_carrier_dir(),
            MERGE_CARRIER_MAX_BYTES,
        )?
        else {
            return Ok(None);
        };
        self.decode_merge_carrier_record(path, path, &bytes)
            .map(Some)
    }
    fn decode_merge_carrier_record(
        &self,
        source_path: &Path,
        canonical_path: &Path,
        bytes: &[u8],
    ) -> Result<MergeLedgerCarrierRecord> {
        let record =
            norito::decode_canonical::<MergeLedgerCarrierRecord>(bytes).map_err(|err| {
                Error::MergeCarrierConflict(format!(
                    "carrier record {} is not exact framed Norito: {err}",
                    source_path.display()
                ))
            })?;
        if record.version != 1
            || record.block_height == 0
            || self.merge_carrier_path(record.block_height) != canonical_path
        {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier record {} has a non-canonical identity",
                source_path.display()
            )));
        }
        Ok(record)
    }
    fn reconcile_merge_carrier_temp_files_unlocked(&self) -> Result<()> {
        let directory = self.merge_carrier_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(()),
            Err(err) => return Err(Error::IO(err, directory)),
        };
        let durable_count = u64::try_from(self.exact_durable_blocks_count()?)?;
        let mut changed = false;
        for entry in read_dir {
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let metadata = secure_file_metadata::from_path(&path)
                .map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink() || !metadata.file_type().is_file() {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier directory entry {} is not a regular no-follow file",
                    path.display()
                )));
            }
            let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                return Err(Error::MergeCarrierConflict(
                    "carrier directory contains a non-UTF-8 entry".to_owned(),
                ));
            };
            if file_name.ends_with(".norito") {
                continue;
            }
            let Some(height_text) = file_name.strip_suffix(".norito.tmp") else {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier directory contains unexpected entry {}",
                    path.display()
                )));
            };
            let block_height = height_text.parse::<u64>().map_err(|_| {
                Error::MergeCarrierConflict(format!(
                    "carrier temporary {} has a non-numeric height",
                    path.display()
                ))
            })?;
            if block_height == 0 || block_height.to_string() != height_text {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier temporary {} has a non-canonical height",
                    path.display()
                )));
            }
            let canonical_path = self.merge_carrier_path(block_height);
            let bytes = self
                .read_regular_sidecar_bytes(&path, &directory, MERGE_CARRIER_MAX_BYTES)?
                .ok_or_else(|| {
                    Error::MergeCarrierConflict(format!(
                        "carrier temporary {} disappeared during recovery",
                        path.display()
                    ))
                })?;
            let record = self.decode_merge_carrier_record(&path, &canonical_path, &bytes)?;
            if let Some(existing) = self.read_merge_carrier_path(&canonical_path)? {
                if existing != record {
                    return Err(Error::MergeCarrierConflict(format!(
                        "carrier temporary {} conflicts with its published record",
                        path.display()
                    )));
                }
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                changed = true;
                continue;
            }
            match self.get_durable_block_hash(
                NonZeroUsize::new(usize::try_from(block_height)?).ok_or_else(|| {
                    Error::MergeCarrierConflict("carrier temporary height is zero".to_owned())
                })?,
            ) {
                Some(block_hash) if block_hash == record.block_hash => {
                    std::fs::rename(&path, &canonical_path)
                        .map_err(|err| Error::IO(err, canonical_path.clone()))?;
                    changed = true;
                }
                None if block_height > durable_count => {
                    // The process stopped before publishing the matching block.
                    // The log suffix is reconciled separately below.
                    std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                    changed = true;
                }
                Some(block_hash) => {
                    return Err(Error::MergeCarrierConflict(format!(
                        "carrier temporary {} names block {} but durable block {} has hash {}",
                        path.display(),
                        record.block_hash,
                        block_height,
                        block_hash
                    )));
                }
                None => {
                    return Err(Error::MergeCarrierConflict(format!(
                        "carrier temporary {} points into a gap in the durable block log",
                        path.display()
                    )));
                }
            }
        }
        if changed {
            sync_dir(&directory).map_err(|err| Error::IO(err, directory))?;
        }
        Ok(())
    }
    fn merge_carrier_records_from_disk_unlocked(&self) -> Result<Vec<MergeLedgerCarrierRecord>> {
        let directory = self.merge_carrier_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(Vec::new()),
            Err(err) => return Err(Error::IO(err, directory)),
        };
        let max_records = self.exact_durable_blocks_count()?.saturating_add(1);
        let mut paths = Vec::new();
        for entry in read_dir {
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let metadata = secure_file_metadata::from_path(&path)
                .map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink() || !metadata.file_type().is_file() {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier directory entry {} is not a regular no-follow file",
                    path.display()
                )));
            }
            if path
                .extension()
                .is_some_and(|extension| extension == "norito")
            {
                paths.push(path);
                if paths.len() > max_records {
                    return Err(Error::MergeCarrierConflict(
                        "carrier record count exceeds the durable block count plus one staged publication"
                            .to_owned(),
                    ));
                }
            } else {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier directory contains unexpected entry {}",
                    path.display()
                )));
            }
        }
        paths.sort();
        let mut records = Vec::with_capacity(paths.len());
        let mut entry_hashes = BTreeSet::new();
        let mut block_heights = BTreeSet::new();
        for path in paths {
            let Some(record) = self.read_merge_carrier_path(&path)? else {
                continue;
            };
            if !entry_hashes.insert(record.entry_hash) || !block_heights.insert(record.block_height)
            {
                return Err(Error::MergeCarrierConflict(
                    "carrier index duplicates an entry hash or block height".to_owned(),
                ));
            }
            records.push(record);
        }
        records.sort_by_key(|record| record.block_height);
        Ok(records)
    }
    fn ensure_merge_carrier_index_initialized_unlocked(&self) -> Result<()> {
        {
            let index = self.merge_carrier_index.lock();
            if index.initialized {
                return Ok(());
            }
        }
        if self.auxiliary_history_deferred {
            return Err(Error::EmergencyFastAuxiliaryUnavailable {
                subsystem: "merge-carrier index",
            });
        }
        let records = self.merge_carrier_records_from_disk_unlocked()?;
        let mut index = self.merge_carrier_index.lock();
        #[cfg(test)]
        {
            index.directory_scans = index.directory_scans.saturating_add(1);
        }
        index.by_height = records
            .iter()
            .map(|record| (record.block_height, *record))
            .collect();
        index.by_entry = records
            .iter()
            .map(|record| (record.entry_hash, *record))
            .collect();
        index.initialized = true;
        index.generation = index.generation.saturating_add(1);
        Ok(())
    }
    fn merge_carrier_records_unlocked(&self) -> Result<Vec<MergeLedgerCarrierRecord>> {
        self.ensure_merge_carrier_index_initialized_unlocked()?;
        #[cfg(test)]
        let mut index = self.merge_carrier_index.lock();
        #[cfg(not(test))]
        let index = self.merge_carrier_index.lock();
        #[cfg(test)]
        {
            index.full_inventory_clones = index.full_inventory_clones.saturating_add(1);
        }
        Ok(index.by_height.values().copied().collect())
    }
    fn write_merge_carrier_record_unlocked(
        &self,
        record: MergeLedgerCarrierRecord,
    ) -> Result<bool> {
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let directory = self.merge_carrier_dir();
        std::fs::create_dir_all(&directory).map_err(|err| Error::MkDir(err, directory.clone()))?;
        self.ensure_merge_carrier_index_initialized_unlocked()?;
        let (existing_for_entry, existing_for_height) = {
            let index = self.merge_carrier_index.lock();
            (
                index.by_entry.get(&record.entry_hash).copied(),
                index.by_height.get(&record.block_height).copied(),
            )
        };
        if let Some(existing) = existing_for_entry {
            if existing == record {
                return match self
                    .read_merge_carrier_path(&self.merge_carrier_path(record.block_height))?
                {
                    Some(persisted) if persisted == record => Ok(false),
                    Some(_) => Err(Error::MergeCarrierConflict(
                        "cached carrier record differs from its canonical file".to_owned(),
                    )),
                    None => Err(Error::MergeCarrierConflict(
                        "cached carrier record is missing from its canonical file".to_owned(),
                    )),
                };
            }
            return Err(Error::MergeCarrierConflict(format!(
                "entry {} is already carried by block {} ({})",
                record.entry_hash, existing.block_height, existing.block_hash
            )));
        }
        if let Some(existing) = existing_for_height {
            return Err(Error::MergeCarrierConflict(format!(
                "block {} ({}) already carries merge entry {}",
                existing.block_height, existing.block_hash, existing.entry_hash
            )));
        }
        let path = self.merge_carrier_path(record.block_height);
        let bytes = norito::encode_canonical(&record).map_err(Error::NoritoFrame)?;
        if bytes.len() > MERGE_CARRIER_MAX_BYTES {
            return Err(Error::MergeCarrierConflict(
                "canonical carrier record exceeds its hard byte limit".to_owned(),
            ));
        }
        let temp_path = path.with_extension("norito.tmp");
        if let Err(err) = std::fs::remove_file(&temp_path)
            && err.kind() != ErrorKind::NotFound
        {
            panic!(
                "cannot clear stale carrier temporary {} before atomic publication: {err}",
                temp_path.display()
            );
        }
        let stage_result = (|| {
            let mut temp = std::fs::OpenOptions::new()
                .create_new(true)
                .write(true)
                .open(&temp_path)
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            temp.write_all(&bytes)
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            temp.sync_all()
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            Ok::<(), Error>(())
        })();
        if let Err(stage_err) = stage_result {
            if let Err(cleanup_err) = std::fs::remove_file(&temp_path)
                && cleanup_err.kind() != ErrorKind::NotFound
            {
                panic!(
                    "carrier staging failed ({stage_err}) and temporary cleanup failed ({cleanup_err})"
                );
            }
            if let Err(sync_err) = sync_dir(&directory) {
                panic!(
                    "carrier staging failed ({stage_err}) and temporary cleanup sync failed ({sync_err})"
                );
            }
            return Err(stage_err);
        }
        if let Err(rename_err) = std::fs::rename(&temp_path, &path) {
            if let Err(cleanup_err) = std::fs::remove_file(&temp_path)
                && cleanup_err.kind() != ErrorKind::NotFound
            {
                panic!(
                    "carrier rename failed ({rename_err}) and temporary cleanup failed ({cleanup_err})"
                );
            }
            if let Err(sync_err) = sync_dir(&directory) {
                panic!(
                    "carrier rename failed ({rename_err}) and temporary cleanup sync failed ({sync_err})"
                );
            }
            return Err(Error::IO(rename_err, path));
        }
        if let Err(sync_err) = sync_dir(&directory) {
            // The rename is already visible. Keep the merge-log frame and fail
            // stop so startup can validate/reconcile the complete pair instead
            // of letting the caller truncate only one half.
            panic!(
                "carrier record {} was renamed but its directory sync failed: {sync_err}",
                path.display()
            );
        }
        self.add_disk_usage_bytes(u64::try_from(bytes.len())?);
        let mut index = self.merge_carrier_index.lock();
        index.by_height.insert(record.block_height, record);
        index.by_entry.insert(record.entry_hash, record);
        index.initialized = true;
        index.generation = index.generation.saturating_add(1);
        drop(index);
        accounting_mutation.finish();
        Ok(true)
    }
    fn preflight_merge_carrier_record_unlocked(
        &self,
        record: MergeLedgerCarrierRecord,
    ) -> Result<bool> {
        self.ensure_merge_carrier_index_initialized_unlocked()?;
        let index = self.merge_carrier_index.lock();
        if let Some(existing) = index.by_entry.get(&record.entry_hash) {
            if *existing != record {
                return Err(Error::MergeCarrierConflict(format!(
                    "entry {} is already carried by block {} ({})",
                    record.entry_hash, existing.block_height, existing.block_hash
                )));
            }
            drop(index);
            return match self
                .read_merge_carrier_path(&self.merge_carrier_path(record.block_height))?
            {
                Some(persisted) if persisted == record => Ok(false),
                Some(_) => Err(Error::MergeCarrierConflict(
                    "cached carrier record differs from its canonical file".to_owned(),
                )),
                None => Err(Error::MergeCarrierConflict(
                    "cached carrier record is missing from its canonical file".to_owned(),
                )),
            };
        }
        if let Some(existing) = index.by_height.get(&record.block_height) {
            return Err(Error::MergeCarrierConflict(format!(
                "block {} ({}) already carries merge entry {}",
                existing.block_height, existing.block_hash, existing.entry_hash
            )));
        }
        Ok(true)
    }
    fn remove_merge_carrier_record_unlocked(&self, record: MergeLedgerCarrierRecord) -> Result<()> {
        let path = self.merge_carrier_path(record.block_height);
        let Some(existing) = self.read_merge_carrier_path(&path)? else {
            return Err(Error::MergeCarrierConflict(format!(
                "cannot remove missing carrier record for block {}",
                record.block_height
            )));
        };
        if existing != record {
            return Err(Error::MergeCarrierConflict(
                "refusing to remove a different merge carrier record".to_owned(),
            ));
        }
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let bytes = std::fs::metadata(&path).map_or(0, |metadata| metadata.len());
        std::fs::remove_file(&path).map_err(|err| Error::IO(err, path))?;
        let sync_result = sync_dir(&self.merge_carrier_dir())
            .map_err(|err| Error::IO(err, self.merge_carrier_dir()));
        self.sub_disk_usage_bytes(bytes);
        let mut index = self.merge_carrier_index.lock();
        index.by_height.remove(&record.block_height);
        index.by_entry.remove(&record.entry_hash);
        index.generation = index.generation.saturating_add(1);
        drop(index);
        sync_result?;
        accounting_mutation.finish();
        Ok(())
    }
    fn validate_merge_carrier_record_against_header(
        &self,
        record: MergeLedgerCarrierRecord,
        header: &BlockHeader,
    ) -> Result<MergeLedgerEntry> {
        let persisted = self
            .read_merge_carrier_path(&self.merge_carrier_path(record.block_height))?
            .ok_or_else(|| {
                Error::MergeCarrierConflict(format!(
                    "cached carrier record for block {} is missing",
                    record.block_height
                ))
            })?;
        if persisted != record {
            return Err(Error::MergeCarrierConflict(format!(
                "cached carrier record for block {} differs from disk",
                record.block_height
            )));
        }
        let height = NonZeroUsize::new(usize::try_from(record.block_height)?)
            .ok_or_else(|| Error::MergeCarrierConflict("carrier height is zero".to_owned()))?;
        if self.get_durable_block_hash(height) != Some(record.block_hash) {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier for entry {} does not match canonical block {}",
                record.entry_hash, record.block_height
            )));
        }
        let entry = self
            .merge_log
            .lock()
            .entry_by_hash(record.entry_hash)?
            .ok_or_else(|| {
                Error::MergeCarrierConflict(format!(
                    "carrier for entry {} is absent from the committed merge log",
                    record.entry_hash
                ))
            })?;
        if entry.merge_qc.carrier_height != header.height().get()
            || Some(entry.merge_qc.carrier_parent_hash) != header.prev_block_hash()
            || entry.merge_qc.view != header.view_change_index()
        {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier block {} merge QC height, parent, or view differs from its canonical block header",
                record.block_height
            )));
        }
        if header.hash() != record.block_hash
            || entry.epoch_id != record.epoch_id
            || entry.merge_qc.carrier_height != record.block_height
            || Some(entry.merge_qc.carrier_parent_hash) != header.prev_block_hash()
            || entry.merge_qc.view != header.view_change_index()
        {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier block {} header differs from its record or full entry",
                record.block_height
            )));
        }
        Ok(entry)
    }
    fn validate_merge_carrier_record_against_block_projection(
        &self,
        record: MergeLedgerCarrierRecord,
        block: &SignedBlock,
    ) -> Result<MergeLedgerEntry> {
        let entry = self.validate_merge_carrier_record_against_header(record, &block.header())?;
        let reference = Self::block_merge_reference(block).ok_or_else(|| {
            Error::MergeCarrierConflict(format!(
                "carrier block {} no longer contains a compact merge reference",
                record.block_height
            ))
        })?;
        if reference.entry_hash != record.entry_hash
            || reference.epoch_id != record.epoch_id
            || !reference.matches_entry(&entry)
        {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier block {} compact reference differs from its record or full entry",
                record.block_height
            )));
        }
        Ok(entry)
    }
    /// Derive the exact merge-carrier projection at the finality publication seam.
    ///
    /// This is deliberately the only pre-finality path which may authorize a
    /// body-carried compact reference. It runs while the caller holds both the
    /// prune and canonical-chain guards, after the canonical block and its
    /// merge-log/carrier sidecars are durable, either at finality publication
    /// or while recovering the sole interrupted prepublication tip.
    fn merge_carrier_commitment_for_finality_prepublication_under_prune_and_canonical_guards(
        &self,
        block_height: NonZeroUsize,
        canonical_header: &BlockHeader,
    ) -> Result<Option<iroha_data_model::block::consensus_v2::MergeCarrierCommitmentV1>> {
        let height = u64::try_from(block_height.get())?;
        let block_hash = canonical_header.hash();
        let record = self.merge_carrier_record_for_block(height, block_hash)?;
        let block = self.get_block_without_merge_sidecar(block_height);
        let entry_hash = match (block, record) {
            (Some(block), Some(record)) => {
                if block.header() != *canonical_header {
                    return Err(Error::MergeCarrierConflict(format!(
                        "carrier block {height} body differs from its canonical finality header"
                    )));
                }
                self.validate_merge_carrier_record_against_block_projection(
                    record,
                    block.as_ref(),
                )?;
                Some(record.entry_hash)
            }
            (Some(block), None) if Self::block_merge_reference(block.as_ref()).is_some() => {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier block {height} has no durable merge-carrier record"
                )));
            }
            (Some(_), None) => None,
            (None, Some(record)) => {
                self.validate_merge_carrier_record_against_header(record, canonical_header)?;
                Some(record.entry_hash)
            }
            (None, None) => None,
        };
        Ok(entry_hash.map(iroha_data_model::block::consensus_v2::MergeCarrierCommitmentV1::new))
    }
    fn validate_merge_carrier_finality_projection(
        record: MergeLedgerCarrierRecord,
        entry: &MergeLedgerEntry,
        header: &BlockHeader,
        finality: &V2FinalityArtifact,
    ) -> Result<()> {
        let expected =
            iroha_data_model::block::consensus_v2::MergeCarrierCommitmentV1::new(record.entry_hash);
        if finality.height != record.block_height
            || finality.block_hash != record.block_hash
            || header.hash() != record.block_hash
            || finality.commit_qc.execution_commitment.validate().is_err()
            || finality.commit_qc.execution_commitment.merge_carrier != Some(expected)
            || entry.canonical_hash() != record.entry_hash
            || entry.epoch_id != record.epoch_id
            || entry.merge_qc.carrier_height != header.height().get()
            || Some(entry.merge_qc.carrier_parent_hash) != header.prev_block_hash()
            || entry.merge_qc.view != header.view_change_index()
        {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier block {} finality does not authenticate its exact merge entry",
                record.block_height
            )));
        }
        Ok(())
    }
    fn validate_merge_carrier_record_under_prune_and_canonical_guards(
        &self,
        record: MergeLedgerCarrierRecord,
    ) -> Result<MergeLedgerEntry> {
        let height = NonZeroUsize::new(usize::try_from(record.block_height)?)
            .ok_or_else(|| Error::MergeCarrierConflict("carrier height is zero".to_owned()))?;
        let block = self.get_block_without_merge_sidecar(height);
        let finality = self
            .v2_finality_artifact_with_archive_under_prune_and_canonical_guards(
                record.block_height,
            )?
            .map(|(header, finality, _)| (header, finality));
        match (block, finality) {
            (Some(block), Some((retained_header, finality))) => {
                let entry = self.validate_merge_carrier_record_against_block_projection(
                    record,
                    block.as_ref(),
                )?;
                if retained_header != block.header() {
                    return Err(Error::MergeCarrierConflict(format!(
                        "carrier block {} body differs from its retained finality header",
                        record.block_height
                    )));
                }
                Self::validate_merge_carrier_finality_projection(
                    record,
                    &entry,
                    &retained_header,
                    &finality,
                )?;
                Ok(entry)
            }
            (None, Some((retained_header, finality))) => {
                let entry =
                    self.validate_merge_carrier_record_against_header(record, &retained_header)?;
                Self::validate_merge_carrier_finality_projection(
                    record,
                    &entry,
                    &retained_header,
                    &finality,
                )?;
                Ok(entry)
            }
            (Some(_), None) | (None, None) => Err(Error::MergeCarrierConflict(format!(
                "carrier block {} has no durable finality-authenticated merge identity",
                record.block_height
            ))),
        }
    }
    fn merge_carrier_record_for_block(
        &self,
        block_height: u64,
        block_hash: HashOf<BlockHeader>,
    ) -> Result<Option<MergeLedgerCarrierRecord>> {
        let record = {
            let _guard = self.merge_carrier_lock.lock();
            self.ensure_merge_carrier_index_initialized_unlocked()?;
            self.merge_carrier_index
                .lock()
                .by_height
                .get(&block_height)
                .copied()
        };
        match record {
            None => Ok(None),
            Some(record) if record.block_hash == block_hash => Ok(Some(record)),
            Some(record) => Err(Error::MergeCarrierConflict(format!(
                "carrier record for block {} binds hash {} instead of canonical hash {}",
                block_height, record.block_hash, block_hash
            ))),
        }
    }
    /// Resolve the exact canonical carrier for a committed merge entry hash.
    ///
    /// # Errors
    /// Returns an error if the sparse carrier index is malformed or the carrier
    /// no longer matches Kura's canonical block hash.
    pub(crate) fn merge_carrier_for_entry(
        &self,
        entry_hash: HashOf<MergeLedgerEntry>,
    ) -> Result<Option<MergeLedgerCarrierRecord>> {
        let _prune_guard = self.prune_lock.lock();
        self.merge_carrier_for_entry_under_prune_guard(entry_hash)
    }
    fn merge_carrier_for_entry_under_prune_guard(
        &self,
        entry_hash: HashOf<MergeLedgerEntry>,
    ) -> Result<Option<MergeLedgerCarrierRecord>> {
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.merge_carrier_for_entry_under_prune_and_canonical_guards(entry_hash)
    }
    fn merge_carrier_for_entry_under_prune_and_canonical_guards(
        &self,
        entry_hash: HashOf<MergeLedgerEntry>,
    ) -> Result<Option<MergeLedgerCarrierRecord>> {
        self.ensure_prune_recovery_not_required()?;
        let record = {
            let _guard = self.merge_carrier_lock.lock();
            self.ensure_merge_carrier_index_initialized_unlocked()?;
            self.merge_carrier_index
                .lock()
                .by_entry
                .get(&entry_hash)
                .copied()
        };
        if let Some(record) = record {
            let _ = self.validate_merge_carrier_record_under_prune_and_canonical_guards(record)?;
        }
        self.ensure_prune_recovery_not_required()?;
        Ok(record)
    }
    /// Resolve the complete committed merge entry carried by an exact global block.
    ///
    /// This reads the complete merge log rather than the capacity-truncated
    /// in-memory cache and revalidates the sparse carrier and compact reference.
    pub(crate) fn merge_entry_for_carrier(
        &self,
        block_height: u64,
        block_hash: HashOf<BlockHeader>,
    ) -> Result<Option<MergeLedgerEntry>> {
        let _prune_guard = self.prune_lock.lock();
        self.merge_entry_for_carrier_under_prune_guard(block_height, block_hash)
    }
    fn merge_entry_for_carrier_under_prune_guard(
        &self,
        block_height: u64,
        block_hash: HashOf<BlockHeader>,
    ) -> Result<Option<MergeLedgerEntry>> {
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.merge_entry_for_carrier_under_prune_and_canonical_guards(block_height, block_hash)
    }
    fn merge_entry_for_carrier_under_prune_and_canonical_guards(
        &self,
        block_height: u64,
        block_hash: HashOf<BlockHeader>,
    ) -> Result<Option<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        let Some(record) = self.merge_carrier_record_for_block(block_height, block_hash)? else {
            self.ensure_prune_recovery_not_required()?;
            return Ok(None);
        };
        let entry = self.validate_merge_carrier_record_under_prune_and_canonical_guards(record)?;
        self.ensure_prune_recovery_not_required()?;
        Ok(Some(entry))
    }
    fn preflight_finalized_merge_carrier_at_under_prune_and_canonical_guards(
        &self,
        height: u64,
        header: &BlockHeader,
        finality: &V2FinalityArtifact,
    ) -> Result<FinalizedMergeCarrierAtHeight> {
        let block_hash = header.hash();
        let block_height = NonZeroUsize::new(usize::try_from(height)?)
            .ok_or_else(|| Error::MergeCarrierConflict("carrier height is zero".to_owned()))?;
        let block = self.get_block_without_merge_sidecar(block_height);
        let record = self.merge_carrier_record_for_block(height, block_hash)?;
        let expected = finality.commit_qc.execution_commitment.merge_carrier;
        let Some(expected) = expected else {
            if record.is_some()
                || block
                    .as_deref()
                    .and_then(Self::block_merge_reference)
                    .is_some()
            {
                return Err(Error::MergeCarrierConflict(format!(
                    "finalized block {height} has no signed merge carrier but retains carrier evidence"
                )));
            }
            return Ok(FinalizedMergeCarrierAtHeight::Complete);
        };
        expected.validate().map_err(|error| {
            Error::MergeCarrierConflict(format!(
                "finalized block {height} has an invalid merge-carrier commitment: {error}"
            ))
        })?;
        if let Some(record) = record {
            if record.entry_hash != expected.entry_hash {
                return Err(Error::MergeCarrierConflict(format!(
                    "finalized block {height} carrier record differs from its signed entry hash"
                )));
            }
            let _ = self.validate_merge_carrier_record_under_prune_and_canonical_guards(record)?;
            return Ok(FinalizedMergeCarrierAtHeight::Complete);
        }
        let Some(block) = block else {
            return Ok(FinalizedMergeCarrierAtHeight::MissingBody(block_hash));
        };
        if block.header() != *header {
            return Err(Error::MergeCarrierConflict(format!(
                "finalized block {height} cached body differs from retained finality"
            )));
        }
        let reference = Self::block_merge_reference(&block).ok_or_else(|| {
            Error::MergeCarrierConflict(format!(
                "finalized block {height} signs a merge carrier but its body has no compact reference"
            ))
        })?;
        if reference.entry_hash != expected.entry_hash {
            return Err(Error::MergeCarrierConflict(format!(
                "finalized block {height} compact reference differs from its signed merge carrier"
            )));
        }
        let entry = self
            .merge_entry_by_hash(expected.entry_hash)?
            .ok_or_else(|| {
                Error::MergeCarrierConflict(format!(
                    "finalized block {height} has no full merge entry for its signed carrier"
                ))
            })?;
        if !reference.matches_entry(&entry) {
            return Err(Error::MergeCarrierConflict(format!(
                "finalized block {height} compact reference differs from the full merge entry"
            )));
        }
        let planned_record = Self::carrier_record_for_block_entry(&block, &entry)?;
        Self::validate_merge_carrier_finality_projection(planned_record, &entry, header, finality)?;
        self.merge_log.lock().preflight_append(&entry)?;
        let _carrier_guard = self.merge_carrier_lock.lock();
        if !self.preflight_merge_carrier_record_unlocked(planned_record)? {
            return Err(Error::MergeCarrierConflict(format!(
                "finalized block {height} carrier appeared during read-only startup preflight"
            )));
        }
        Ok(FinalizedMergeCarrierAtHeight::Repair(
            FinalizedMergeCarrierRepair { block, entry },
        ))
    }
    /// Reverse-audit every verified finality projection through `committed_height`.
    pub(crate) fn preflight_finalized_merge_carrier_repairs(
        &self,
        committed_height: u64,
        capacity: usize,
    ) -> Result<FinalizedMergeCarrierRepairPreflight> {
        if capacity == 0 {
            return Err(Error::MergeCarrierConflict(
                "finalized merge-carrier startup preflight has zero capacity".to_owned(),
            ));
        }
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.ensure_canonical_storage_not_poisoned()?;
        let durable_height = u64::try_from(self.exact_durable_blocks_count()?)?;
        if committed_height > durable_height {
            return Err(Error::MergeCarrierConflict(format!(
                "State height {committed_height} exceeds durable Kura height {durable_height}"
            )));
        }
        let mut repairs = Vec::new();
        let mut missing_bodies = Vec::new();
        let mut planned_entries = BTreeSet::new();
        for height in 1..=committed_height {
            let Some((header, finality, _)) =
                self.v2_finality_artifact_with_archive_under_prune_and_canonical_guards(height)?
            else {
                continue;
            };
            match self.preflight_finalized_merge_carrier_at_under_prune_and_canonical_guards(
                height, &header, &finality,
            )? {
                FinalizedMergeCarrierAtHeight::Complete => {}
                FinalizedMergeCarrierAtHeight::MissingBody(block_hash) => {
                    missing_bodies.push((height, block_hash));
                }
                FinalizedMergeCarrierAtHeight::Repair(repair) => {
                    let entry_hash = repair.entry.canonical_hash();
                    if !planned_entries.insert(entry_hash) {
                        return Err(Error::MergeCarrierConflict(format!(
                            "finalized merge entry {entry_hash} is planned for more than one carrier"
                        )));
                    }
                    repairs.push(repair);
                }
            }
            if repairs.len().saturating_add(missing_bodies.len()) > capacity {
                return Err(Error::MergeCarrierConflict(format!(
                    "finalized merge-carrier startup repair exceeds capacity {capacity}"
                )));
            }
        }
        Ok(FinalizedMergeCarrierRepairPreflight {
            repairs,
            missing_bodies,
        })
    }
    /// Ensure a newly cached finalized body can reconstruct any signed missing
    /// merge-carrier record before generic recovery retires the body need.
    pub(crate) fn preflight_cached_finalized_merge_carrier_reconstruction(
        &self,
        block: &SignedBlock,
    ) -> Result<()> {
        let height = block.header().height().get();
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        let Some((header, finality, _)) =
            self.v2_finality_artifact_with_archive_under_prune_and_canonical_guards(height)?
        else {
            return Err(Error::MissingV2FinalityArtifact { height });
        };
        if header != block.header() {
            return Err(Error::MergeCarrierConflict(format!(
                "cached finalized body {height} differs from retained finality"
            )));
        }
        match self.preflight_finalized_merge_carrier_at_under_prune_and_canonical_guards(
            height, &header, &finality,
        )? {
            FinalizedMergeCarrierAtHeight::Complete | FinalizedMergeCarrierAtHeight::Repair(_) => {
                Ok(())
            }
            FinalizedMergeCarrierAtHeight::MissingBody(_) => Err(Error::MergeCarrierConflict(
                format!("cached finalized body {height} is not readable after publication"),
            )),
        }
    }
    /// Publish an all-item-preflighted finalized merge-carrier repair set and
    /// rebuild merge application receipts from authenticated committed entries.
    pub(crate) fn apply_finalized_merge_carrier_repairs(
        &self,
        repairs: &[FinalizedMergeCarrierRepair],
        repair_authorizations: Vec<Vec<PostCarrierEvidenceRepairAuthorization>>,
    ) -> Result<usize> {
        if repairs.is_empty() {
            if !repair_authorizations.is_empty() {
                return Err(Error::MergeCarrierConflict(
                    "empty finalized merge-carrier repair received repair authority".to_owned(),
                ));
            }
            return Ok(0);
        }
        if repair_authorizations.len() != repairs.len() {
            return Err(Error::MergeCarrierConflict(
                "finalized merge-carrier repair authority cardinality changed after preflight"
                    .to_owned(),
            ));
        }
        let durable_count = self.exact_durable_blocks_count()?;
        {
            let _prune_guard = self.prune_lock.lock();
            self.ensure_prune_recovery_not_required()?;
            let _canonical_chain_guard = self.canonical_chain_lock.lock();
            for expected in repairs {
                let height = expected.block.header().height().get();
                let Some((header, finality, _)) = self
                    .v2_finality_artifact_with_archive_under_prune_and_canonical_guards(height)?
                else {
                    return Err(Error::MissingV2FinalityArtifact { height });
                };
                match self.preflight_finalized_merge_carrier_at_under_prune_and_canonical_guards(
                    height, &header, &finality,
                )? {
                    FinalizedMergeCarrierAtHeight::Repair(actual) if actual == *expected => {}
                    _ => {
                        return Err(Error::MergeCarrierConflict(format!(
                            "finalized merge carrier {height} changed after all-item preflight"
                        )));
                    }
                }
            }
            // Consume the complete move-only repair set after the raw
            // finality/body/entry revalidation and before the first reverse
            // carrier, transaction-index, or receipt publication.
            for (repair, authorizations) in repairs.iter().zip(repair_authorizations.into_iter()) {
                self.consume_post_carrier_evidence_repair_authorizations(
                    &repair.entry,
                    repair.block.header().height().get(),
                    repair.block.hash(),
                    authorizations,
                )?;
            }
            for repair in repairs {
                let _ = self.append_committed_merge_entry_for_block_if_missing(
                    &repair.block,
                    &repair.entry,
                )?;
                let height = usize::try_from(repair.block.header().height().get())?;
                self.set_transaction_entrypoint_index_entry_with_merge(
                    height,
                    &repair.block,
                    Some(&repair.entry),
                    durable_count,
                    true,
                );
                let record = Self::carrier_record_for_block_entry(&repair.block, &repair.entry)?;
                let _ =
                    self.validate_merge_carrier_record_under_prune_and_canonical_guards(record)?;
            }
        }
        for repair in repairs {
            self.persist_merge_lane_block_application_receipts_after_repair_authorization(
                &repair.entry,
                repair.block.header().height().get(),
                repair.block.hash(),
            )?;
            self.remove_committed_pending_merge_entry_best_effort(repair.entry.canonical_hash());
        }
        Ok(repairs.len())
    }
    /// Resolve the complete committed merge entry carried at a canonical block height.
    ///
    /// The lookup is index-backed and validates the complete durable log length,
    /// sparse carrier record, canonical block hash, compact block reference, and
    /// full merge-log entry before returning.
    ///
    /// # Errors
    /// Returns an error when the canonical carrier metadata or full merge entry is
    /// unavailable, malformed, or inconsistent with the block log.
    pub fn get_merge_entry_by_carrier_height(
        &self,
        block_height: NonZeroUsize,
    ) -> Result<Option<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        self.merge_log.lock().validate_indexed_file_length()?;
        let Some(block_hash) = self.get_block_hash(block_height) else {
            return Ok(None);
        };
        self.merge_entry_for_carrier(u64::try_from(block_height.get())?, block_hash)
    }
    /// Return every globally carried execution entry in sparse carrier order.
    ///
    /// The result is complete regardless of merge-log cache capacity.
    pub(crate) fn committed_merge_execution_entries(
        &self,
    ) -> Result<Vec<(MergeLedgerCarrierRecord, MergeLedgerEntry)>> {
        self.ensure_prune_recovery_not_required()?;
        #[cfg(test)]
        {
            let mut merge_log = self.merge_log.lock();
            merge_log.complete_execution_scans =
                merge_log.complete_execution_scans.saturating_add(1);
        }
        for _ in 0..2 {
            let records = self.merge_carrier_records()?;
            let generation = self.merge_carrier_index.lock().generation;
            let mut committed = Vec::new();
            for record in records {
                let entry = self
                    .merge_log
                    .lock()
                    .entry_by_hash(record.entry_hash)?
                    .ok_or_else(|| {
                        Error::MergeCarrierConflict(format!(
                            "carrier block {} references a missing committed merge entry",
                            record.block_height
                        ))
                    })?;
                if entry.execution_batch.is_some() {
                    committed.push((record, entry));
                }
            }
            if self.merge_carrier_index.lock().generation == generation {
                self.ensure_prune_recovery_not_required()?;
                return Ok(committed);
            }
        }
        Err(Error::MergeCarrierConflict(
            "sparse merge carriers changed during complete query snapshot".to_owned(),
        ))
    }
    /// Snapshot every sparse merge carrier after validating each record against
    /// the canonical durable block hash. The result is ordered by block height.
    ///
    /// # Errors
    /// Returns an error if the carrier index is malformed or references a
    /// non-canonical block.
    pub(crate) fn merge_carrier_records(&self) -> Result<Vec<MergeLedgerCarrierRecord>> {
        let _prune_guard = self.prune_lock.lock();
        self.merge_carrier_records_under_prune_guard()
    }
    fn merge_carrier_records_under_prune_guard(&self) -> Result<Vec<MergeLedgerCarrierRecord>> {
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.merge_carrier_records_under_prune_and_canonical_guards()
    }
    fn merge_carrier_records_under_prune_and_canonical_guards(
        &self,
    ) -> Result<Vec<MergeLedgerCarrierRecord>> {
        self.ensure_prune_recovery_not_required()?;
        for _ in 0..2 {
            let (records, generation) = {
                let _guard = self.merge_carrier_lock.lock();
                let records = self.merge_carrier_records_unlocked()?;
                let generation = self.merge_carrier_index.lock().generation;
                (records, generation)
            };
            for record in records.iter().copied() {
                let _ =
                    self.validate_merge_carrier_record_under_prune_and_canonical_guards(record)?;
            }
            if self.merge_carrier_index.lock().generation == generation {
                self.ensure_prune_recovery_not_required()?;
                return Ok(records);
            }
        }
        Err(Error::MergeCarrierConflict(
            "sparse merge carriers changed during validated snapshot".to_owned(),
        ))
    }
    fn merge_carrier_records_for_prune_under_prune_and_canonical_guards(
        &self,
        retained_height: u64,
    ) -> Result<Vec<MergeLedgerCarrierRecord>> {
        self.ensure_prune_recovery_not_required()?;
        for _ in 0..2 {
            let (records, generation) = {
                let _guard = self.merge_carrier_lock.lock();
                let records = self.merge_carrier_records_unlocked()?;
                let generation = self.merge_carrier_index.lock().generation;
                (records, generation)
            };
            for record in records.iter().copied() {
                if record.block_height <= retained_height {
                    let _ = self
                        .validate_merge_carrier_record_under_prune_and_canonical_guards(record)?;
                    continue;
                }
                // A pruned, unfinalized suffix is never exposed as committed
                // carrier evidence. It must still bind exactly to the durable
                // canonical body, merge log, and sparse carrier record before
                // destructive removal. Retained records continue to require
                // current-version QC-authenticated finality above.
                let height =
                    NonZeroUsize::new(usize::try_from(record.block_height)?).ok_or_else(|| {
                        Error::MergeCarrierConflict("carrier height is zero".to_owned())
                    })?;
                let block = self
                    .get_block_without_merge_sidecar(height)
                    .ok_or_else(|| {
                        Error::MergeCarrierConflict(format!(
                            "pruned unfinalized carrier {} has no recoverable canonical body",
                            record.block_height
                        ))
                    })?;
                let expected = self
                    .merge_carrier_commitment_for_finality_prepublication_under_prune_and_canonical_guards(
                        height,
                        &block.header(),
                    )?;
                let actual = Some(
                    iroha_data_model::block::consensus_v2::MergeCarrierCommitmentV1::new(
                        record.entry_hash,
                    ),
                );
                if expected != actual {
                    return Err(Error::MergeCarrierConflict(format!(
                        "pruned unfinalized carrier {} differs from its canonical body",
                        record.block_height
                    )));
                }
            }
            if self.merge_carrier_index.lock().generation == generation {
                self.ensure_prune_recovery_not_required()?;
                return Ok(records);
            }
        }
        Err(Error::MergeCarrierConflict(
            "sparse merge carriers changed during prune validation".to_owned(),
        ))
    }
    fn merge_carrier_records_for_startup_prepublication_reconciliation(
        &self,
        durable_tip: u64,
        allow_pending_tip: bool,
    ) -> Result<(Vec<MergeLedgerCarrierRecord>, BTreeMap<u64, BlockHeader>)> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.ensure_canonical_storage_not_poisoned()?;
        for _ in 0..2 {
            let (records, generation) = {
                let _guard = self.merge_carrier_lock.lock();
                let records = self.merge_carrier_records_unlocked()?;
                let generation = self.merge_carrier_index.lock().generation;
                (records, generation)
            };
            let mut finalized_headers = BTreeMap::new();
            for record in records.iter().copied() {
                match self.validate_merge_carrier_record_under_prune_and_canonical_guards(record) {
                    Ok(_) => {
                        let (header, _, _) = self
                            .v2_finality_artifact_with_archive_under_prune_and_canonical_guards(
                                record.block_height,
                            )?
                            .ok_or_else(|| {
                                Error::MergeCarrierConflict(format!(
                                    "finalized carrier {} lost its retained finality header",
                                    record.block_height
                                ))
                            })?;
                        finalized_headers.insert(record.block_height, header);
                    }
                    Err(strict_error) => {
                        let finality = self
                            .v2_finality_artifact_with_archive_under_prune_and_canonical_guards(
                                record.block_height,
                            )?;
                        if !allow_pending_tip
                            || record.block_height != durable_tip
                            || finality.is_some()
                        {
                            return Err(strict_error);
                        }
                        let height = NonZeroUsize::new(usize::try_from(record.block_height)?)
                            .ok_or_else(|| {
                                Error::MergeCarrierConflict(
                                    "pending carrier height is zero".to_owned(),
                                )
                            })?;
                        let block = self.get_block_without_merge_sidecar(height).ok_or_else(
                            || {
                                Error::MergeCarrierConflict(format!(
                                    "unfinalized carrier tip {} has no recoverable canonical body",
                                    record.block_height
                                ))
                            },
                        )?;
                        let expected = self
                            .merge_carrier_commitment_for_finality_prepublication_under_prune_and_canonical_guards(
                                height,
                                &block.header(),
                            )?;
                        let actual = Some(
                            iroha_data_model::block::consensus_v2::MergeCarrierCommitmentV1::new(
                                record.entry_hash,
                            ),
                        );
                        if expected != actual {
                            return Err(Error::MergeCarrierConflict(format!(
                                "unfinalized carrier tip {} differs from its prepublication body",
                                record.block_height
                            )));
                        }
                    }
                }
            }
            if self.merge_carrier_index.lock().generation == generation {
                return Ok((records, finalized_headers));
            }
        }
        Err(Error::MergeCarrierConflict(
            "sparse merge carriers changed during startup reconciliation".to_owned(),
        ))
    }
    fn reconcile_merge_carriers_during_snapshot_finalization(
        &self,
        authority: &SnapshotFinalizationMutationAuthority<'_>,
    ) -> Result<()> {
        authority.validate_for(self)?;
        self.reconcile_merge_carriers_from_durable_blocks_with_authority(
            Some(authority),
            false,
            true,
        )
    }
    fn reconcile_merge_carriers_from_durable_blocks_with_authority(
        &self,
        finalization_authority: Option<&SnapshotFinalizationMutationAuthority<'_>>,
        reject_missing_retained_carrier: bool,
        scan_canonical_bodies: bool,
    ) -> Result<()> {
        if let Some(authority) = finalization_authority {
            authority.validate_for(self)?;
        }
        self.validate_pending_merge_entries_on_startup()?;
        let block_count = self.exact_durable_blocks_count()?;
        let block_count_u64 = u64::try_from(block_count)?;
        // Recover the only intentionally non-atomic window in the publication
        // sequence: merge log -> carrier sidecar -> canonical block. Complete
        // carrier temporaries are published only when their exact block is
        // already durable. A suffix whose QC targets heights beyond the durable
        // block log is an uncommitted crash remnant and is rolled back as one
        // unit; records at committed heights are never silently discarded.
        {
            let _guard = self.merge_carrier_lock.lock();
            self.reconcile_merge_carrier_temp_files_unlocked()?;
            let records = self.merge_carrier_records_from_disk_unlocked()?;
            {
                let mut index = self.merge_carrier_index.lock();
                index.by_height = records
                    .iter()
                    .map(|record| (record.block_height, *record))
                    .collect();
                index.by_entry = records
                    .iter()
                    .map(|record| (record.entry_hash, *record))
                    .collect();
                index.initialized = true;
                index.generation = index.generation.saturating_add(1);
                #[cfg(test)]
                {
                    index.directory_scans = index.directory_scans.saturating_add(1);
                }
            }
            let future_records = records
                .iter()
                .copied()
                .filter(|record| record.block_height > block_count_u64)
                .collect::<Vec<_>>();
            let (staged_entries, retained_len) = {
                let mut merge_log = self.merge_log.lock();
                let frames = merge_log
                    .frames_by_epoch
                    .values()
                    .rev()
                    .copied()
                    .collect::<Vec<_>>();
                let mut staged = Vec::new();
                for frame in frames {
                    let entry = merge_log.entry_by_hash(frame.entry_hash)?.ok_or_else(|| {
                        Error::MergeCarrierConflict(
                            "merge suffix index references a missing frame".to_owned(),
                        )
                    })?;
                    if entry.merge_qc.carrier_height <= block_count_u64 {
                        break;
                    }
                    staged.push(entry);
                }
                let retained_len = merge_log.total_entries.saturating_sub(staged.len());
                (staged, retained_len)
            };
            let staged_by_hash = staged_entries
                .iter()
                .map(|entry| (entry.canonical_hash(), entry))
                .collect::<BTreeMap<_, _>>();
            for record in &future_records {
                let entry = staged_by_hash.get(&record.entry_hash).ok_or_else(|| {
                    Error::MergeCarrierConflict(format!(
                        "future carrier at block {} is not part of the uncommitted merge-log suffix",
                        record.block_height
                    ))
                })?;
                if entry.epoch_id != record.epoch_id
                    || entry.merge_qc.carrier_height != record.block_height
                {
                    return Err(Error::MergeCarrierConflict(format!(
                        "future carrier at block {} differs from its staged merge entry",
                        record.block_height
                    )));
                }
            }
            for record in future_records.iter().rev().copied() {
                self.remove_merge_carrier_record_unlocked(record)?;
            }
            if !staged_entries.is_empty() {
                self.truncate_merge_log_to_len(retained_len)?;
            }
        }
        // Repair the sole block-first crash window from exact canonical body
        // bytes, but keep every merge-derived transaction index explicitly
        // incomplete until the repaired carrier is authenticated by durable
        // current-version finality below.
        if scan_canonical_bodies {
            for height in 1..=block_count {
                let height = NonZeroUsize::new(height).expect("durable block height is non-zero");
                let Some(block) = self.get_block_without_merge_sidecar(height) else {
                    continue;
                };
                let Some(reference) = Self::block_merge_reference(&block) else {
                    continue;
                };
                let entry = self.merge_entry_by_hash(reference.entry_hash)?.ok_or(
                    Error::MissingCertifiedMergeSidecar {
                        entry_hash: reference.entry_hash,
                    },
                )?;
                if !reference.matches_entry(&entry) {
                    return Err(Error::MergeReferenceMismatch(format!(
                        "canonical block {} compact reference does not match its sidecar",
                        height.get()
                    )));
                }
                if reject_missing_retained_carrier {
                    let record = Self::carrier_record_for_block_entry(&block, &entry)?;
                    let _guard = self.merge_carrier_lock.lock();
                    if self.preflight_merge_carrier_record_unlocked(record)? {
                        return Err(Error::PruneIntentConflict(format!(
                            "active prune cannot allocate missing retained merge carrier at block {}",
                            height.get()
                        )));
                    }
                } else {
                    self.append_committed_merge_entry_for_block_if_missing(&block, &entry)?;
                }
                self.set_transaction_entrypoint_index_entry_with_merge(
                    height.get(),
                    &block,
                    None,
                    block_count,
                    false,
                );
            }
        }
        // Existing carrier files must never silently migrate to another
        // block. A normal process restart may retain only the sole durable tip
        // as an unpublished pre-finality recovery candidate; snapshot
        // finalization requires every carrier to be fully authenticated.
        let (records, finalized_carrier_headers) = self
            .merge_carrier_records_for_startup_prepublication_reconciliation(
                block_count_u64,
                finalization_authority.is_none(),
            )?;
        for record in records {
            let Some(finalized_header) = finalized_carrier_headers.get(&record.block_height) else {
                continue;
            };
            let entry = self
                .merge_entry_by_hash(record.entry_hash)?
                .ok_or_else(|| {
                    Error::MergeCarrierConflict(format!(
                        "finalized carrier {} lost its merge-log entry during startup",
                        record.block_height
                    ))
                })?;
            let height = NonZeroUsize::new(usize::try_from(record.block_height)?)
                .ok_or_else(|| Error::MergeCarrierConflict("carrier height is zero".to_owned()))?;
            if scan_canonical_bodies
                && let Some(block) = self.get_block_without_merge_sidecar(height)
            {
                self.set_transaction_entrypoint_index_entry_with_merge(
                    height.get(),
                    &block,
                    Some(&entry),
                    block_count,
                    true,
                );
            } else {
                self.set_transaction_entrypoint_index_entry_from_finalized_bodyless_merge(
                    height.get(),
                    finalized_header,
                    &entry,
                    block_count,
                )?;
            }
            if finalization_authority.is_some() {
                self.remove_pending_certified_merge_entry_after_authorization(record.entry_hash)?;
            } else {
                self.remove_pending_certified_merge_entry(record.entry_hash)?;
            }
        }
        Ok(())
    }
    fn pending_merge_entry_dir(&self) -> PathBuf {
        self.store_root.join(PENDING_MERGE_ENTRIES_DIR)
    }
    fn pending_merge_entry_path(&self, hash: HashOf<MergeLedgerEntry>) -> PathBuf {
        self.pending_merge_entry_dir()
            .join(format!("{}.norito", hex::encode(hash.as_ref())))
    }
    fn invalid_pending_merge_entry_error(path: PathBuf, message: impl Into<String>) -> Error {
        Error::IO(
            std::io::Error::new(ErrorKind::InvalidData, message.into()),
            path,
        )
    }
    fn validate_pending_merge_hash_text(path: &Path, hash_text: &str) -> Result<()> {
        let decoded_hash = hex::decode(hash_text).map_err(|_| {
            Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge filename is not a canonical hash",
            )
        })?;
        if decoded_hash.len() != Hash::LENGTH || hex::encode(&decoded_hash) != hash_text {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge filename is not a canonical lowercase hash",
            ));
        }
        Ok(())
    }
    fn ensure_pending_merge_entry_dir_unlocked(&self) -> Result<()> {
        let directory = self.pending_merge_entry_dir();
        match std::fs::symlink_metadata(&directory) {
            Ok(_) => {
                self.canonical_sidecar_directory(&directory)?
                    .ok_or_else(|| {
                        Self::invalid_pending_merge_entry_error(
                            directory.clone(),
                            "pending merge directory disappeared",
                        )
                    })?;
            }
            Err(error) if error.kind() == ErrorKind::NotFound => {
                std::fs::create_dir(&directory)
                    .map_err(|error| Error::MkDir(error, directory.clone()))?;
                sync_dir(&self.store_root)
                    .map_err(|error| Error::IO(error, self.store_root.clone()))?;
                sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
                self.canonical_sidecar_directory(&directory)?
                    .ok_or_else(|| {
                        Self::invalid_pending_merge_entry_error(
                            directory.clone(),
                            "new pending merge directory disappeared",
                        )
                    })?;
            }
            Err(error) => return Err(Error::IO(error, directory)),
        }
        Ok(())
    }
    fn create_exclusive_pending_merge_temp(&self, path: &Path) -> Result<std::fs::File> {
        let directory = self.pending_merge_entry_dir();
        if path.parent() != Some(directory.as_path()) {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge temporary is outside its direct directory",
            ));
        }
        let (_, directory_before) =
            self.canonical_sidecar_directory(&directory)?
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        directory.clone(),
                        "pending merge directory does not exist",
                    )
                })?;
        let file_name = path.file_name().ok_or_else(|| {
            Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge temporary has no filename",
            )
        })?;
        #[cfg(unix)]
        let file = {
            use std::os::unix::fs::OpenOptionsExt as _;
            let mut directory_options = std::fs::OpenOptions::new();
            directory_options.read(true).custom_flags(
                (rustix::fs::OFlags::DIRECTORY
                    | rustix::fs::OFlags::NOFOLLOW
                    | rustix::fs::OFlags::CLOEXEC)
                    .bits() as i32,
            );
            let opened_directory = directory_options
                .open(&directory)
                .map_err(|error| Error::IO(error, directory.clone()))?;
            let opened_directory_metadata = opened_directory
                .metadata()
                .map_err(|error| Error::IO(error, directory.clone()))?;
            if !opened_directory_metadata.is_dir()
                || !Self::sidecar_metadata_same_object(
                    &directory_before,
                    &opened_directory_metadata,
                )
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory.clone(),
                    "pending merge directory changed while binding it",
                ));
            }
            std::fs::File::from(
                rustix::fs::openat(
                    &opened_directory,
                    file_name,
                    rustix::fs::OFlags::WRONLY
                        | rustix::fs::OFlags::CREATE
                        | rustix::fs::OFlags::EXCL
                        | rustix::fs::OFlags::NOFOLLOW
                        | rustix::fs::OFlags::CLOEXEC,
                    rustix::fs::Mode::RUSR | rustix::fs::Mode::WUSR,
                )
                .map_err(std::io::Error::from)
                .map_err(|error| Error::IO(error, path.to_path_buf()))?,
            )
        };
        #[cfg(not(unix))]
        let file = {
            let mut options = std::fs::OpenOptions::new();
            options.create_new(true).write(true);
            #[cfg(windows)]
            {
                use std::os::windows::fs::OpenOptionsExt as _;
                const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
                options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
            }
            options
                .open(path)
                .map_err(|error| Error::IO(error, path.to_path_buf()))?
        };
        let opened = secure_file_metadata::from_file(&file)
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let path_metadata = secure_file_metadata::from_path(path)
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let (_, directory_after) =
            self.canonical_sidecar_directory(&directory)?
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        directory.clone(),
                        "pending merge directory disappeared while creating a temporary",
                    )
                })?;
        if !opened.is_file()
            || path_metadata.file_type().is_symlink()
            || !path_metadata.file_type().is_file()
            || !Self::sidecar_is_single_link(&opened)
            || !Self::sidecar_is_single_link(&path_metadata)
            || !Self::sidecar_metadata_same_object(&opened, &path_metadata)
            || !Self::sidecar_metadata_same_object(&directory_before, &directory_after)
        {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge temporary identity changed during creation",
            ));
        }
        Ok(file)
    }
