    fn read_pending_queue_plan_admission_path(
        &self,
        path: &Path,
        expected_hash: Option<Hash>,
    ) -> Result<Option<(Hash, Vec<u8>)>> {
        let Some(bytes) = self.read_regular_sidecar_bytes(
            path,
            &self.pending_queue_plan_admission_dir(),
            MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES,
        )?
        else {
            return Ok(None);
        };
        if bytes.is_empty() {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission certificate is empty",
            ));
        }
        let hash = Hash::new(&bytes);
        if expected_hash.is_some_and(|expected| expected != hash)
            || self.pending_queue_plan_admission_path(hash) != path
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission certificate path/hash mismatch",
            ));
        }
        Ok(Some((hash, bytes)))
    }
    fn validate_pending_queue_plan_admission_temp_bytes(
        &self,
        path: &Path,
        hash_text: &str,
        bytes: &[u8],
    ) -> Result<Hash> {
        if bytes.is_empty() || bytes.len() > MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission temporary violates its hard byte limit",
            ));
        }
        let hash = Hash::new(bytes);
        if hex::encode(hash.as_ref()) != hash_text {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission temporary bytes do not match their hash path",
            ));
        }
        Ok(hash)
    }
    fn pending_control_recovery_directory_bytes_unlocked(
        &self,
        directory: &Path,
        max_stable_count: usize,
        max_file_bytes: usize,
        queue_plan_admission: bool,
    ) -> Result<usize> {
        #[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
        enum RecoveryFileIdentity {
            #[cfg(unix)]
            Unix { device: u64, inode: u64 },
            #[cfg(windows)]
            Windows { volume: u32, index: u64 },
            #[cfg(not(unix))]
            Synthetic(usize),
        }
        struct RecoveryRecord {
            path: PathBuf,
            hash_text: String,
            is_temporary: bool,
            metadata: SecureMetadata,
            identity: RecoveryFileIdentity,
        }
        struct RecoveryAliases {
            first: usize,
            second: Option<usize>,
            count: usize,
        }
        let invalid = |path: PathBuf, message: String| {
            if queue_plan_admission {
                Self::invalid_pending_queue_plan_admission_error(path, message)
            } else {
                Self::invalid_pending_merge_entry_error(path, message)
            }
        };
        let (_, directory_before) =
            self.canonical_sidecar_directory(directory)?
                .ok_or_else(|| {
                    invalid(
                        directory.to_path_buf(),
                        "pending control recovery directory does not exist".to_owned(),
                    )
                })?;
        let read_dir = std::fs::read_dir(directory)
            .map_err(|error| Error::IO(error, directory.to_path_buf()))?;
        let mut records: Vec<RecoveryRecord> = Vec::new();
        let mut stable_count = 0usize;
        let mut temporary_count = 0usize;
        let mut unique_bytes = 0usize;
        let mut aliases_by_identity = BTreeMap::<RecoveryFileIdentity, RecoveryAliases>::new();
        for entry in read_dir {
            if records.len() == max_stable_count.saturating_add(1) {
                return Err(invalid(
                    directory.to_path_buf(),
                    "pending control recovery entry count exceeds its hard limit".to_owned(),
                ));
            }
            let entry = entry.map_err(|error| Error::IO(error, directory.to_path_buf()))?;
            let path = entry.path();
            let file_name = entry
                .file_name()
                .to_str()
                .map(str::to_owned)
                .ok_or_else(|| {
                    invalid(
                        path.clone(),
                        "pending control recovery directory contains a non-UTF-8 entry".to_owned(),
                    )
                })?;
            let (hash_text, is_temporary) = if let Some(hash_text) =
                file_name.strip_suffix(".norito.tmp")
            {
                temporary_count = temporary_count.saturating_add(1);
                if temporary_count > 1 {
                    return Err(invalid(
                        directory.to_path_buf(),
                        "pending control recovery directory contains multiple temporaries"
                            .to_owned(),
                    ));
                }
                (hash_text, true)
            } else if let Some(hash_text) = file_name.strip_suffix(".norito") {
                stable_count = stable_count.saturating_add(1);
                if stable_count > max_stable_count {
                    return Err(invalid(
                        directory.to_path_buf(),
                        "pending control recovery stable entry count exceeds its hard limit"
                            .to_owned(),
                    ));
                }
                (hash_text, false)
            } else {
                return Err(invalid(
                    path,
                    "pending control recovery directory contains an unexpected entry".to_owned(),
                ));
            };
            if queue_plan_admission {
                Self::validate_pending_queue_plan_admission_hash_text(&path, hash_text)?;
            } else {
                Self::validate_pending_merge_hash_text(&path, hash_text)?;
            }
            let metadata = secure_file_metadata::from_path(&path)
                .map_err(|error| Error::IO(error, path.clone()))?;
            if metadata.file_type().is_symlink()
                || !metadata.file_type().is_file()
                || (!Self::sidecar_has_link_count(&metadata, 1)
                    && !Self::sidecar_has_link_count(&metadata, 2))
            {
                return Err(invalid(
                    path,
                    "pending control recovery entry is not a one- or two-link regular no-follow file"
                        .to_owned(),
                ));
            }
            let file_bytes = usize::try_from(metadata.len())?;
            if file_bytes == 0 || file_bytes > max_file_bytes {
                return Err(invalid(
                    path,
                    "pending control recovery entry violates its per-file byte limit".to_owned(),
                ));
            }
            #[cfg(unix)]
            let identity = {
                use std::os::unix::fs::MetadataExt as _;
                RecoveryFileIdentity::Unix {
                    device: metadata.dev(),
                    inode: metadata.ino(),
                }
            };
            #[cfg(windows)]
            let identity = {
                match (metadata.volume_serial_number(), metadata.file_index()) {
                    (Some(volume), Some(index)) => RecoveryFileIdentity::Windows { volume, index },
                    // Match `sidecar_metadata_same_object`: missing Windows identity
                    // components never establish aliasing, so a two-link record
                    // remains fail-closed during the pair check below.
                    _ => RecoveryFileIdentity::Synthetic(records.len()),
                }
            };
            #[cfg(all(not(unix), not(windows)))]
            let identity = RecoveryFileIdentity::Synthetic(records.len());
            let record_index = records.len();
            // The previous all-prior-record metadata scan made configured
            // maximum inventories quadratic. One ordered identity group keeps
            // byte de-duplication and exact alias validation O(n log n).
            match aliases_by_identity.entry(identity) {
                std::collections::btree_map::Entry::Vacant(slot) => {
                    unique_bytes = unique_bytes.checked_add(file_bytes).ok_or_else(|| {
                        invalid(
                            directory.to_path_buf(),
                            "pending control recovery byte count overflow".to_owned(),
                        )
                    })?;
                    if !self
                        .pending_control_sidecar_limits
                        .merge_bytes_within_limit(unique_bytes)
                    {
                        return Err(invalid(
                            directory.to_path_buf(),
                            "pending control recovery bytes exceed their aggregate hard limit"
                                .to_owned(),
                        ));
                    }
                    slot.insert(RecoveryAliases {
                        first: record_index,
                        second: None,
                        count: 1,
                    });
                }
                std::collections::btree_map::Entry::Occupied(mut slot) => {
                    let aliases = slot.get_mut();
                    aliases.count = aliases.count.saturating_add(1);
                    if aliases.second.is_none() {
                        aliases.second = Some(record_index);
                    }
                }
            }
            records.push(RecoveryRecord {
                path,
                hash_text: hash_text.to_owned(),
                is_temporary,
                metadata,
                identity,
            });
        }
        for record in &records {
            if !Self::sidecar_has_link_count(&record.metadata, 2) {
                continue;
            }
            let Some(aliases) = aliases_by_identity.get(&record.identity) else {
                return Err(invalid(
                    record.path.clone(),
                    "pending control recovery hard links are not one exact temporary/target pair"
                        .to_owned(),
                ));
            };
            let Some(second) = aliases.second.filter(|_| aliases.count == 2) else {
                return Err(invalid(
                    record.path.clone(),
                    "pending control recovery hard links are not one exact temporary/target pair"
                        .to_owned(),
                ));
            };
            let left = &records[aliases.first];
            let right = &records[second];
            if left.is_temporary == right.is_temporary || left.hash_text != right.hash_text {
                return Err(invalid(
                    record.path.clone(),
                    "pending control recovery hard links are not one exact temporary/target pair"
                        .to_owned(),
                ));
            }
        }
        let (_, directory_after) =
            self.canonical_sidecar_directory(directory)?
                .ok_or_else(|| {
                    invalid(
                        directory.to_path_buf(),
                        "pending control recovery directory disappeared during inventory"
                            .to_owned(),
                    )
                })?;
        if !Self::sidecar_directory_metadata_unchanged(&directory_before, &directory_after) {
            return Err(invalid(
                directory.to_path_buf(),
                "pending control recovery directory changed during inventory".to_owned(),
            ));
        }
        Ok(unique_bytes)
    }
    fn preflight_pending_control_recovery_unlocked(&self) -> Result<(usize, usize)> {
        self.ensure_pending_merge_entry_dir_unlocked()?;
        self.ensure_pending_queue_plan_admission_dir_unlocked()?;
        let merge_bytes = self.pending_control_recovery_directory_bytes_unlocked(
            &self.pending_merge_entry_dir(),
            self.pending_control_sidecar_limits.certified_merge_entries,
            MAX_MERGE_LEDGER_ENTRY_BYTES,
            false,
        )?;
        let admission_bytes = self.pending_control_recovery_directory_bytes_unlocked(
            &self.pending_queue_plan_admission_dir(),
            self.pending_control_sidecar_limits.queue_plan_admissions,
            MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES,
            true,
        )?;
        if !self
            .pending_control_sidecar_limits
            .combined_bytes_within_limit(merge_bytes, admission_bytes)
        {
            return Err(Self::invalid_pending_merge_entry_error(
                self.store_root.clone(),
                "pending merge and QueuePlan admission recovery bytes exceed their shared hard limit",
            ));
        }
        Ok((merge_bytes, admission_bytes))
    }
    fn pending_merge_entry_paths_unlocked(&self) -> Result<(Vec<PathBuf>, usize)> {
        let directory = self.pending_merge_entry_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok((Vec::new(), 0)),
            Err(err) => return Err(Error::IO(err, directory)),
        };
        let mut paths = Vec::new();
        let mut total_bytes = 0usize;
        for entry in read_dir {
            if paths.len() == self.pending_control_sidecar_limits.certified_merge_entries {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending certified merge entry count exceeds the hard limit",
                ));
            }
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory contains a non-UTF-8 entry",
                ));
            };
            let Some(hash_text) = file_name.strip_suffix(".norito") else {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory contains an unexpected non-Norito entry",
                ));
            };
            Self::validate_pending_merge_hash_text(&path, hash_text)?;
            let metadata = secure_file_metadata::from_path(&path)
                .map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink()
                || !metadata.file_type().is_file()
                || !Self::sidecar_is_single_link(&metadata)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory entry is not a single-link regular no-follow file",
                ));
            }
            let file_bytes = usize::try_from(metadata.len())?;
            total_bytes = total_bytes.checked_add(file_bytes).ok_or_else(|| {
                Self::invalid_pending_merge_entry_error(
                    directory.clone(),
                    "pending certified merge byte count overflow",
                )
            })?;
            if !self
                .pending_control_sidecar_limits
                .merge_bytes_within_limit(total_bytes)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending certified merge bytes exceed the aggregate hard limit",
                ));
            }
            paths.push(path);
        }
        paths.sort();
        Ok((paths, total_bytes))
    }
    fn validate_pending_merge_entries_on_startup(&self) -> Result<()> {
        let _guard = self.sidecar_lock.lock();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.reconcile_pending_queue_plan_admission_temp_files_unlocked()?;
        let (merge_paths, merge_bytes) = self.pending_merge_entry_paths_unlocked()?;
        let (admission_paths, admission_bytes) =
            self.pending_queue_plan_admission_paths_unlocked()?;
        if !self
            .pending_control_sidecar_limits
            .combined_bytes_within_limit(merge_bytes, admission_bytes)
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                self.store_root.clone(),
                "pending merge and QueuePlan admission sidecars exceed their shared hard byte limit",
            ));
        }
        for path in merge_paths {
            let _ = self
                .read_pending_merge_entry_path(&path, None)?
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        path,
                        "pending merge sidecar disappeared during startup validation",
                    )
                })?;
        }
        for path in admission_paths {
            let _ = self
                .read_pending_queue_plan_admission_path(&path, None)?
                .ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        path,
                        "pending QueuePlan admission sidecar disappeared during startup validation",
                    )
                })?;
        }
        Ok(())
    }
    fn reconcile_pending_merge_temp_files_unlocked(&self) -> Result<()> {
        let _ = self.preflight_pending_control_recovery_unlocked()?;
        let directory = self.pending_merge_entry_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) => return Err(Error::IO(err, directory)),
        };
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let mut scanned = 0usize;
        let mut stable_count = 0usize;
        let mut total_bytes = 0usize;
        let mut path_bytes_before = 0u64;
        let mut temp_paths = Vec::new();
        #[cfg(unix)]
        let mut seen_inodes = BTreeSet::new();
        #[cfg(windows)]
        let mut seen_file_ids = BTreeSet::new();
        for entry in read_dir {
            scanned = scanned.saturating_add(1);
            if scanned
                > self
                    .pending_control_sidecar_limits
                    .certified_merge_entries
                    .saturating_add(1)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending merge directory entry count exceeds the crash-recovery limit",
                ));
            }
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let metadata = secure_file_metadata::from_path(&path)
                .map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink()
                || !metadata.file_type().is_file()
                || (!Self::sidecar_has_link_count(&metadata, 1)
                    && !Self::sidecar_has_link_count(&metadata, 2))
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge recovery entry is not a one- or two-link regular no-follow file",
                ));
            }
            path_bytes_before = path_bytes_before
                .checked_add(metadata.len())
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        directory.clone(),
                        "pending merge recovery path-byte count overflow",
                    )
                })?;
            #[cfg(unix)]
            let count_file_bytes = {
                use std::os::unix::fs::MetadataExt as _;
                seen_inodes.insert((metadata.dev(), metadata.ino()))
            };
            #[cfg(windows)]
            let count_file_bytes = {
                let volume = metadata.volume_serial_number().ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        path.clone(),
                        "pending merge recovery entry has no volume identity",
                    )
                })?;
                let index = metadata.file_index().ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        path.clone(),
                        "pending merge recovery entry has no file identity",
                    )
                })?;
                seen_file_ids.insert((volume, index))
            };
            #[cfg(all(not(unix), not(windows)))]
            let count_file_bytes = true;
            if count_file_bytes {
                total_bytes = total_bytes
                    .checked_add(usize::try_from(metadata.len())?)
                    .ok_or_else(|| {
                        Self::invalid_pending_merge_entry_error(
                            directory.clone(),
                            "pending merge directory byte count overflow",
                        )
                    })?;
            }
            if !self
                .pending_control_sidecar_limits
                .merge_bytes_within_limit(total_bytes)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending merge directory bytes exceed the aggregate hard limit",
                ));
            }
            let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory contains a non-UTF-8 entry",
                ));
            };
            if let Some(hash_text) = file_name.strip_suffix(".norito.tmp") {
                Self::validate_pending_merge_hash_text(&path, hash_text)?;
                temp_paths.push((path, hash_text.to_owned()));
                if temp_paths.len() > 1 {
                    return Err(Self::invalid_pending_merge_entry_error(
                        directory,
                        "pending merge directory contains multiple temporaries",
                    ));
                }
                continue;
            }
            let Some(hash_text) = file_name.strip_suffix(".norito") else {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory contains an unexpected recovery entry",
                ));
            };
            Self::validate_pending_merge_hash_text(&path, hash_text)?;
            stable_count = stable_count.saturating_add(1);
            if stable_count > self.pending_control_sidecar_limits.certified_merge_entries {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending certified merge entry count exceeds the hard limit",
                ));
            }
            continue;
        }
        for (temp_path, hash_text) in temp_paths {
            let temp_metadata = secure_file_metadata::from_path(&temp_path)
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            let target_path = directory.join(format!("{hash_text}.norito"));
            let target_metadata = match secure_file_metadata::from_path(&target_path) {
                Ok(metadata) => Some(metadata),
                Err(err) if err.kind() == ErrorKind::NotFound => None,
                Err(err) => return Err(Error::IO(err, target_path.clone())),
            };
            if let Some(target_metadata) = target_metadata.as_ref() {
                if target_metadata.file_type().is_symlink()
                    || !target_metadata.file_type().is_file()
                {
                    return Err(Self::invalid_pending_merge_entry_error(
                        target_path,
                        "pending merge recovery target is not a regular no-follow file",
                    ));
                }
                if Self::sidecar_metadata_same_object(&temp_metadata, target_metadata) {
                    if !Self::sidecar_has_link_count(&temp_metadata, 2)
                        || !Self::sidecar_has_link_count(target_metadata, 2)
                    {
                        return Err(Self::invalid_pending_merge_entry_error(
                            temp_path,
                            "pending merge recovery pair has an unexpected hard-link count",
                        ));
                    }
                    // A crash after `hard_link` legitimately leaves both
                    // names attached to the same two-link inode. Remove the
                    // temporary first so the ordinary single-link reader can
                    // authenticate the stable path without weakening its
                    // invariant.
                    std::fs::remove_file(&temp_path)
                        .map_err(|err| Error::IO(err, temp_path.clone()))?;
                    sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
                    let _ = self
                        .read_pending_merge_entry_path(&target_path, None)?
                        .ok_or_else(|| {
                            Self::invalid_pending_merge_entry_error(
                                target_path,
                                "published pending merge target disappeared during recovery",
                            )
                        })?;
                    continue;
                } else if !Self::sidecar_is_single_link(&temp_metadata)
                    || !Self::sidecar_is_single_link(target_metadata)
                {
                    return Err(Self::invalid_pending_merge_entry_error(
                        temp_path,
                        "conflicting pending merge recovery paths are not single-link files",
                    ));
                }
            }
            let bytes = self
                .read_regular_sidecar_bytes(&temp_path, &directory, MAX_MERGE_LEDGER_ENTRY_BYTES)?
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        temp_path.clone(),
                        "pending merge temporary disappeared during recovery",
                    )
                })?;
            let entry = norito::decode_canonical::<MergeLedgerEntry>(&bytes).map_err(|err| {
                Self::invalid_pending_merge_entry_error(
                    temp_path.clone(),
                    format!("pending merge temporary is not exact framed Norito: {err}"),
                )
            })?;
            if !entry.has_current_version() {
                return Err(Self::invalid_pending_merge_entry_error(
                    temp_path,
                    format!(
                        "pending merge temporary has unsupported merge ledger entry version {}",
                        entry.version
                    ),
                ));
            }
            if hex::encode(entry.canonical_hash().as_ref()) != hash_text
                || self.pending_merge_entry_path(entry.canonical_hash()) != target_path
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    temp_path,
                    "pending merge temporary bytes do not match their canonical hash path",
                ));
            }
            if let Some(existing) =
                self.read_pending_merge_entry_path(&target_path, Some(entry.canonical_hash()))?
            {
                if existing != entry {
                    return Err(Self::invalid_pending_merge_entry_error(
                        temp_path,
                        "pending merge temporary conflicts with its published target",
                    ));
                }
                std::fs::remove_file(&temp_path)
                    .map_err(|err| Error::IO(err, temp_path.clone()))?;
                sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
                continue;
            }
            if target_metadata.is_some() {
                return Err(Self::invalid_pending_merge_entry_error(
                    target_path,
                    "pending merge recovery target disappeared during validation",
                ));
            }
            if stable_count == self.pending_control_sidecar_limits.certified_merge_entries {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "unpublished pending merge temporary exceeds the entry-count hard limit",
                ));
            }
            if !Self::sidecar_is_single_link(&temp_metadata) {
                return Err(Self::invalid_pending_merge_entry_error(
                    temp_path,
                    "unpublished pending merge temporary is not a single-link file",
                ));
            }
            std::fs::File::open(&temp_path)
                .and_then(|file| file.sync_all())
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            std::fs::hard_link(&temp_path, &target_path)
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            let target_metadata = secure_file_metadata::from_path(&target_path)
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            if !Self::sidecar_metadata_same_object(&temp_metadata, &target_metadata)
                || !Self::sidecar_has_link_count(&target_metadata, 2)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    target_path,
                    "published pending merge target does not bind its durable temporary",
                ));
            }
            std::fs::File::open(&target_path)
                .and_then(|file| file.sync_all())
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            std::fs::remove_file(&temp_path).map_err(|err| Error::IO(err, temp_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
        }
        let (_, path_bytes_after) = self.pending_merge_entry_paths_unlocked()?;
        self.update_disk_usage_delta(path_bytes_before, u64::try_from(path_bytes_after)?);
        accounting_mutation.finish();
        Ok(())
    }
    fn reconcile_pending_queue_plan_admission_temp_files_unlocked(&self) -> Result<()> {
        let _ = self.preflight_pending_control_recovery_unlocked()?;
        let directory = self.pending_queue_plan_admission_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) => return Err(Error::IO(err, directory)),
        };
        // Recovery may unlink a crash-staged temporary after its stable hard
        // link is already visible. The usage scanners account directory
        // entries, so that unlink removes one full path's byte contribution
        // even though the underlying inode remains. Publish the exact
        // before/after delta here: callers may otherwise complete an
        // idempotent retry without performing any later write whose accounting
        // could repair the stale cache.
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let mut scanned = 0usize;
        let mut stable_count = 0usize;
        let mut total_bytes = 0usize;
        let mut path_bytes_before = 0u64;
        let mut temp_paths = Vec::new();
        #[cfg(unix)]
        let mut seen_inodes = BTreeSet::new();
        #[cfg(windows)]
        let mut seen_file_ids = BTreeSet::new();
        for entry in read_dir {
            scanned = scanned.saturating_add(1);
            if scanned
                > self
                    .pending_control_sidecar_limits
                    .queue_plan_admissions
                    .saturating_add(1)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "pending QueuePlan admission directory entry count exceeds the crash-recovery limit",
                ));
            }
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let metadata = secure_file_metadata::from_path(&path)
                .map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink()
                || !metadata.file_type().is_file()
                || (!Self::sidecar_has_link_count(&metadata, 1)
                    && !Self::sidecar_has_link_count(&metadata, 2))
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission recovery entry is not a one- or two-link regular no-follow file",
                ));
            }
            let file_bytes = usize::try_from(metadata.len())?;
            path_bytes_before = path_bytes_before
                .checked_add(metadata.len())
                .ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        directory.clone(),
                        "pending QueuePlan admission recovery path-byte count overflow",
                    )
                })?;
            if file_bytes == 0 || file_bytes > MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission recovery entry violates its hard byte limit",
                ));
            }
            #[cfg(unix)]
            let count_file_bytes = {
                use std::os::unix::fs::MetadataExt as _;
                seen_inodes.insert((metadata.dev(), metadata.ino()))
            };
            #[cfg(windows)]
            let count_file_bytes = {
                let volume = metadata.volume_serial_number().ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        path.clone(),
                        "pending QueuePlan admission recovery entry has no volume identity",
                    )
                })?;
                let index = metadata.file_index().ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        path.clone(),
                        "pending QueuePlan admission recovery entry has no file identity",
                    )
                })?;
                seen_file_ids.insert((volume, index))
            };
            #[cfg(all(not(unix), not(windows)))]
            let count_file_bytes = true;
            if count_file_bytes {
                total_bytes = total_bytes.checked_add(file_bytes).ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        directory.clone(),
                        "pending QueuePlan admission recovery byte count overflow",
                    )
                })?;
            }
            if !self
                .pending_control_sidecar_limits
                .merge_bytes_within_limit(total_bytes)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "pending QueuePlan admission recovery bytes exceed the aggregate hard limit",
                ));
            }
            let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission directory contains a non-UTF-8 recovery entry",
                ));
            };
            if let Some(hash_text) = file_name.strip_suffix(".norito.tmp") {
                Self::validate_pending_queue_plan_admission_hash_text(&path, hash_text)?;
                temp_paths.push((path, hash_text.to_owned()));
                if temp_paths.len() > 1 {
                    return Err(Self::invalid_pending_queue_plan_admission_error(
                        directory,
                        "pending QueuePlan admission directory contains multiple temporaries",
                    ));
                }
                continue;
            }
            let Some(hash_text) = file_name.strip_suffix(".norito") else {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission directory contains an unexpected recovery entry",
                ));
            };
            Self::validate_pending_queue_plan_admission_hash_text(&path, hash_text)?;
            stable_count = stable_count.saturating_add(1);
            if stable_count > self.pending_control_sidecar_limits.queue_plan_admissions {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "pending QueuePlan admission certificate count exceeds the hard limit",
                ));
            }
        }
        for (temp_path, hash_text) in temp_paths {
            let target_path = directory.join(format!("{hash_text}.norito"));
            let temp_metadata = secure_file_metadata::from_path(&temp_path)
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            let target_metadata = match secure_file_metadata::from_path(&target_path) {
                Ok(metadata) => Some(metadata),
                Err(err) if err.kind() == ErrorKind::NotFound => None,
                Err(err) => return Err(Error::IO(err, target_path.clone())),
            };
            if let Some(target_metadata) = target_metadata {
                if target_metadata.file_type().is_symlink()
                    || !target_metadata.file_type().is_file()
                {
                    return Err(Self::invalid_pending_queue_plan_admission_error(
                        target_path,
                        "pending QueuePlan admission recovery target is not a regular no-follow file",
                    ));
                }
                if Self::sidecar_metadata_same_object(&temp_metadata, &target_metadata) {
                    if !Self::sidecar_has_link_count(&temp_metadata, 2)
                        || !Self::sidecar_has_link_count(&target_metadata, 2)
                    {
                        return Err(Self::invalid_pending_queue_plan_admission_error(
                            temp_path,
                            "pending QueuePlan admission recovery pair has an unexpected hard-link count",
                        ));
                    }
                    std::fs::remove_file(&temp_path)
                        .map_err(|err| Error::IO(err, temp_path.clone()))?;
                    sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
                    let expected_hash = self
                        .read_pending_queue_plan_admission_path(&target_path, None)?
                        .ok_or_else(|| {
                            Self::invalid_pending_queue_plan_admission_error(
                                target_path.clone(),
                                "published QueuePlan admission target disappeared during recovery",
                            )
                        })?
                        .0;
                    if hex::encode(expected_hash.as_ref()) != hash_text {
                        return Err(Self::invalid_pending_queue_plan_admission_error(
                            target_path,
                            "published QueuePlan admission target bytes do not match their hash path",
                        ));
                    }
                    continue;
                }
                if !Self::sidecar_is_single_link(&temp_metadata)
                    || !Self::sidecar_is_single_link(&target_metadata)
                {
                    return Err(Self::invalid_pending_queue_plan_admission_error(
                        temp_path,
                        "conflicting QueuePlan admission recovery paths are not single-link files",
                    ));
                }
                let temp_bytes = self
                    .read_regular_sidecar_bytes(
                        &temp_path,
                        &directory,
                        MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES,
                    )?
                    .ok_or_else(|| {
                        Self::invalid_pending_queue_plan_admission_error(
                            temp_path.clone(),
                            "pending QueuePlan admission temporary disappeared during recovery",
                        )
                    })?;
                let expected_hash = self.validate_pending_queue_plan_admission_temp_bytes(
                    &temp_path,
                    &hash_text,
                    &temp_bytes,
                )?;
                let (_, target_bytes) = self
                    .read_pending_queue_plan_admission_path(&target_path, Some(expected_hash))?
                    .ok_or_else(|| {
                        Self::invalid_pending_queue_plan_admission_error(
                            target_path.clone(),
                            "published QueuePlan admission target disappeared during recovery",
                        )
                    })?;
                if target_bytes != temp_bytes {
                    return Err(Self::invalid_pending_queue_plan_admission_error(
                        temp_path,
                        "pending QueuePlan admission temporary conflicts with its published target",
                    ));
                }
                std::fs::remove_file(&temp_path)
                    .map_err(|err| Error::IO(err, temp_path.clone()))?;
                sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
                continue;
            }
            if stable_count == self.pending_control_sidecar_limits.queue_plan_admissions {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "unpublished pending QueuePlan admission temporary exceeds the certificate-count hard limit",
                ));
            }
            if !Self::sidecar_is_single_link(&temp_metadata) {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    temp_path,
                    "unpublished QueuePlan admission temporary is not a single-link file",
                ));
            }
            let temp_bytes = self
                .read_regular_sidecar_bytes(
                    &temp_path,
                    &directory,
                    MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES,
                )?
                .ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        temp_path.clone(),
                        "pending QueuePlan admission temporary disappeared during recovery",
                    )
                })?;
            let expected_hash = self.validate_pending_queue_plan_admission_temp_bytes(
                &temp_path,
                &hash_text,
                &temp_bytes,
            )?;
            std::fs::File::open(&temp_path)
                .and_then(|file| file.sync_all())
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            std::fs::hard_link(&temp_path, &target_path)
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            let target_metadata = secure_file_metadata::from_path(&target_path)
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            if !Self::sidecar_metadata_same_object(&temp_metadata, &target_metadata)
                || !Self::sidecar_has_link_count(&target_metadata, 2)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    target_path,
                    "published QueuePlan admission target does not bind its durable temporary",
                ));
            }
            std::fs::File::open(&target_path)
                .and_then(|file| file.sync_all())
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            std::fs::remove_file(&temp_path).map_err(|err| Error::IO(err, temp_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            let _ = self
                .read_pending_queue_plan_admission_path(&target_path, Some(expected_hash))?
                .ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        target_path,
                        "published QueuePlan admission target disappeared after recovery",
                    )
                })?;
        }
        let (_, path_bytes_after) = self.pending_queue_plan_admission_paths_unlocked()?;
        self.update_disk_usage_delta(path_bytes_before, u64::try_from(path_bytes_after)?);
        accounting_mutation.finish();
        Ok(())
    }
    fn read_pending_merge_entry_path(
        &self,
        path: &Path,
        expected_hash: Option<HashOf<MergeLedgerEntry>>,
    ) -> Result<Option<MergeLedgerEntry>> {
        let Some(bytes) = self.read_regular_sidecar_bytes(
            path,
            &self.pending_merge_entry_dir(),
            MAX_MERGE_LEDGER_ENTRY_BYTES,
        )?
        else {
            return Ok(None);
        };
        let entry = norito::decode_canonical::<MergeLedgerEntry>(&bytes).map_err(|err| {
            Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                format!("pending certified merge entry is not exact framed Norito: {err}"),
            )
        })?;
        if !entry.has_current_version() {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                format!(
                    "pending certified merge entry has unsupported merge ledger entry version {}",
                    entry.version
                ),
            ));
        }
        let actual_hash = crate::merge::merge_ledger_entry_hash(&entry);
        if expected_hash.is_some_and(|expected| expected != actual_hash)
            || self.pending_merge_entry_path(actual_hash) != path
        {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending certified merge entry path/hash mismatch",
            ));
        }
        Ok(Some(entry))
    }
    fn retain_pending_certified_merge_entries_unlocked(
        &self,
        mut retain: impl FnMut(&MergeLedgerEntry) -> bool,
    ) -> Result<usize> {
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let directory = self.pending_merge_entry_dir();
        let (paths, _) = self.pending_merge_entry_paths_unlocked()?;
        let mut removed = 0usize;
        let mut removed_bytes = 0u64;
        for path in paths {
            let Some(entry) = self.read_pending_merge_entry_path(&path, None)? else {
                continue;
            };
            if retain(&entry) {
                continue;
            }
            removed_bytes = removed_bytes
                .saturating_add(std::fs::metadata(&path).map_or(0, |metadata| metadata.len()));
            std::fs::remove_file(&path).map_err(|err| Error::IO(err, path))?;
            removed = removed.saturating_add(1);
        }
        if removed > 0 {
            sync_dir(&directory).map_err(|err| Error::IO(err, directory))?;
            self.sub_disk_usage_bytes(removed_bytes);
        }
        accounting_mutation.finish();
        Ok(removed)
    }
    fn prune_pending_certified_merge_entries_not_bound_to_unlocked(
        &self,
        carrier_height: u64,
        carrier_parent_hash: HashOf<BlockHeader>,
        view: u64,
    ) -> Result<usize> {
        self.retain_pending_certified_merge_entries_unlocked(|entry| {
            entry.merge_qc.carrier_height == carrier_height
                && entry.merge_qc.carrier_parent_hash == carrier_parent_hash
                && entry.merge_qc.view == view
        })
    }
    /// Remove pending certificates that can no longer be carried by the exact current round.
    ///
    /// This cleanup runs before pending-count and aggregate-byte admission, so missed rounds
    /// cannot permanently consume the bounded pending store.
    pub(crate) fn prune_pending_certified_merge_entries_not_bound_to(
        &self,
        carrier_height: u64,
        carrier_parent_hash: HashOf<BlockHeader>,
        view: u64,
    ) -> Result<usize> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        let _guard = self.sidecar_lock.lock();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.prune_pending_certified_merge_entries_not_bound_to_unlocked(
            carrier_height,
            carrier_parent_hash,
            view,
        )
    }
    /// At a locked carrier, retain only the exact full entry referenced by the
    /// immutable body. With no reference, remove every losing sidecar for that
    /// carrier height while leaving other heights untouched.
    pub(crate) fn retain_pending_certified_merge_entry_for_locked_carrier(
        &self,
        carrier_height: u64,
        reference: Option<&iroha_data_model::block::CertifiedMergeLedgerReference>,
    ) -> Result<usize> {
        self.durable_mutation_authorized()?;
        let _guard = self.sidecar_lock.lock();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.retain_pending_certified_merge_entries_unlocked(|entry| {
            entry.merge_qc.carrier_height != carrier_height
                || reference.is_some_and(|reference| reference.matches_entry(entry))
        })
    }
    /// Remove every pending merge sidecar whose carrier height is already
    /// finalized. No losing sidecar can become canonical after height rollover.
    pub(crate) fn prune_finalized_pending_certified_merge_entries(
        &self,
        finalized_height: u64,
    ) -> Result<usize> {
        self.durable_mutation_authorized()?;
        let _guard = self.sidecar_lock.lock();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.retain_pending_certified_merge_entries_unlocked(|entry| {
            entry.merge_qc.carrier_height > finalized_height
        })
    }
    /// Persist a fully certified entry in the hash-addressed pending sidecar
    /// store without appending it to the globally committed merge log.
    ///
    /// # Errors
    /// Returns an error for an oversized or conflicting sidecar, or when the
    /// atomic file publication cannot be completed. This method never prunes
    /// other carrier rounds; callers that own the active round must invoke the
    /// explicit exact-round pruning API first.
    pub(crate) fn persist_pending_certified_merge_entry(
        &self,
        entry: &MergeLedgerEntry,
    ) -> Result<HashOf<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        let bytes = crate::merge::canonical_merge_ledger_entry_bytes(entry);
        if bytes.len() > MAX_MERGE_LEDGER_ENTRY_BYTES {
            return Err(Self::invalid_pending_merge_entry_error(
                self.pending_merge_entry_dir(),
                "pending certified merge entry exceeds the hard byte limit",
            ));
        }
        let hash = crate::merge::merge_ledger_entry_hash(entry);
        let path = self.pending_merge_entry_path(hash);
        let directory = self.pending_merge_entry_dir();
        let _guard = self.sidecar_lock.lock();
        self.ensure_pending_merge_entry_dir_unlocked()?;
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.reconcile_pending_queue_plan_admission_temp_files_unlocked()?;
        let temp_path = path.with_extension("norito.tmp");
        let (paths, pending_bytes) = self.pending_merge_entry_paths_unlocked()?;
        if let Some(existing) = self.read_pending_merge_entry_path(&path, Some(hash))? {
            if existing == *entry {
                accounting_mutation.finish();
                return Ok(hash);
            }
            return Err(Self::invalid_pending_merge_entry_error(
                path,
                "hash-addressed pending merge sidecar conflicts with existing bytes",
            ));
        }
        if paths.len() == self.pending_control_sidecar_limits.certified_merge_entries {
            return Err(Self::invalid_pending_merge_entry_error(
                directory,
                "pending certified merge entry count exceeds the hard limit",
            ));
        }
        let (_, admission_bytes) = self.pending_queue_plan_admission_paths_unlocked()?;
        if pending_bytes.checked_add(bytes.len()).is_none_or(|total| {
            !self
                .pending_control_sidecar_limits
                .combined_bytes_within_limit(total, admission_bytes)
        }) {
            return Err(Self::invalid_pending_merge_entry_error(
                directory,
                "pending merge and QueuePlan admission bytes exceed their shared hard limit",
            ));
        }
        let mut temp = self.create_exclusive_pending_merge_temp(&temp_path)?;
        temp.write_all(&bytes)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        temp.flush()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        temp.sync_all()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        let opened_after_write = secure_file_metadata::from_file(&temp)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        let path_after_write = secure_file_metadata::from_path(&temp_path)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        if !opened_after_write.is_file()
            || path_after_write.file_type().is_symlink()
            || !path_after_write.file_type().is_file()
            || !Self::sidecar_is_single_link(&opened_after_write)
            || !Self::sidecar_is_single_link(&path_after_write)
            || !Self::sidecar_metadata_same_object(&opened_after_write, &path_after_write)
            || opened_after_write.len() != u64::try_from(bytes.len())?
        {
            return Err(Self::invalid_pending_merge_entry_error(
                temp_path,
                "pending merge temporary changed while writing",
            ));
        }
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        if let Err(error) = std::fs::hard_link(&temp_path, &path) {
            let remove_result = std::fs::remove_file(&temp_path);
            let sync_result = sync_dir(&directory);
            if let Err(remove_error) = remove_result {
                return Err(Error::IO(remove_error, temp_path));
            }
            if let Err(sync_error) = sync_result {
                return Err(Error::IO(sync_error, directory));
            }
            return Err(Error::IO(error, path));
        }
        let target_metadata = secure_file_metadata::from_path(&path)
            .map_err(|error| Error::IO(error, path.clone()))?;
        if target_metadata.file_type().is_symlink()
            || !target_metadata.file_type().is_file()
            || !Self::sidecar_metadata_same_object(&opened_after_write, &target_metadata)
            || !Self::sidecar_has_link_count(&target_metadata, 2)
        {
            return Err(Self::invalid_pending_merge_entry_error(
                path,
                "published pending merge target does not bind its durable temporary",
            ));
        }
        let target = std::fs::File::open(&path).map_err(|error| Error::IO(error, path.clone()))?;
        let opened_target = secure_file_metadata::from_file(&target)
            .map_err(|error| Error::IO(error, path.clone()))?;
        if !Self::sidecar_metadata_same_object(&target_metadata, &opened_target)
            || !Self::sidecar_has_link_count(&opened_target, 2)
        {
            return Err(Self::invalid_pending_merge_entry_error(
                path,
                "published pending merge target changed while opening",
            ));
        }
        target
            .sync_all()
            .map_err(|error| Error::IO(error, path.clone()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        std::fs::remove_file(&temp_path).map_err(|error| Error::IO(error, temp_path.clone()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        let persisted = self
            .read_pending_merge_entry_path(&path, Some(hash))?
            .ok_or_else(|| {
                Self::invalid_pending_merge_entry_error(
                    path.clone(),
                    "published pending merge entry disappeared",
                )
            })?;
        if persisted != *entry {
            return Err(Self::invalid_pending_merge_entry_error(
                path,
                "published pending merge entry differs from its durable input",
            ));
        }
        self.add_disk_usage_bytes(u64::try_from(bytes.len())?);
        accounting_mutation.finish();
        Ok(hash)
    }
    /// Persist exact canonical QueuePlan admission certificate bytes before
    /// they become eligible for a global carrier.
    ///
    /// Kura deliberately treats the versioned certificate as opaque bytes: the
    /// admission layer owns Norito decoding and semantic validation, while this
    /// store preserves those exact bytes under their content hash. Empty,
    /// oversized, aliased, or non-canonical filesystem identities fail closed.
    ///
    /// # Errors
    /// Returns an error when the certificate or pending-control store exceeds
    /// its bounds, or when durable no-clobber publication cannot complete.
    pub fn persist_pending_queue_plan_admission_certificate(
        &self,
        canonical_certificate_bytes: &[u8],
    ) -> Result<Hash> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        if canonical_certificate_bytes.is_empty()
            || canonical_certificate_bytes.len()
                > MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                self.pending_queue_plan_admission_dir(),
                "pending QueuePlan admission certificate violates its hard byte limit",
            ));
        }
        let hash = Hash::new(canonical_certificate_bytes);
        let path = self.pending_queue_plan_admission_path(hash);
        let temp_path = path.with_extension("norito.tmp");
        let directory = self.pending_queue_plan_admission_dir();
        let _guard = self.sidecar_lock.lock();
        self.ensure_pending_queue_plan_admission_dir_unlocked()?;
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.reconcile_pending_queue_plan_admission_temp_files_unlocked()?;
        if let Some((_, existing)) =
            self.read_pending_queue_plan_admission_path(&path, Some(hash))?
        {
            if existing == canonical_certificate_bytes {
                accounting_mutation.finish();
                return Ok(hash);
            }
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path,
                "hash-addressed QueuePlan admission sidecar conflicts with existing bytes",
            ));
        }
        let (paths, admission_bytes) = self.pending_queue_plan_admission_paths_unlocked()?;
        if paths.len() == self.pending_control_sidecar_limits.queue_plan_admissions {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                directory,
                "pending QueuePlan admission certificate count exceeds the hard limit",
            ));
        }
        let (_, merge_bytes) = self.pending_merge_entry_paths_unlocked()?;
        if admission_bytes
            .checked_add(canonical_certificate_bytes.len())
            .is_none_or(|total| {
                !self
                    .pending_control_sidecar_limits
                    .combined_bytes_within_limit(merge_bytes, total)
            })
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                directory,
                "pending merge and QueuePlan admission bytes exceed their shared hard limit",
            ));
        }
        let mut temp = self.create_exclusive_pending_queue_plan_admission_temp(&temp_path)?;
        temp.write_all(canonical_certificate_bytes)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        temp.flush()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        temp.sync_all()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        let opened_after_write = secure_file_metadata::from_file(&temp)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        let path_after_write = secure_file_metadata::from_path(&temp_path)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        if !opened_after_write.is_file()
            || path_after_write.file_type().is_symlink()
            || !path_after_write.file_type().is_file()
            || !Self::sidecar_is_single_link(&opened_after_write)
            || !Self::sidecar_is_single_link(&path_after_write)
            || !Self::sidecar_metadata_same_object(&opened_after_write, &path_after_write)
            || opened_after_write.len() != u64::try_from(canonical_certificate_bytes.len())?
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                temp_path,
                "pending QueuePlan admission temporary changed while writing",
            ));
        }
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        if let Err(error) = std::fs::hard_link(&temp_path, &path) {
            let remove_result = std::fs::remove_file(&temp_path);
            let sync_result = sync_dir(&directory);
            if let Err(remove_error) = remove_result {
                return Err(Error::IO(remove_error, temp_path));
            }
            if let Err(sync_error) = sync_result {
                return Err(Error::IO(sync_error, directory));
            }
            return Err(Error::IO(error, path));
        }
        let target_metadata = secure_file_metadata::from_path(&path)
            .map_err(|error| Error::IO(error, path.clone()))?;
        if target_metadata.file_type().is_symlink()
            || !target_metadata.file_type().is_file()
            || !Self::sidecar_metadata_same_object(&opened_after_write, &target_metadata)
            || !Self::sidecar_has_link_count(&target_metadata, 2)
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path,
                "published QueuePlan admission target does not bind its durable temporary",
            ));
        }
        let target = std::fs::File::open(&path).map_err(|error| Error::IO(error, path.clone()))?;
        let opened_target = secure_file_metadata::from_file(&target)
            .map_err(|error| Error::IO(error, path.clone()))?;
        if !Self::sidecar_metadata_same_object(&target_metadata, &opened_target)
            || !Self::sidecar_has_link_count(&opened_target, 2)
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path,
                "published QueuePlan admission target changed while opening",
            ));
        }
        target
            .sync_all()
            .map_err(|error| Error::IO(error, path.clone()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        std::fs::remove_file(&temp_path).map_err(|error| Error::IO(error, temp_path.clone()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        let (_, persisted) = self
            .read_pending_queue_plan_admission_path(&path, Some(hash))?
            .ok_or_else(|| {
                Self::invalid_pending_queue_plan_admission_error(
                    path.clone(),
                    "published QueuePlan admission certificate disappeared",
                )
            })?;
        if persisted != canonical_certificate_bytes {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path,
                "published QueuePlan admission certificate differs from its durable input",
            ));
        }
        self.add_disk_usage_bytes(u64::try_from(canonical_certificate_bytes.len())?);
        accounting_mutation.finish();
        Ok(hash)
    }
    /// Return every pending QueuePlan admission certificate in byte-hash order.
    #[cfg(test)]
    pub(crate) fn pending_queue_plan_admission_certificates(&self) -> Result<Vec<(Hash, Vec<u8>)>> {
        self.pending_queue_plan_admission_certificates_bounded(
            self.pending_control_sidecar_limits.queue_plan_admissions,
        )
    }
    /// Return at most `limit` pending QueuePlan admission certificates in
    /// deterministic byte-hash order.
    pub(crate) fn pending_queue_plan_admission_certificates_bounded(
        &self,
        limit: usize,
    ) -> Result<Vec<(Hash, Vec<u8>)>> {
        if limit == 0 {
            return Ok(Vec::new());
        }
        self.ensure_prune_recovery_not_required()?;
        let certificates = {
            let _guard = self.sidecar_lock.lock();
            self.ensure_prune_recovery_not_required()?;
            let paths = self.pending_queue_plan_admission_inventory_paths_unlocked()?;
            let bounded = limit.min(self.pending_control_sidecar_limits.queue_plan_admissions);
            let mut certificates = Vec::with_capacity(paths.len().min(bounded));
            for path in paths.into_iter().take(bounded) {
                let Some(certificate) = self.read_pending_queue_plan_admission_path(&path, None)?
                else {
                    continue;
                };
                certificates.push(certificate);
            }
            certificates
        };
        self.ensure_prune_recovery_not_required()?;
        Ok(certificates)
    }
    /// Remove pending QueuePlan admission certificates rejected by `retain`.
    ///
    /// This is the byte-oriented cleanup hook used by the admission layer for
    /// stale round/incarnation evidence; Kura does not interpret the payload.
    #[cfg(test)]
    pub(crate) fn retain_pending_queue_plan_admission_certificates(
        &self,
        mut retain: impl FnMut(Hash, &[u8]) -> bool,
    ) -> Result<usize> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        let _guard = self.sidecar_lock.lock();
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        self.reconcile_pending_queue_plan_admission_temp_files_unlocked()?;
        let directory = self.pending_queue_plan_admission_dir();
        let (paths, _) = self.pending_queue_plan_admission_paths_unlocked()?;
        let mut removed = 0usize;
        let mut removed_bytes = 0u64;
        for path in paths {
            let Some((hash, bytes)) = self.read_pending_queue_plan_admission_path(&path, None)?
            else {
                continue;
            };
            if retain(hash, &bytes) {
                continue;
            }
            removed_bytes = removed_bytes.saturating_add(u64::try_from(bytes.len())?);
            std::fs::remove_file(&path).map_err(|error| Error::IO(error, path))?;
            removed = removed.saturating_add(1);
        }
        if removed > 0 {
            sync_dir(&directory).map_err(|error| Error::IO(error, directory))?;
            self.sub_disk_usage_bytes(removed_bytes);
        }
        accounting_mutation.finish();
        Ok(removed)
    }
    /// Remove one pending QueuePlan admission certificate after canonical
    /// carrier commitment or explicit stale-certificate rejection.
    pub(crate) fn remove_pending_queue_plan_admission_certificate(&self, hash: Hash) -> Result<()> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        let path = self.pending_queue_plan_admission_path(hash);
        let directory = self.pending_queue_plan_admission_dir();
        let _guard = self.sidecar_lock.lock();
        let Some((_, bytes)) = self.read_pending_queue_plan_admission_path(&path, Some(hash))?
        else {
            return Ok(());
        };
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        std::fs::remove_file(&path).map_err(|error| Error::IO(error, path))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory))?;
        self.sub_disk_usage_bytes(u64::try_from(bytes.len())?);
        accounting_mutation.finish();
        Ok(())
    }
    /// Resolve an exact merge entry from the pending sidecar store or the
    /// globally committed merge log.
    ///
    /// # Errors
    /// Returns an error if a matching pending sidecar is corrupt or committed
    /// merge-log recovery fails.
    pub(crate) fn merge_entry_by_hash(
        &self,
        hash: HashOf<MergeLedgerEntry>,
    ) -> Result<Option<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let path = self.pending_merge_entry_path(hash);
        let pending = {
            let _guard = self.sidecar_lock.lock();
            self.ensure_prune_recovery_not_required()?;
            self.read_pending_merge_entry_path(&path, Some(hash))?
        };
        self.ensure_prune_recovery_not_required()?;
        if pending.is_some() {
            return Ok(pending);
        }
        let mut merge_log = self.merge_log.lock();
        self.ensure_prune_recovery_not_required()?;
        let entry = merge_log.entry_by_hash(hash)?;
        self.ensure_prune_recovery_not_required()?;
        Ok(entry)
    }
    /// Return canonical, uncommitted certified merge sidecars in deterministic order.
    ///
    /// The pending store is bounded at admission, and entries already present in the committed
    /// merge log are excluded.
    pub(crate) fn pending_certified_merge_entries(
        &self,
    ) -> Result<Vec<(HashOf<MergeLedgerEntry>, MergeLedgerEntry)>> {
        self.pending_certified_merge_entries_bounded(
            self.pending_control_sidecar_limits.certified_merge_entries,
        )
    }
    /// Return at most `limit` deterministic pending merge sidecars.
    ///
    /// Directory shape and aggregate metadata remain fail-closed under the
    /// protocol hard limits. Files are decoded one at a time until `limit`
    /// uncommitted entries have been selected, and only those selected entries
    /// are retained. This prevents committed sidecars that sort first from
    /// under-filling the bounded result.
    pub(crate) fn pending_certified_merge_entries_bounded(
        &self,
        limit: usize,
    ) -> Result<Vec<(HashOf<MergeLedgerEntry>, MergeLedgerEntry)>> {
        if limit == 0 {
            return Ok(Vec::new());
        }
        let bounded = limit.min(self.pending_control_sidecar_limits.certified_merge_entries);
        let mut entries = Vec::with_capacity(bounded);
        let _ = self.visit_pending_certified_merge_entries(
            self.pending_control_sidecar_limits.certified_merge_entries,
            |hash, entry| {
                entries.push((hash, entry.clone()));
                entries.len() == bounded
            },
        )?;
        entries.sort_by_key(|(hash, entry)| (entry.epoch_id, *hash));
        self.ensure_prune_recovery_not_required()?;
        Ok(entries)
    }
    /// Return deterministic hashes for matching uncommitted pending merge evidence.
    ///
    /// At most `evidence_scan_limit` sidecars are decoded, one at a time. The
    /// predicate runs without a Kura lock, and selected entries are represented
    /// only by their hashes so callers can resolve, validate, and discard each
    /// large entry independently. [`PendingCertifiedMergeEvidenceScan::LimitExceeded`]
    /// is returned when the stable pending inventory exceeds the scan limit; no
    /// entry bytes are decoded in that case.
    pub(crate) fn pending_certified_merge_entry_hashes_matching_bounded(
        &self,
        evidence_scan_limit: usize,
        mut selected: impl FnMut(&MergeLedgerEntry) -> bool,
    ) -> Result<PendingCertifiedMergeEvidenceScan> {
        let mut matches = Vec::new();
        let outcome =
            self.visit_pending_certified_merge_entries(evidence_scan_limit, |hash, entry| {
                if selected(entry) {
                    matches.push((entry.epoch_id, hash));
                }
                false
            })?;
        if outcome == PendingCertifiedMergeVisitOutcome::ScanLimitExceeded {
            return Ok(PendingCertifiedMergeEvidenceScan::LimitExceeded);
        }
        matches.sort_unstable_by_key(|(epoch_id, hash)| (*epoch_id, *hash));
        Ok(PendingCertifiedMergeEvidenceScan::Complete(
            matches.into_iter().map(|(_, hash)| hash).collect(),
        ))
    }
    fn visit_pending_certified_merge_entries(
        &self,
        evidence_scan_limit: usize,
        mut visitor: impl FnMut(HashOf<MergeLedgerEntry>, &MergeLedgerEntry) -> bool,
    ) -> Result<PendingCertifiedMergeVisitOutcome> {
        self.ensure_prune_recovery_not_required()?;
        let paths = {
            let _guard = self.sidecar_lock.lock();
            self.ensure_prune_recovery_not_required()?;
            let (paths, _) = self.pending_merge_entry_paths_unlocked()?;
            paths
        };
        let evidence_scan_limit =
            evidence_scan_limit.min(self.pending_control_sidecar_limits.certified_merge_entries);
        if paths.len() > evidence_scan_limit {
            return Ok(PendingCertifiedMergeVisitOutcome::ScanLimitExceeded);
        }
        for path in paths {
            let entry = {
                let _guard = self.sidecar_lock.lock();
                self.ensure_prune_recovery_not_required()?;
                self.read_pending_merge_entry_path(&path, None)?
            };
            let Some(entry) = entry else {
                continue;
            };
            let hash = entry.canonical_hash();
            self.ensure_prune_recovery_not_required()?;
            let committed = {
                let mut merge_log = self.merge_log.lock();
                self.ensure_prune_recovery_not_required()?;
                merge_log.contains_hash(hash)?
            };
            if committed {
                continue;
            }
            if visitor(hash, &entry) {
                self.ensure_prune_recovery_not_required()?;
                return Ok(PendingCertifiedMergeVisitOutcome::VisitorStopped);
            }
        }
        self.ensure_prune_recovery_not_required()?;
        Ok(PendingCertifiedMergeVisitOutcome::Complete)
    }
    /// Return whether an uncommitted certified merge sidecar still carries
    /// work for one exact active lane incarnation.
    ///
    /// The underlying scan is bounded by the pending-entry count and byte
    /// limits, decodes one entry at a time, and stops at the first blocker.
    /// Malformed autonomous routing bytes, misaligned Native receipts, or a
    /// matching route without one unique historical active-lane binding
    /// conservatively count as work, so drain certification never treats
    /// unverifiable evidence as empty. A certificate-only entry is the closure
    /// carrier itself and owns no lane work; counting it here would make its own
    /// admission impossible.
    pub(crate) fn pending_certified_merge_work_for_lane(
        &self,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
        lane_incarnation: Hash,
    ) -> Result<bool> {
        let outcome = self.visit_pending_certified_merge_entries(
            self.pending_control_sidecar_limits.certified_merge_entries,
            |_, entry| {
                entry.lane_snapshots.iter().any(|snapshot| {
                    snapshot.lane_id == lane_id
                        && snapshot.dataspace_id == dataspace_id
                        && snapshot.lane_incarnation == lane_incarnation
                }) || entry.execution_batch.as_ref().is_some_and(|batch| {
                    batch.lanes.iter().any(|execution| {
                        let descriptor = &execution.proposal.descriptor;
                        let origin = &execution.origin_proposal.descriptor;
                        let entry_count = execution.entrypoints.len();
                        (descriptor.lane_id == lane_id
                            && descriptor.dataspace_id == dataspace_id
                            && descriptor.lane_incarnation == lane_incarnation)
                            || (origin.lane_id == lane_id
                                && origin.dataspace_id == dataspace_id
                                && origin.lane_incarnation == lane_incarnation)
                            || descriptor.lane_id != origin.lane_id
                            || descriptor.dataspace_id != origin.dataspace_id
                            || descriptor.lane_incarnation != origin.lane_incarnation
                            || execution.entrypoint_hashes.len() != entry_count
                            || execution.reservation_keys.len() != entry_count
                            || execution.routing_plans.len() != entry_count
                            || execution.native_amx_receipts.len() != entry_count
                            || execution.result_hashes.len() != entry_count
                            || execution.results.len() != entry_count
                            || execution
                                .routing_plans
                                .iter()
                                .zip(&execution.native_amx_receipts)
                                .any(|(encoded, receipt)| {
                                    let Ok(plan) = norito::decode_canonical::<
                                        crate::queue::RoutingPlan,
                                    >(encoded)
                                    else {
                                        return true;
                                    };
                                    let coordinator = plan.coordinator_leg().route;
                                    if coordinator.lane_id != origin.lane_id
                                        || coordinator.dataspace_id != origin.dataspace_id
                                    {
                                        return true;
                                    }
                                    let route_carries_incarnation =
                                        plan.legs().into_iter().any(|leg| {
                                            if leg.route.lane_id != lane_id
                                                || leg.route.dataspace_id != dataspace_id
                                            {
                                                return false;
                                            }
                                            let mut bindings =
                                                entry.active_lanes.iter().filter(|binding| {
                                                    binding.lane_id == leg.route.lane_id
                                                        && binding.dataspace_id
                                                            == leg.route.dataspace_id
                                                });
                                            let Some(binding) = bindings.next() else {
                                                return true;
                                            };
                                            if bindings.next().is_some() {
                                                return true;
                                            }
                                            binding.incarnation == lane_incarnation
                                        });
                                    let participant_carries_incarnation = match (&plan, receipt) {
                                        (crate::queue::RoutingPlan::Single(_), None) => false,
                                        (
                                            crate::queue::RoutingPlan::NativeAmx(native_plan),
                                            Some(receipt),
                                        ) => {
                                            if receipt.plan_digest != plan.digest()
                                                || receipt.lane_id != origin.lane_id
                                                || receipt.dataspace_id != origin.dataspace_id
                                                || receipt.lane_incarnation
                                                    != origin.lane_incarnation
                                                || receipt.authority_context_height
                                                    != origin.proposal_height
                                                || receipt.lane_block_height
                                                    != origin.lane_block_height
                                                || receipt.lane_block_view
                                                    != origin.lane_block_view
                                                || receipt.coordinator_proposal_hash
                                                    != execution.origin_proposal.proposal_hash
                                                || receipt.legs.len()
                                                    != native_plan.participants.len()
                                                || receipt.legs.iter().zip(&native_plan.participants).any(
                                                    |(leg, planned)| {
                                                        leg.lane_id
                                                            != planned.route.lane_id
                                                            || leg.dataspace_id
                                                                != planned.route.dataspace_id
                                                    },
                                                )
                                            {
                                                true
                                            } else {
                                                crate::native_amx::native_amx_receipt_requires_separate_participant_application_for(
                                                    receipt,
                                                    lane_id,
                                                    dataspace_id,
                                                    lane_incarnation,
                                                )
                                                .unwrap_or(true)
                                            }
                                        }
                                        _ => true,
                                    };
                                    route_carries_incarnation
                                        || participant_carries_incarnation
                                })
                    })
                })
            },
        )?;
        Ok(outcome != PendingCertifiedMergeVisitOutcome::Complete)
    }
    /// Select the next pending certified entry deterministically by
    /// `(epoch_id, entry_hash)`, excluding entries already in the committed log.
    ///
    /// # Errors
    /// Returns an error when the pending directory is unreadable, exceeds its
    /// hard entry-count/byte caps, or contains a malformed sidecar.
    #[cfg(test)]
    pub(crate) fn select_pending_certified_merge_entry(
        &self,
    ) -> Result<Option<(HashOf<MergeLedgerEntry>, MergeLedgerEntry)>> {
        Ok(self.pending_certified_merge_entries()?.into_iter().next())
    }
    /// Select the first canonical pending entry accepted by `eligible`.
    ///
    /// The predicate runs without the sidecar lock, allowing callers to perform
    /// full state/QC validation. Rejected stale entries remain durable and do
    /// not poison selection of a later eligible candidate.
    pub(crate) fn select_pending_certified_merge_entry_matching(
        &self,
        mut eligible: impl FnMut(HashOf<MergeLedgerEntry>, &MergeLedgerEntry) -> bool,
    ) -> Result<Option<(HashOf<MergeLedgerEntry>, MergeLedgerEntry)>> {
        Ok(self
            .pending_certified_merge_entries()?
            .into_iter()
            .find(|(hash, entry)| eligible(*hash, entry)))
    }
    /// Remove a pending sidecar after the same entry is globally committed.
    ///
    /// # Errors
    /// Returns an error when the sidecar cannot be removed or its parent cannot
    /// be synchronized.
    pub(crate) fn remove_pending_certified_merge_entry(
        &self,
        hash: HashOf<MergeLedgerEntry>,
    ) -> Result<()> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        self.remove_pending_certified_merge_entry_after_authorization(hash)
    }
    fn remove_pending_certified_merge_entry_after_authorization(
        &self,
        hash: HashOf<MergeLedgerEntry>,
    ) -> Result<()> {
        #[cfg(test)]
        if self
            .fail_next_pending_merge_cleanup
            .swap(false, Ordering::Relaxed)
        {
            return Err(Error::IO(
                std::io::Error::other("injected committed-pending cleanup failure"),
                self.pending_merge_entry_path(hash),
            ));
        }
        let path = self.pending_merge_entry_path(hash);
        let directory = self.pending_merge_entry_dir();
        let _guard = self.sidecar_lock.lock();
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let bytes = std::fs::metadata(&path).map_or(0, |metadata| metadata.len());
        let result = match std::fs::remove_file(&path) {
            Ok(()) => {
                sync_dir(&directory).map_err(|err| Error::IO(err, directory))?;
                self.sub_disk_usage_bytes(bytes);
                Ok(())
            }
            Err(err) if err.kind() == ErrorKind::NotFound => Ok(()),
            Err(err) => Err(Error::IO(err, path)),
        };
        if result.is_ok() {
            accounting_mutation.finish();
        }
        result
    }
    fn preflight_committed_merge_entry_for_block(
        &self,
        block: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) -> Result<()> {
        let record = Self::carrier_record_for_block_entry(block, entry)?;
        self.merge_log.lock().preflight_append(entry)?;
        let _guard = self.merge_carrier_lock.lock();
        self.preflight_merge_carrier_record_unlocked(record)?;
        Ok(())
    }
    fn associated_merge_entry_for_block(
        &self,
        block: &SignedBlock,
    ) -> Result<Option<MergeLedgerEntry>> {
        let Some(reference) = Self::block_merge_reference(block) else {
            return Ok(None);
        };
        let Some(entry) = self.merge_log.lock().entry_by_hash(reference.entry_hash)? else {
            return Ok(None);
        };
        if !reference.matches_entry(&entry) {
            return Err(Error::MergeReferenceMismatch(
                "canonical block compact reference differs from its committed merge entry"
                    .to_owned(),
            ));
        }
        let record = Self::carrier_record_for_block_entry(block, &entry)?;
        let _guard = self.merge_carrier_lock.lock();
        if self.preflight_merge_carrier_record_unlocked(record)? {
            return Ok(None);
        }
        Ok(Some(entry))
    }
    fn remove_committed_pending_merge_entry_best_effort(&self, hash: HashOf<MergeLedgerEntry>) {
        if let Err(error) = self.remove_pending_certified_merge_entry(hash) {
            warn!(
                ?error,
                %hash,
                "committed merge entry remains in the redundant pending sidecar store"
            );
        }
    }
    fn append_committed_merge_entry_for_block_if_missing(
        &self,
        block: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) -> Result<(usize, bool)> {
        let record = Self::carrier_record_for_block_entry(block, entry)?;
        let entry_hash = record.entry_hash;
        let _carrier_guard = self.merge_carrier_lock.lock();
        let mut merge_log = self.merge_log.lock();
        let merge_log_len_before = merge_log.total_entries;
        let existing = merge_log.entry_by_hash(entry_hash)?;
        let mut appended = false;
        let mut merge_accounting_mutation = None;
        if let Some(existing) = existing.as_ref() {
            if existing != entry {
                return Err(Error::MergeCarrierConflict(
                    "committed merge log contains different bytes for the same entry hash"
                        .to_owned(),
                ));
            }
        } else {
            merge_accounting_mutation = Some(self.begin_total_disk_usage_mutation());
            merge_log.append(entry)?;
            appended = true;
        }
        let carrier_written = match self.write_merge_carrier_record_unlocked(record) {
            Ok(written) => written,
            Err(err) => {
                if appended
                    && let Err(rollback_err) = merge_log.truncate_to_len(merge_log_len_before)
                {
                    let combined = Error::MergeCarrierConflict(format!(
                        "merge carrier publication failed ({err}) and merge-log rollback failed ({rollback_err})"
                    ));
                    drop(merge_log);
                    drop(_carrier_guard);
                    return Err(self.committed_recovery_failure(
                        "merge carrier publication rollback",
                        &combined,
                    ));
                }
                return Err(err);
            }
        };
        drop(merge_log);
        if appended && !self.store_root.as_os_str().is_empty() {
            let bytes = Self::merge_entry_bytes(entry)?;
            self.add_disk_usage_bytes(bytes);
        }
        if let Some(accounting_mutation) = merge_accounting_mutation {
            accounting_mutation.finish();
        }
        Ok((merge_log_len_before, carrier_written))
    }
    /// Snapshot merge-ledger entries retained in the in-memory cache.
    #[cfg(test)]
    pub(crate) fn merge_ledger_snapshot(&self) -> Vec<MergeLedgerEntry> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return Vec::new();
        }
        let merge_log = self.merge_log.lock();
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return Vec::new();
        }
        let entries = merge_log.snapshot();
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return Vec::new();
        }
        entries
    }
    /// Snapshot at most `limit` newest cached merge-ledger entries, newest first.
    ///
    /// Diagnostic callers can use this accessor without cloning an
    /// operator-configured cache of arbitrary size.
    ///
    /// # Errors
    /// Returns an explicit unavailable error when emergency Fast startup
    /// deferred merge history, or when canonical storage is fail-stop poisoned.
    pub(crate) fn merge_ledger_latest_snapshot(
        &self,
        limit: usize,
    ) -> Result<Vec<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let merge_log = self.merge_log.lock();
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let entries = merge_log.latest_snapshot(limit)?;
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        Ok(entries)
    }
    /// Read every durable merge-ledger entry in chronological order.
    ///
    /// # Errors
    /// Returns an error when an indexed frame cannot be decoded or the file no
    /// longer has the exact length validated by startup/append recovery.
    pub(crate) fn merge_ledger_all_entries(&self) -> Result<Vec<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let mut merge_log = self.merge_log.lock();
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let entries = merge_log.all_entries()?;
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        Ok(entries)
    }
    /// Return the latest committed lane-local execution height for every active
    /// `(lane, dataspace, incarnation)` identity.
    ///
    /// The map is maintained while the merge log is streamed at startup and on
    /// each append/truncation, so consensus validation does not rescan or decode
    /// the complete durable history for every candidate.
    #[cfg(test)]
    pub(crate) fn latest_merge_execution_heights(
        &self,
    ) -> Result<BTreeMap<(LaneId, DataSpaceId, Hash), u64>> {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let merge_log = self.merge_log.lock();
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        merge_log.ensure_history_available()?;
        let heights = merge_log.latest_execution_heights();
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        Ok(heights)
    }
    #[cfg(test)]
    pub(crate) fn fail_next_merge_append_for_test(&self) {
        self.merge_log.lock().fail_next_append = true;
    }
    /// Reset merge-history read counters used by transaction-query complexity tests.
    #[cfg(test)]
    pub(crate) fn reset_merge_query_read_counters_for_test(&self) {
        let mut merge_log = self.merge_log.lock();
        merge_log.full_history_scans = 0;
        merge_log.indexed_lookups = 0;
        merge_log.complete_execution_scans = 0;
    }
    /// Return `(full_log_scans, complete_execution_scans, indexed_lookups)` for tests.
    #[cfg(test)]
    pub(crate) fn merge_query_read_counters_for_test(&self) -> (usize, usize, usize) {
        let merge_log = self.merge_log.lock();
        (
            merge_log.full_history_scans,
            merge_log.complete_execution_scans,
            merge_log.indexed_lookups,
        )
    }
    /// Corrupt a sidecar payload while retaining its frame index for fail-closed tests.
    #[cfg(test)]
    pub(crate) fn remove_merge_entry_payload_for_test(&self, hash: HashOf<MergeLedgerEntry>) {
        let mut merge_log = self.merge_log.lock();
        merge_log.in_memory_entries.remove(&hash);
        let Some(frame) = merge_log.frames_by_hash.get(&hash).copied() else {
            return;
        };
        let Some(path) = merge_log.file.as_ref().map(|file| file.path.clone()) else {
            return;
        };
        let payload_len =
            usize::try_from(frame.payload_len).expect("merge frame payload length fits usize");
        let mut file = FileWrap::open_with(path, |options| {
            options.write(true);
        })
        .expect("open indexed merge sidecar without append mode for test corruption");
        file.try_io(|inner| {
            inner.seek(SeekFrom::Start(frame.frame_offset.saturating_add(4)))?;
            inner.write_all(&vec![0; payload_len])?;
            inner.sync_data()?;
            Ok(())
        })
        .expect("corrupt indexed merge sidecar payload for test");
    }
    #[cfg(test)]
    fn fail_next_merge_append_after_for_test(&self, point: MergeLedgerAppendFailurePoint) {
        self.merge_log.lock().fail_next_append_after = Some(point);
    }
    pub(crate) fn truncate_merge_log_to_len(&self, keep: usize) -> Result<()> {
        self.durable_mutation_authorized()?;
        self.truncate_merge_log_to_len_after_authorization(keep)
    }
    fn truncate_merge_log_to_len_after_authorization(&self, keep: usize) -> Result<()> {
        let before = self.merge_log_tracked_bytes()?;
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        self.merge_log.lock().truncate_to_len(keep)?;
        let after = self.merge_log_tracked_bytes()?;
        self.update_disk_usage_delta(before, after);
        accounting_mutation.finish();
        Ok(())
    }
    /// Start a thread that receives and stores new blocks
    /// Start the background block writer after all provisional startup authority is finalized.
    ///
    /// # Errors
    /// Returns an error when the immutable local peer identity has not been
    /// bound, while signed snapshot authentication is pending, or canonical
    /// storage is fail-stop poisoned.
    pub fn start(kura: Arc<Self>, shutdown_signal: ShutdownSignal) -> Result<Child> {
        if kura.local_peer_id.get().is_none() {
            return Err(Error::KuraReplicaLocalPeerUnbound);
        }
        kura.ensure_snapshot_bootstrap_authenticated()?;
        kura.ensure_canonical_storage_not_poisoned()?;
        let shutdown_notify_tx = kura.block_notify_tx.clone();
        let shutdown_signal_clone = shutdown_signal.clone();
        tokio::spawn(async move {
            shutdown_signal_clone.receive().await;
            Self::notify_block_writer_sender(
                &shutdown_notify_tx,
                BlockNotify::Shutdown,
                "shutdown",
            );
        });
        Ok(Child::new(
            tokio::task::spawn(spawn_os_thread_as_future(
                std::thread::Builder::new().name("kura".to_owned()),
                move || {
                    kura.receive_blocks_loop(&shutdown_signal);
                },
            )),
            OnShutdown::Wait(Duration::from_secs(5)),
        ))
    }
    /// Initialize [`Kura`] after its construction to be able to work with it.
    ///
    /// # Errors
    /// Fails if:
    /// - file storage is unavailable
    /// - data in file storage is invalid or corrupted
    #[iroha_logger::log(skip_all, name = "kura_init")]
    fn init(
        block_store: &mut BlockStore,
        mode: InitMode,
        v2_finality_floor: Option<u64>,
        provisional_hash_only_prefix: Option<usize>,
    ) -> Result<ChainValidation> {
        let block_index_count: usize = block_store
            .read_durable_index_count()?
            .try_into()
            .expect("INTERNAL BUG: block index count exceeds usize::MAX");
        let chain_validation = if let Some(audited_height) = provisional_hash_only_prefix {
            Kura::init_provisional_snapshot_bootstrap(
                block_store,
                block_index_count,
                audited_height,
                v2_finality_floor,
            )?
        } else {
            match mode {
                InitMode::Fast => {
                    warn!(
                        "Kura fast init trusts the durable local journal and defers full block validation; restart in strict mode after emergency recovery"
                    );
                    Kura::init_fast_mode(block_store, block_index_count, v2_finality_floor)
                }
                InitMode::Strict => {
                    Kura::init_canonical_chain(block_store, block_index_count, v2_finality_floor)
                }
            }?
        };
        if chain_validation.truncated {
            warn!(
                validated_blocks = chain_validation.hashes.len(),
                "Kura detected corrupted storage during init and pruned to the last valid block"
            );
        }
        if chain_validation.hash_mismatch {
            warn!("Kura rewrote hashes file after detecting mismatches with on-disk blocks");
        }
        Ok(chain_validation)
    }
    fn init_provisional_snapshot_bootstrap(
        block_store: &mut BlockStore,
        block_index_count: usize,
        audited_height: usize,
        _v2_finality_floor: Option<u64>,
    ) -> Result<ChainValidation, Error> {
        let hashes_count = usize::try_from(block_store.read_hashes_count()?)?;
        if hashes_count != block_index_count || block_index_count < audited_height {
            return Err(Error::HashesFileHeightMismatch);
        }
        let hashes = block_store.read_block_hashes(0, hashes_count)?;
        let mut block_indices = vec![BlockIndex::default(); block_index_count];
        block_store.read_block_indices(0, &mut block_indices)?;
        let data_file_len = block_store.data_file_len()?;
        let mut buffer = Vec::new();
        let mut previous_hash = audited_height
            .checked_sub(1)
            .and_then(|index| hashes.get(index))
            .copied();
        for (index, block_index) in block_indices.iter().enumerate().skip(audited_height) {
            let height = u64::try_from(index)?.saturating_add(1);
            if block_index.length == 0 || block_index.length > STRICT_INIT_MAX_BLOCK_BYTES {
                return Err(Error::InvalidProvisionalSnapshotSuffix {
                    height,
                    reason: format!(
                        "block length {} is zero or exceeds the strict limit",
                        block_index.length
                    ),
                });
            }
            let header = if block_index.is_evicted() {
                block_store.verified_evicted_block_header(
                    height,
                    hashes[index],
                    block_index.length,
                )?
            } else {
                let end = block_index.start.checked_add(block_index.length).ok_or(
                    Error::CorruptedBlockRange {
                        start: block_index.start,
                        length: block_index.length,
                        data_len: data_file_len,
                    },
                )?;
                if end > data_file_len {
                    return Err(Error::CorruptedBlockRange {
                        start: block_index.start,
                        length: block_index.length,
                        data_len: data_file_len,
                    });
                }
                buffer.resize(usize::try_from(block_index.length)?, 0);
                block_store.read_block_data(block_index.start, &mut buffer)?;
                decode_framed_signed_block(&buffer)
                    .map_err(|error| Error::InvalidProvisionalSnapshotSuffix {
                        height,
                        reason: format!("canonical block body is not decodable: {error}"),
                    })?
                    .header()
            };
            if header.height().get() != height
                || header.prev_block_hash() != previous_hash
                || header.hash() != hashes[index]
            {
                return Err(Error::InvalidProvisionalSnapshotSuffix {
                    height,
                    reason: "block height, parent hash, or canonical header hash mismatches the durable journal"
                        .to_owned(),
                });
            }
            previous_hash = Some(hashes[index]);
        }
        Ok(ChainValidation {
            hashes,
            truncated: false,
            hash_mismatch: false,
            hard_fork_hash_only_block_count: audited_height,
        })
    }
    fn ensure_startup_rewrite_respects_v2_finality(
        v2_finality_floor: Option<u64>,
        rewrite_from_height: u64,
    ) -> Result<()> {
        if let Some(finalized_height) = v2_finality_floor
            && finalized_height >= rewrite_from_height
        {
            return Err(Error::FinalizedV2BlockMutation {
                rewrite_from_height,
                finalized_height,
            });
        }
        Ok(())
    }
    fn rewrite_validated_block_hashes(
        block_store: &mut BlockStore,
        hashes: &[HashOf<BlockHeader>],
        v2_finality_floor: Option<u64>,
    ) -> Result<()> {
        let Some(finalized_height) = v2_finality_floor else {
            return block_store.overwrite_block_hashes(hashes);
        };
        let suffix_start = usize::try_from(finalized_height)?;
        let Some(suffix) = hashes.get(suffix_start..) else {
            return Err(Error::HashesFileHeightMismatch);
        };
        block_store.overwrite_block_hash_suffix(finalized_height, suffix)
    }
    /// Open the exact durable journal without decoding historical block bodies.
    ///
    /// Read-only preflight has already bound the durable count and terminal hash.
    /// Fast mode leaves any unpublished suffix untouched and deliberately trusts the
    /// committed journal prefix. A requested block is still decoded and checked
    /// lazily before it is returned.
    fn init_fast_mode(
        block_store: &mut BlockStore,
        block_index_count: usize,
        v2_finality_floor: Option<u64>,
    ) -> Result<ChainValidation, Error> {
        if block_store.fast_prevalidated_count != Some(u64::try_from(block_index_count)?) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "Kura fast init did not pass the read-only committed-prefix preflight",
                ),
                block_store.path_to_blockchain.clone(),
            ));
        }
        block_store.fast_prevalidated_count = None;
        if block_store.read_exact_durable_index_count()? != u64::try_from(block_index_count)? {
            return Err(Error::HashesFileHeightMismatch);
        }
        let durable_height = u64::try_from(block_index_count)?;
        if let Some(finalized_height) = v2_finality_floor
            && durable_height < finalized_height
        {
            return Err(Error::V2FinalityBeyondDurableChain {
                finalized_height,
                durable_height,
            });
        }
        Ok(ChainValidation {
            // Fast keeps only the durable count and reads exact hashes on demand. This avoids
            // startup I/O and RAM proportional to total chain height.
            hashes: Vec::new(),
            truncated: false,
            hash_mismatch: false,
            hard_fork_hash_only_block_count: 0,
        })
    }
    fn init_canonical_chain(
        block_store: &mut BlockStore,
        block_index_count: usize,
        v2_finality_floor: Option<u64>,
    ) -> Result<ChainValidation, Error> {
        let mut block_indices = vec![BlockIndex::default(); block_index_count];
        block_store.read_block_indices(0, &mut block_indices)?;
        let hashes_count = block_store.read_hashes_count()?;
        if let Some(finalized_height) = v2_finality_floor {
            if u64::try_from(block_index_count)? < finalized_height {
                return Err(Error::FinalizedV2BlockMutation {
                    rewrite_from_height: u64::try_from(block_index_count)?.saturating_add(1),
                    finalized_height,
                });
            }
            if hashes_count < finalized_height {
                return Err(Error::FinalizedV2BlockMutation {
                    rewrite_from_height: hashes_count.saturating_add(1),
                    finalized_height,
                });
            }
        }
        let hash_journal_is_exact = hashes_count == block_index_count as u64;
        let expected_hashes = if hash_journal_is_exact {
            Some(block_store.read_block_hashes(0, block_index_count)?)
        } else if let Some(finalized_height) = v2_finality_floor {
            let finalized_count = usize::try_from(finalized_height)?;
            warn!(
                hashes_count,
                index_count = block_index_count,
                finalized_height,
                "strict Kura init is retaining the finalized hash prefix and rebuilding only its mutable suffix"
            );
            Some(block_store.read_block_hashes(0, finalized_count)?)
        } else {
            if hashes_count > 0 {
                warn!(
                    hashes_count,
                    index_count = block_index_count,
                    "strict Kura init cannot use hashes file for remote-only block metadata"
                );
            }
            None
        };
        let validation = Self::validate_block_chain(
            block_store,
            &block_indices,
            expected_hashes.as_deref(),
            0,
            v2_finality_floor,
        )?;
        if !hash_journal_is_exact || validation.truncated || validation.hash_mismatch {
            Self::rewrite_validated_block_hashes(
                block_store,
                &validation.hashes,
                v2_finality_floor,
            )?;
        }
        Ok(validation)
    }
    #[allow(clippy::too_many_lines)]
    fn validate_block_chain(
        block_store: &mut BlockStore,
        block_indices: &[BlockIndex],
        expected_hashes: Option<&[HashOf<BlockHeader>]>,
        mut hash_only_prefix: usize,
        v2_finality_floor: Option<u64>,
    ) -> Result<ChainValidation, Error> {
        let hashes_count = block_store.read_hashes_count()?;
        let verified_snapshot_tail = block_store
            .validated_verified_snapshot_tail(u64::try_from(block_indices.len())?, hashes_count)?;
        if let Some(marker) = verified_snapshot_tail.as_ref()
            && marker.body_prefix_count == marker.snapshot_height
        {
            hash_only_prefix = hash_only_prefix.max(usize::try_from(marker.snapshot_height)?);
        }
        if let Some(expected) = expected_hashes {
            if expected.len() > block_indices.len() || expected.len() < hash_only_prefix {
                return Err(Error::HashesFileHeightMismatch);
            }
        } else if hash_only_prefix > 0 {
            return Err(Error::HashesFileHeightMismatch);
        }
        let mut block_hashes = Vec::with_capacity(block_indices.len());
        let mut block_data_buffer = Vec::new();
        let mut prev_block_hash = None;
        let data_file_len = block_store.data_file_len()?;
        let mut truncated = None;
        let mut hash_mismatch = false;
        for (idx, block) in block_indices.iter().enumerate() {
            let height = idx.saturating_add(1) as u64;
            if idx < hash_only_prefix {
                let expected = expected_hashes
                    .and_then(|hashes| hashes.get(idx))
                    .copied()
                    .ok_or(Error::HashesFileHeightMismatch)?;
                prev_block_hash = Some(expected);
                block_hashes.push(expected);
                continue;
            }
            if block.length == 0
                && block.is_evicted()
                && expected_hashes.is_some_and(|hashes| hashes.get(idx).is_some())
                && verified_snapshot_tail.as_ref().is_some_and(|marker| {
                    let position = u64::try_from(idx).unwrap_or(u64::MAX);
                    let marker_start = if marker.body_prefix_count == marker.snapshot_height {
                        0
                    } else {
                        marker.body_prefix_count
                    };
                    position >= marker_start && position < marker.snapshot_height
                })
            {
                let expected = expected_hashes
                    .and_then(|hashes| hashes.get(idx))
                    .copied()
                    .ok_or(Error::HashesFileHeightMismatch)?;
                debug!(
                    block_index = idx,
                    height,
                    block = %expected,
                    "preserving verified snapshot hash-only block metadata from hashes file"
                );
                prev_block_hash = Some(expected);
                block_hashes.push(expected);
                continue;
            }
            if block.length == 0 {
                truncated = Some(true);
                error!(
                    length = block.length,
                    limit = STRICT_INIT_MAX_BLOCK_BYTES,
                    "Encountered zero-length block entry; pruning to last valid block"
                );
                break;
            }
            if block.length > STRICT_INIT_MAX_BLOCK_BYTES {
                truncated = Some(true);
                error!(
                    length = block.length,
                    limit = STRICT_INIT_MAX_BLOCK_BYTES,
                    "Encountered oversized block entry; pruning to last valid block"
                );
                break;
            }
            let decoded_block = if block.is_evicted() {
                let expected_evicted_hash =
                    expected_hashes.and_then(|hashes| hashes.get(idx)).copied();
                let expected_evicted_hash =
                    expected_evicted_hash.ok_or(Error::HashesFileHeightMismatch)?;
                let signed_wire_hash = block_store.verified_v2_finality_wire_hash(
                    height,
                    expected_evicted_hash,
                    block.length,
                )?;
                let payload = match block_store.read_optional_da_cache(height) {
                    Ok(payload) => payload,
                    Err(error) => {
                        return Err(error);
                    }
                };
                let Some(payload) = payload else {
                    debug!(
                        block_index = idx,
                        height,
                        block = %expected_evicted_hash,
                        "preserving signed remote-only evicted block metadata from hashes file"
                    );
                    prev_block_hash = Some(expected_evicted_hash);
                    block_hashes.push(expected_evicted_hash);
                    continue;
                };
                {
                    let expected = expected_evicted_hash;
                    let retained_wire_hash = signed_wire_hash;
                    if u64::try_from(payload.len())? != block.length
                        || Hash::new(&payload) != retained_wire_hash
                    {
                        warn!(
                            block_index = idx,
                            height,
                            block = %expected,
                            "removing noncanonical DA cache and preserving remote-only metadata"
                        );
                        if let Err(remove_error) = block_store.remove_da_block_file(height) {
                            warn!(
                                ?remove_error,
                                height, "failed to remove complete-wire-mismatched DA block cache"
                            );
                        }
                        prev_block_hash = Some(expected);
                        block_hashes.push(expected);
                        continue;
                    }
                }
                match decode_framed_signed_block(&payload) {
                    Ok(decoded_block) => {
                        {
                            let expected = expected_evicted_hash;
                            let actual = decoded_block.hash();
                            if actual != expected {
                                warn!(
                                    expected = %expected,
                                    actual = %actual,
                                    block_index = idx,
                                    height,
                                    "removing local sidecar with mismatched block hash and preserving remote-only metadata"
                                );
                                if let Err(remove_error) = block_store.remove_da_block_file(height)
                                {
                                    warn!(
                                        ?remove_error,
                                        height, "failed to remove hash-mismatched DA block sidecar"
                                    );
                                }
                                prev_block_hash = Some(expected);
                                block_hashes.push(expected);
                                continue;
                            }
                        }
                        decoded_block
                    }
                    Err(error) => {
                        let expected = expected_evicted_hash;
                        warn!(
                            ?error,
                            block_index = idx,
                            height,
                            block = %expected,
                            "removing malformed local sidecar and preserving remote-only block metadata"
                        );
                        if let Err(remove_error) = block_store.remove_da_block_file(height) {
                            warn!(
                                ?remove_error,
                                height, "failed to remove malformed DA block sidecar"
                            );
                        }
                        prev_block_hash = Some(expected);
                        block_hashes.push(expected);
                        continue;
                    }
                }
            } else {
                let end =
                    block
                        .start
                        .checked_add(block.length)
                        .ok_or(Error::CorruptedBlockRange {
                            start: block.start,
                            length: block.length,
                            data_len: data_file_len,
                        })?;
                if end > data_file_len {
                    truncated = Some(true);
                    error!(
                        start = block.start,
                        length = block.length,
                        data_len = data_file_len,
                        "Block index points past data file; pruning to last valid block"
                    );
                    break;
                }
                let length: usize = block.length.try_into()?;
                let additional = length.saturating_sub(block_data_buffer.len());
                if additional > 0 {
                    block_data_buffer.try_reserve(additional)?;
                }
                block_data_buffer.resize(length, 0);
                match block_store.read_block_data(block.start, &mut block_data_buffer) {
                    Ok(()) => match decode_framed_signed_block(&block_data_buffer) {
                        Ok(decoded_block) => decoded_block,
                        Err(error) => {
                            truncated = Some(true);
                            error!(
                                ?error,
                                block_index = idx,
                                "Malformed block payload; pruning to last valid block"
                            );
                            break;
                        }
                    },
                    Err(error) => {
                        truncated = Some(true);
                        error!(
                            ?error,
                            block_index = idx,
                            "Failed to read block payload; pruning to last valid block"
                        );
                        break;
                    }
                }
            };
            if prev_block_hash != decoded_block.header().prev_block_hash() {
                truncated = Some(true);
                error!(
                    expected = ?prev_block_hash,
                    actual = ?decoded_block.header().prev_block_hash(),
                    block_index = idx,
                    "Previous block hash mismatch; pruning to last valid block"
                );
                break;
            }
            let decoded_block_hash = decoded_block.hash();
            if let Some(expected) = expected_hashes.and_then(|hashes| hashes.get(idx)).copied() {
                if expected != decoded_block_hash {
                    Self::ensure_startup_rewrite_respects_v2_finality(v2_finality_floor, height)?;
                    hash_mismatch = true;
                    warn!(
                        expected = ?expected,
                        actual = ?decoded_block_hash,
                        block_index = idx,
                        "Block hash file entry mismatched decoded block; rewriting hashes file"
                    );
                }
            }
            prev_block_hash = Some(decoded_block_hash);
            block_hashes.push(decoded_block_hash);
        }
        let truncated = truncated.unwrap_or(false);
        let validated_height = block_hashes.len() as u64;
        if truncated {
            Self::ensure_startup_rewrite_respects_v2_finality(
                v2_finality_floor,
                validated_height.saturating_add(1),
            )?;
            block_store.prune(validated_height)?;
            info!(
                validated_height,
                "Pruned Kura storage to last validated block after detecting corruption"
            );
        }
        let authenticated_hash_only_block_count = verified_snapshot_tail
            .as_ref()
            .filter(|marker| marker.body_prefix_count == marker.snapshot_height)
            .and_then(|marker| usize::try_from(marker.snapshot_height).ok())
            .unwrap_or(hash_only_prefix)
            .min(block_hashes.len());
        Ok(ChainValidation {
            hashes: block_hashes,
            truncated,
            hash_mismatch,
            hard_fork_hash_only_block_count: authenticated_hash_only_block_count,
        })
    }
    #[iroha_logger::log(skip_all)]
    fn receive_blocks_loop(&self, shutdown_signal: &ShutdownSignal) {
        let kura = self;
        let block_rx = kura
            .block_notify_rx
            .lock()
            .take()
            .expect("Kura writer thread already started");
        let mut should_exit = false;
        loop {
            if shutdown_signal.is_sent() {
                info!("Kura block thread is being shut down. Flushing sidecars and fsync state.");
                should_exit = true;
            }
            let prune_guard = kura.prune_lock.lock();
            if kura.prune_recovery_is_required() {
                error!("Kura writer stopped because canonical prune recovery requires restart");
                return;
            }
            kura.flush_pipeline_sidecars();
            kura.flush_fastpq_proof_snapshots();
            kura.flush_pending_budget_eviction();
            drop(prune_guard);
            if should_exit {
                let _prune_guard = kura.prune_lock.lock();
                if kura.prune_recovery_is_required() {
                    error!("Kura writer stopped because canonical prune recovery requires restart");
                    return;
                }
                let flush_result = {
                    let mut store = kura.block_store.lock();
                    store.flush_pending_fsync(true)
                };
                if let Err(error) = flush_result {
                    error!(?error, "Failed to fsync pending blocks on shutdown");
                    kura.record_or_poison_fsync_fault("shutdown fsync", &error);
                    return;
                }
                info!("Kura has flushed sidecars and pending fsync state and is shutting down.");
                return;
            }
            let wait_for_fsync = {
                let guard = kura.block_store.lock();
                guard.next_fsync_wait()
            };
            match wait_for_fsync {
                Some(wait) => match block_rx.recv_timeout(wait) {
                    Ok(BlockNotify::NewBlock) => {
                        debug!("kura writer received sidecar flush signal");
                    }
                    Ok(BlockNotify::StorageBudgetEviction) => {
                        debug!("kura writer received storage-budget eviction signal");
                    }
                    Ok(BlockNotify::Shutdown) => {
                        should_exit = true;
                        debug!("kura writer received shutdown signal");
                    }
                    Err(RecvTimeoutError::Timeout) => {
                        let _prune_guard = kura.prune_lock.lock();
                        if kura.prune_recovery_is_required() {
                            error!(
                                "Kura writer stopped because canonical prune recovery requires restart"
                            );
                            return;
                        }
                        let mut store = kura.block_store.lock();
                        if let Err(error) = store.flush_pending_fsync(false) {
                            error!(?error, "Failed to fsync pending batch");
                            drop(store);
                            kura.record_or_poison_fsync_fault("periodic fsync", &error);
                            return;
                        }
                    }
                    Err(RecvTimeoutError::Disconnected) => {
                        info!("Block writer channel closed; exiting thread.");
                        return;
                    }
                },
                None => match block_rx.recv() {
                    Ok(BlockNotify::NewBlock) => {
                        debug!("kura writer received sidecar flush signal");
                    }
                    Ok(BlockNotify::StorageBudgetEviction) => {
                        debug!("kura writer received storage-budget eviction signal");
                    }
                    Ok(BlockNotify::Shutdown) => {
                        should_exit = true;
                        debug!("kura writer received shutdown signal");
                    }
                    Err(error) => {
                        info!(?error, "Block writer channel closed; exiting thread.");
                        return;
                    }
                },
            }
        }
    }
    /// Get the hash of the block at the provided height.
    pub fn get_block_hash(&self, block_height: NonZeroUsize) -> Option<HashOf<BlockHeader>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        #[cfg(test)]
        self.observe_canonical_read_after_prune_check_for_tests(CANONICAL_HASH_READER_OBSERVED);
        if self.emergency_fast_startup_enabled() {
            return self.get_durable_block_hash(block_height);
        }
        let hash_data_guard = self.block_data.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let block_height = block_height.get();
        if hash_data_guard.len() < block_height {
            return None;
        }
        let block_index = block_height - 1;
        hash_data_guard.get(block_index).map(|(hash, _)| *hash)
    }
    /// Get the committed hash at the provided height from Kura's durable hash journal.
    pub fn get_durable_block_hash(
        &self,
        block_height: NonZeroUsize,
    ) -> Option<HashOf<BlockHeader>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let height = u64::try_from(block_height.get()).ok()?;
        let mut block_store = self.block_store.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let hash = Self::read_durable_hash_at_height(&mut block_store, height)
            .ok()
            .flatten();
        if self.prune_recovery_is_required() {
            return None;
        }
        hash
    }
    /// Resolve the height of the block with the given hash.
    ///
    /// Emergency Fast mode resolves only hashes learned after startup or by a
    /// height-based block read. It deliberately does not scan the complete
    /// durable hash journal to answer a reverse lookup.
    pub fn get_block_height_by_hash(&self, hash: HashOf<BlockHeader>) -> Option<NonZeroUsize> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let cached = self.block_height_index.lock().get(&hash).copied();
        if self.prune_recovery_is_required() {
            return None;
        }
        cached
    }
    /// Resolve block heights containing the given transaction entrypoint hash.
    ///
    /// Returns `None` when the in-memory index is known to be partial, so callers can fall back to
    /// scanning blocks without risking incomplete query results.
    pub fn get_block_heights_by_entrypoint_hash(
        &self,
        hash: HashOf<TransactionEntrypoint>,
    ) -> Option<BTreeSet<NonZeroUsize>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let index = self.transaction_entrypoint_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let heights = index.complete.then(|| {
            index
                .heights_by_entrypoint
                .get(&hash)
                .cloned()
                .unwrap_or_default()
        });
        if self.prune_recovery_is_required() {
            return None;
        }
        heights
    }
    /// Resolve the earliest block height containing an issuer-bound offline operation.
    ///
    /// The outer `None` means the in-memory transaction index is partial. An inner `None`
    /// means the complete index contains no operation with both the requested outer transaction
    /// authority and signed operation identifier. Binding the lookup to the outer authority keeps
    /// a rejected transaction from another authority from shadowing a Torii-issued operation.
    /// Returning only the earliest height bounds request-time work even if invalid historical data
    /// reused an identifier within one issuer namespace.
    pub fn get_earliest_block_height_by_offline_operation_id(
        &self,
        issuer: &AccountId,
        operation_id: [u8; 32],
    ) -> Option<Option<NonZeroUsize>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        #[cfg(test)]
        self.observe_canonical_read_after_prune_check_for_tests(OFFLINE_OPERATION_READER_OBSERVED);
        let index = self.transaction_entrypoint_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let height = index.complete.then(|| {
            index
                .heights_by_offline_operation_id
                .get(&(issuer.clone(), operation_id))
                .and_then(|heights| heights.first().copied())
        });
        if self.prune_recovery_is_required() {
            return None;
        }
        height
    }
    /// Resolve block heights containing committed transactions with the given authority.
