    fn validate_v2_startup_replay_storage_binding_unlocked(
        &self,
        binding: &V2StartupReplayStorageBinding,
    ) -> Result<()> {
        let V2StartupReplayStorageBinding::Strict(inventory) = binding else {
            let V2StartupReplayStorageBinding::EmergencyFast(binding) = binding else {
                unreachable!("startup replay binding variants are exhaustive");
            };
            let blocks_dir = self.active_blocks_dir.lock().clone();
            let current_storage = self.canonical_block_store_metadata(&blocks_dir)?;
            let boundary_tip_matches =
                self.emergency_fast_replay_boundary_matches(binding.count, binding.tip_hash)?;
            let current_storage_after_tip = self.canonical_block_store_metadata(&blocks_dir)?;
            if !boundary_tip_matches
                || !Self::canonical_block_store_metadata_unchanged(
                    &binding.canonical_storage,
                    &current_storage,
                )
                || !Self::canonical_block_store_metadata_unchanged(
                    &current_storage,
                    &current_storage_after_tip,
                )
            {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "Kura emergency Fast startup journal changed after replay planning",
                    ),
                    blocks_dir,
                ));
            }
            return Ok(());
        };
        let inventory = inventory.as_ref();
        let blocks_dir = self.active_blocks_dir.lock().clone();
        let current_storage = self.canonical_block_store_metadata(&blocks_dir)?;
        let boundary_tip_matches =
            self.v2_startup_replay_boundary_tip_matches(&inventory.boundary)?;
        let current_storage_after_tip = self.canonical_block_store_metadata(&blocks_dir)?;
        let current_finality_directory =
            self.stable_sidecar_directory_metadata(&inventory.finality_directory.expected_path)?;
        let current_retained_directory =
            self.stable_sidecar_directory_metadata(&inventory.retained_directory.expected_path)?;
        if !boundary_tip_matches
            || !Self::canonical_block_store_metadata_unchanged(
                &inventory.canonical_storage,
                &current_storage,
            )
            || !Self::canonical_block_store_metadata_unchanged(
                &current_storage,
                &current_storage_after_tip,
            )
            || !Self::stable_sidecar_directory_metadata_unchanged(
                &inventory.finality_directory,
                &current_finality_directory,
            )
            || !Self::stable_sidecar_directory_metadata_unchanged(
                &inventory.retained_directory,
                &current_retained_directory,
            )
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "Kura startup replay storage identity changed after validation",
                ),
                blocks_dir,
            ));
        }
        let current_auxiliary = self.capture_v2_startup_replay_auxiliary_sidecars()?;
        if current_auxiliary.len() != inventory.auxiliary_sidecars.len()
            || inventory
                .auxiliary_sidecars
                .iter()
                .any(|(directory, expected)| {
                    current_auxiliary.get(directory).is_none_or(|current| {
                        !Self::stable_sidecar_directory_inventory_unchanged(expected, current)
                    })
                })
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "startup replay checkpoint, manifest, or lane sidecar identity changed",
                ),
                blocks_dir,
            ));
        }
        let finality_directory = Self::v2_finality_artifact_dir_for(&blocks_dir);
        let retained_directory = Self::retained_block_record_dir_for(&blocks_dir);
        for (&height, entry) in &inventory.entries {
            let finality_path = Self::v2_finality_artifact_path_for(&blocks_dir, height);
            let current_finality = self
                .regular_sidecar_metadata(&finality_path, &finality_directory)?
                .ok_or_else(|| {
                    Error::IO(
                        std::io::Error::new(
                            ErrorKind::NotFound,
                            "validated v2 finality sidecar disappeared before recovery",
                        ),
                        finality_path.clone(),
                    )
                })?;
            if !Self::stable_sidecar_metadata_unchanged(&entry.finality.metadata, &current_finality)
            {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "validated v2 finality sidecar changed before recovery",
                    ),
                    finality_path,
                ));
            }
            let retained_path = Self::retained_block_record_path_for(&blocks_dir, height);
            let current_retained = self
                .regular_sidecar_metadata(&retained_path, &retained_directory)?
                .ok_or_else(|| {
                    Error::IO(
                        std::io::Error::new(
                            ErrorKind::NotFound,
                            "validated retained block sidecar disappeared before recovery",
                        ),
                        retained_path.clone(),
                    )
                })?;
            if !Self::stable_sidecar_metadata_unchanged(
                &entry.retained_block.metadata,
                &current_retained,
            ) {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "validated retained block sidecar changed before recovery",
                    ),
                    retained_path,
                ));
            }
        }
        Ok(())
    }
    /// Revalidate the bounded storage authorization carried by a replay plan
    /// immediately before active-height recovery.
    pub(crate) fn validate_v2_startup_replay_storage_binding(
        &self,
        binding: &V2StartupReplayStorageBinding,
    ) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.ensure_canonical_storage_not_poisoned()?;
        self.validate_v2_startup_replay_storage_binding_unlocked(binding)
    }
    /// Bind one replay-planning pass to the exact canonical storage image
    /// covered by the startup finality audit.
    ///
    /// `Ok(None)` means no reusable inventory is available; callers must use
    /// the ordinary fully validating finality reader.
    pub(crate) fn begin_v2_startup_finality_verification(
        &self,
    ) -> Result<Option<V2StartupFinalityVerificationSession<'_>>> {
        let prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let canonical_chain_guard = self.canonical_chain_lock.lock();
        self.ensure_canonical_storage_not_poisoned()?;
        let inventory = {
            let inventory = self.v2_startup_finality_verification_inventory.lock();
            let Some(inventory) = inventory.as_ref() else {
                return Ok(None);
            };
            Arc::clone(inventory)
        };
        let binding = V2StartupReplayStorageBinding::Strict(Arc::clone(&inventory));
        if self
            .validate_v2_startup_replay_storage_binding_unlocked(&binding)
            .is_err()
        {
            self.finish_v2_startup_finality_verification();
            return Ok(None);
        }
        Ok(Some(V2StartupFinalityVerificationSession {
            kura: self,
            _prune_guard: prune_guard,
            _canonical_chain_guard: canonical_chain_guard,
            inventory,
        }))
    }
    fn v2_startup_retained_entry_matches(
        &self,
        height: u64,
        retained_identity: &StableSidecarRead,
    ) -> bool {
        self.v2_startup_finality_verification_inventory
            .lock()
            .as_ref()
            .is_some_and(|inventory| {
                inventory.entries.get(&height).is_some_and(|entry| {
                    entry.retained_block.bytes_hash == retained_identity.bytes_hash
                        && Self::stable_sidecar_metadata_unchanged(
                            &entry.retained_block.metadata,
                            &retained_identity.metadata,
                        )
                })
            })
    }
    fn remember_verified_v2_finality_entry(&self, entry: VerifiedV2FinalityCacheEntry) {
        let mut cache = self.v2_finality_verification_cache.lock();
        cache.retain(|cached| cached.height != entry.height);
        while cache.len() >= V2_FINALITY_VERIFICATION_CACHE_CAPACITY {
            cache.pop_front();
        }
        cache.push_back(entry);
    }
    fn remember_verified_v2_finality(
        &self,
        height: u64,
        artifact_hash: HashOf<V2FinalityArtifact>,
        bytes_hash: Hash,
        metadata: StableSidecarMetadata,
    ) {
        self.remember_verified_v2_finality_entry(VerifiedV2FinalityCacheEntry {
            height,
            artifact_hash,
            bytes_hash,
            metadata,
        });
    }
    fn verify_v2_finality_crypto(&self, artifact: &V2FinalityArtifact) -> Result<()> {
        #[cfg(test)]
        self.v2_finality_crypto_verifications
            .fetch_add(1, Ordering::Relaxed);
        artifact.verify()?;
        Ok(())
    }
    fn verify_v2_finality_artifact_uncached_at(
        &self,
        path: &Path,
        directory: &Path,
        artifact: &V2FinalityArtifact,
        read_identity: &StableSidecarRead,
    ) -> Result<VerifiedV2FinalityCacheEntry> {
        let current_metadata =
            self.regular_sidecar_metadata(path, directory)?
                .ok_or_else(|| {
                    Error::IO(
                        std::io::Error::new(
                            ErrorKind::NotFound,
                            "v2 finality sidecar disappeared before verification",
                        ),
                        path.to_path_buf(),
                    )
                })?;
        if !Self::stable_sidecar_metadata_unchanged(&read_identity.metadata, &current_metadata) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "v2 finality sidecar changed between decoding and verification",
                ),
                path.to_path_buf(),
            ));
        }
        let artifact_hash = HashOf::new(artifact);
        self.verify_v2_finality_crypto(artifact)?;
        let after = self
            .regular_sidecar_metadata(path, directory)?
            .ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "v2 finality sidecar disappeared after verification",
                    ),
                    path.to_path_buf(),
                )
            })?;
        if !Self::stable_sidecar_metadata_unchanged(&current_metadata, &after) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "v2 finality sidecar changed during cryptographic verification",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(VerifiedV2FinalityCacheEntry {
            height: artifact.height,
            artifact_hash,
            bytes_hash: read_identity.bytes_hash,
            metadata: after,
        })
    }
    fn verify_v2_finality_artifact_at(
        &self,
        path: &Path,
        directory: &Path,
        artifact: &V2FinalityArtifact,
        read_identity: &StableSidecarRead,
    ) -> Result<()> {
        let current_metadata =
            self.regular_sidecar_metadata(path, directory)?
                .ok_or_else(|| {
                    Error::IO(
                        std::io::Error::new(
                            ErrorKind::NotFound,
                            "v2 finality sidecar disappeared before verification",
                        ),
                        path.to_path_buf(),
                    )
                })?;
        if !Self::stable_sidecar_metadata_unchanged(&read_identity.metadata, &current_metadata) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "v2 finality sidecar changed between decoding and verification",
                ),
                path.to_path_buf(),
            ));
        }
        let artifact_hash = HashOf::new(artifact);
        if self.v2_finality_cache_hit(
            artifact.height,
            artifact_hash,
            read_identity.bytes_hash,
            &current_metadata,
        ) {
            return Ok(());
        }
        if self.v2_startup_finality_verification_hit(
            artifact.height,
            artifact_hash,
            read_identity.bytes_hash,
            &current_metadata,
        ) {
            self.remember_verified_v2_finality(
                artifact.height,
                artifact_hash,
                read_identity.bytes_hash,
                current_metadata,
            );
            return Ok(());
        }
        let entry =
            self.verify_v2_finality_artifact_uncached_at(path, directory, artifact, read_identity)?;
        self.remember_verified_v2_finality_entry(entry);
        Ok(())
    }
    fn cache_newly_verified_v2_finality(
        &self,
        path: &Path,
        directory: &Path,
        record: &KuraV2FinalityRecord,
    ) -> Result<()> {
        let snapshot = self
            .read_regular_sidecar_snapshot(path, directory, MAX_KURA_V2_FINALITY_RECORD_BYTES)?
            .ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "new v2 finality sidecar is missing after durable rename",
                    ),
                    path.to_path_buf(),
                )
            })?;
        let expected_bytes = record.encode();
        let bytes_hash = Hash::new(&expected_bytes);
        if snapshot.bytes != expected_bytes || snapshot.bytes_hash != bytes_hash {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "new v2 finality sidecar bytes changed after durable rename",
                ),
                path.to_path_buf(),
            ));
        }
        self.remember_verified_v2_finality(
            record.artifact.height,
            HashOf::new(&record.artifact),
            bytes_hash,
            snapshot.metadata,
        );
        Ok(())
    }
    /// Return the chain-scoped root for consensus-v2 journals and transport stores.
    ///
    /// The directory is rooted directly below the immutable Kura store root, not
    /// below the relabelable primary-lane block directory. Live consensus stores
    /// therefore keep a stable pathname while a lane alias changes. A configured
    /// chain still never shares a safety WAL or body store with another Kura
    /// instance. Callers create and synchronise their own children; Kura
    /// deliberately does not create this path as a side effect of lookup.
    pub(crate) fn sumeragi_v2_storage_root(&self) -> PathBuf {
        self.store_root.join("sumeragi_v2")
    }
    /// Project a comparison-only identity for this exact live Kura owner.
    pub(crate) fn instance_identity(&self) -> KuraInstanceIdentity {
        KuraInstanceIdentity(Arc::clone(&self.instance_identity))
    }
    fn canonical_header_for_v2_finality(
        &self,
        block_height: NonZeroUsize,
        canonical_hash: HashOf<BlockHeader>,
        retained_header: Option<BlockHeader>,
    ) -> Result<BlockHeader> {
        let height = u64::try_from(block_height.get())?;
        let body_header = self.get_block(block_height).map(|block| block.header());
        if let Some(header) = body_header {
            let actual_hash = header.hash();
            if header.height().get() != height || actual_hash != canonical_hash {
                return Err(Error::BlockHeightConflict {
                    height,
                    expected: canonical_hash,
                    actual: actual_hash,
                });
            }
        }
        if let (Some(body), Some(retained)) = (body_header, retained_header)
            && body != retained
        {
            return Err(Error::ConflictingRetainedBlockRecord { height });
        }
        body_header
            .or(retained_header)
            .ok_or(Error::V2FinalityCanonicalHeaderUnavailable { height })
    }
    fn publish_merge_carrier_after_v2_finality_under_prune_and_canonical_guards(
        &self,
        height: u64,
        block_hash: HashOf<BlockHeader>,
    ) -> Result<()> {
        let Some(record) = self.merge_carrier_record_for_block(height, block_hash)? else {
            return Ok(());
        };
        let entry = self.validate_merge_carrier_record_under_prune_and_canonical_guards(record)?;
        let block_height = NonZeroUsize::new(usize::try_from(height)?)
            .ok_or_else(|| Error::MergeCarrierConflict("carrier height is zero".to_owned()))?;
        if let Some(block) = self.get_block_without_merge_sidecar(block_height) {
            let chain_len = self.block_data.lock().len();
            self.set_transaction_entrypoint_index_entry_with_merge(
                block_height.get(),
                &block,
                Some(&entry),
                chain_len,
                true,
            );
        } else {
            let (retained_header, _, _) = self
                .v2_finality_artifact_with_archive_under_prune_and_canonical_guards(height)?
                .ok_or_else(|| {
                    Error::MergeCarrierConflict(format!(
                        "finalized bodyless carrier {height} lost its retained finality header"
                    ))
                })?;
            let chain_len = self.block_data.lock().len();
            self.set_transaction_entrypoint_index_entry_from_finalized_bodyless_merge(
                block_height.get(),
                &retained_header,
                &entry,
                chain_len,
            )?;
        }
        self.remove_committed_pending_merge_entry_best_effort(record.entry_hash);
        Ok(())
    }
    /// Persist a cryptographically valid v2 finality artifact for an already durable block.
    ///
    /// The returned [`KuraV2CommitReceipt`] is created only after the artifact
    /// contents, canonical header, separately retained complete-block wire
    /// hash, atomic rename, artifact directory, and a newly created artifact
    /// directory entry have been synchronously persisted.
    ///
    /// # Errors
    ///
    /// Returns an error if the artifact is malformed, its height or block hash
    /// or signed payload hash differs from Kura's canonical durable block, or
    /// persistence fails.
    pub fn store_v2_finality_artifact(
        &self,
        artifact: &V2FinalityArtifact,
    ) -> Result<KuraV2CommitReceipt> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        artifact.validate()?;
        let height = artifact.height;
        let block_hash = artifact.block_hash;
        let artifact_bytes = artifact.encode();
        if artifact_bytes.len() > MAX_V2_FINALITY_ARTIFACT_BYTES {
            return Err(Error::V2FinalityArtifactTooLarge {
                actual: artifact_bytes.len(),
                max: MAX_V2_FINALITY_ARTIFACT_BYTES,
            });
        }
        // Finality association and destructive canonical-chain operations share
        // one serialization lock beneath the prune gate. Appends cannot change
        // an existing height, so the block-store writer lock is deliberately not
        // retained across BLS work or sidecar I/O.
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        // `canonical_chain_lock` excludes live canonical publication. Any
        // ambiguous publication has already latched canonical poison in the
        // writer, while startup resolves durable stages before constructing
        // this Kura. Finality therefore needs the ordinary mutation
        // authorization check, not `block_store_write_lock`; waiting for that
        // lock here would invert a block-data owner and deadlock finality.
        self.durable_mutation_authorized()?;
        let block_height = NonZeroUsize::new(usize::try_from(height)?)
            .ok_or(Error::V2FinalityCanonicalHeaderUnavailable { height })?;
        let blocks_dir = self.active_blocks_dir.lock().clone();
        let dir = Self::v2_finality_artifact_dir_for(&blocks_dir);
        let path = Self::v2_finality_artifact_path_for(&blocks_dir, height);
        self.ensure_durable_block_at_height(height, block_hash)?;
        let canonical_hash = self
            .get_durable_block_hash(block_height)
            .ok_or(Error::V2FinalityCanonicalHeaderUnavailable { height })?;
        let indexed_wire_len = self
            .block_store
            .lock()
            .read_block_index(height.saturating_sub(1))?
            .length;
        let (retained_header, prepared_retained_record) =
            match self.retained_block_record_at(&blocks_dir, height, canonical_hash)? {
                Some((
                    header,
                    proposal_wire_hash,
                    executed_block_wire_len,
                    executed_block_wire_hash,
                    _,
                    _,
                )) => {
                    if executed_block_wire_len != indexed_wire_len {
                        return Err(Error::V2FinalityExecutedBlockWireLengthMismatch { height });
                    }
                    Self::validate_v2_finality_wire_bindings(
                        height,
                        artifact,
                        proposal_wire_hash,
                        executed_block_wire_len,
                        executed_block_wire_hash,
                    )?;
                    (header, None)
                }
                None => {
                    let canonical_block = self
                        .get_block(block_height)
                        .ok_or(Error::V2FinalityCanonicalHeaderUnavailable { height })?;
                    let header = canonical_block.header();
                    if header.hash() != canonical_hash {
                        return Err(Error::BlockHeightConflict {
                            height,
                            expected: canonical_hash,
                            actual: header.hash(),
                        });
                    }
                    let prepared = Self::prepare_retained_block_record(
                        &blocks_dir,
                        canonical_hash,
                        canonical_block.as_ref(),
                    )?;
                    if prepared.block_header != header {
                        return Err(Error::ConflictingRetainedBlockRecord { height });
                    }
                    if prepared.executed_block_wire_len != indexed_wire_len {
                        return Err(Error::V2FinalityExecutedBlockWireLengthMismatch { height });
                    }
                    Self::validate_v2_finality_wire_bindings(
                        height,
                        artifact,
                        prepared.proposal_wire_hash,
                        prepared.executed_block_wire_len,
                        prepared.executed_block_wire_hash,
                    )?;
                    (header, Some(prepared))
                }
            };
        let canonical_header = self.canonical_header_for_v2_finality(
            block_height,
            canonical_hash,
            Some(retained_header),
        )?;
        artifact.validate_for_header(&canonical_header)?;
        let expected_merge_carrier = self
            .merge_carrier_commitment_for_finality_prepublication_under_prune_and_canonical_guards(
                block_height,
                &canonical_header,
            )?;
        if artifact.commit_qc.execution_commitment.merge_carrier != expected_merge_carrier {
            return Err(Error::MergeCarrierConflict(format!(
                "v2 finality for canonical block {height} does not commit to its exact merge carrier"
            )));
        }
        if let Some((existing, read_identity)) = self.decode_v2_finality_record_at(&path, &dir)? {
            Self::validate_v2_finality_record_at(&path, height, canonical_hash, &existing)?;
            if retained_header != existing.block_header {
                return Err(Error::ConflictingRetainedBlockRecord { height });
            }
            if existing.artifact != *artifact {
                return Err(Error::ConflictingV2FinalityArtifact { height });
            }
            self.verify_v2_finality_artifact_at(&path, &dir, &existing.artifact, &read_identity)?;
            if let Some(prepared) = prepared_retained_record.as_ref() {
                self.persist_prepared_retained_block_record(&blocks_dir, canonical_hash, prepared)?;
            }
            self.publish_merge_carrier_after_v2_finality_under_prune_and_canonical_guards(
                height,
                canonical_hash,
            )?;
            self.record_durable_v2_finality_telemetry(&existing.artifact);
            return Ok(v2_commit_receipt(&existing.artifact));
        }
        let record = KuraV2FinalityRecord::new(canonical_header, artifact.clone());
        Self::validate_v2_finality_record_at(&path, height, canonical_hash, &record)?;
        let bytes = record.encode();
        if bytes.len() > MAX_KURA_V2_FINALITY_RECORD_BYTES {
            return Err(Error::V2FinalityRecordTooLarge {
                actual: bytes.len(),
                max: MAX_KURA_V2_FINALITY_RECORD_BYTES,
            });
        }
        // A structurally coherent but forged certificate must not create even
        // ancillary retained evidence. Complete all cryptographic validation
        // before the first durable mutation in the new-artifact path.
        self.verify_v2_finality_crypto(artifact)?;
        if self.canonical_sidecar_directory(&dir)?.is_none() {
            create_dir_all_with_context(&dir)?;
            self.canonical_sidecar_directory(&dir)?.ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "Kura v2 finality directory disappeared after creation",
                    ),
                    dir.clone(),
                )
            })?;
        }
        if let Some(parent) = dir.parent() {
            sync_dir(parent).map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        }
        if let Some(prepared) = prepared_retained_record.as_ref() {
            self.persist_prepared_retained_block_record(&blocks_dir, canonical_hash, prepared)?;
        }
        #[cfg(test)]
        if self
            .fail_next_v2_finality_write
            .swap(false, Ordering::Relaxed)
        {
            return Err(Error::IO(
                std::io::Error::other("Kura Sumeragi v2 finality injected failure"),
                PathBuf::from("v2_finality_test_fail"),
            ));
        }
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        if !self.write_atomic_synced_noclobber(&path, &bytes)? {
            let Some((existing, read_identity)) = self.decode_v2_finality_record_at(&path, &dir)?
            else {
                return Err(Error::ConflictingV2FinalityArtifact { height });
            };
            Self::validate_v2_finality_record_at(&path, height, canonical_hash, &existing)?;
            if existing.artifact != *artifact {
                return Err(Error::ConflictingV2FinalityArtifact { height });
            }
            self.verify_v2_finality_artifact_at(&path, &dir, &existing.artifact, &read_identity)?;
            self.publish_merge_carrier_after_v2_finality_under_prune_and_canonical_guards(
                height,
                canonical_hash,
            )?;
            self.record_durable_v2_finality_telemetry(&existing.artifact);
            return Ok(v2_commit_receipt(&existing.artifact));
        }
        self.add_total_disk_usage_bytes(u64::try_from(bytes.len())?);
        self.cache_newly_verified_v2_finality(&path, &dir, &record)?;
        accounting_mutation.finish();
        self.publish_merge_carrier_after_v2_finality_under_prune_and_canonical_guards(
            height,
            canonical_hash,
        )?;
        self.record_durable_v2_finality_telemetry(artifact);
        Ok(v2_commit_receipt(artifact))
    }
    fn decode_v2_finality_record_at(
        &self,
        path: &Path,
        directory: &Path,
    ) -> Result<Option<(KuraV2FinalityRecord, StableSidecarRead)>> {
        self.record_startup_replay_historical_payload_read();
        let Some(snapshot) =
            self.read_regular_sidecar_snapshot(path, directory, MAX_KURA_V2_FINALITY_RECORD_BYTES)?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let record = KuraV2FinalityRecord::decode_all(&mut cursor).map_err(Error::NoritoFrame)?;
        if record.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "Kura v2 finality record is not canonically encoded",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((record, snapshot)))
    }
    fn validate_v2_finality_record_at(
        path: &Path,
        expected_height: u64,
        canonical_hash: HashOf<BlockHeader>,
        record: &KuraV2FinalityRecord,
    ) -> Result<()> {
        if record.format_version != KURA_V2_FINALITY_RECORD_VERSION {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "unsupported Kura v2 finality record version",
                ),
                path.to_path_buf(),
            ));
        }
        if record.artifact.height != expected_height {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "v2 finality artifact height does not match its canonical file name",
                ),
                path.to_path_buf(),
            ));
        }
        let artifact_len = record.artifact.encode().len();
        if artifact_len > MAX_V2_FINALITY_ARTIFACT_BYTES {
            return Err(Error::V2FinalityArtifactTooLarge {
                actual: artifact_len,
                max: MAX_V2_FINALITY_ARTIFACT_BYTES,
            });
        }
        let recorded_hash = record.block_header.hash();
        if recorded_hash != canonical_hash {
            return Err(Error::BlockHeightConflict {
                height: expected_height,
                expected: canonical_hash,
                actual: recorded_hash,
            });
        }
        record
            .artifact
            .validate_for_header(&record.block_header)
            .map_err(Error::from)
    }
    /// Read and cryptographically validate a v2 finality artifact for a durable block.
    ///
    /// A missing final path returns `Ok(None)`. Incomplete temporary files left
    /// before the atomic rename are ignored. A malformed final path or an
    /// artifact that does not match Kura's canonical header and separately
    /// retained complete-block wire hash fails closed.
    ///
    /// # Errors
    ///
    /// Returns an error if decoding, header association, proof-of-possession,
    /// or CommitQC verification fails, the height is zero or absent from the
    /// durable chain, or the canonical header/wire association differs.
    pub fn v2_finality_artifact(&self, height: u64) -> Result<Option<V2FinalityArtifact>> {
        Ok(self
            .v2_finality_artifact_with_header(height)?
            .map(|(_, artifact)| artifact))
    }
    /// Read exact finality as an opaque State-apply capability.
    ///
    /// The underlying reader performs the canonical BLS verification. Wrapping
    /// its result here preserves that provenance so replay does not verify the
    /// same aggregate a second time when changing the block lifecycle type.
    pub(crate) fn v2_finality_apply_authority(
        &self,
        height: u64,
    ) -> Result<Option<crate::block::VerifiedV2FinalityArtifact>> {
        Ok(self
            .v2_finality_artifact_with_header(height)?
            .map(|(_, artifact)| {
                crate::block::VerifiedV2FinalityArtifact::from_kura_verified(
                    VerifiedV2FinalityRead(artifact),
                )
            }))
    }
    /// Read a verified finality artifact together with its retained canonical header.
    ///
    /// The signed payload is also matched to the separately retained canonical
    /// `SignedBlock` wire hash. This remains available after the block body is
    /// evicted to remote-only storage.
    ///
    /// # Errors
    ///
    /// Returns an error if the durable record, canonical header/wire binding,
    /// artifact structure, or finality cryptography is invalid.
    pub(crate) fn v2_finality_artifact_with_header(
        &self,
        height: u64,
    ) -> Result<Option<(BlockHeader, V2FinalityArtifact)>> {
        Ok(self
            .v2_finality_artifact_with_archive(height)?
            .map(|(header, artifact, _)| (header, artifact)))
    }
    /// Read verified finality and the root-authenticated SCCP archive in one bounded pass.
    ///
    /// Rootless finalized blocks return an empty archive. Combining these reads prevents
    /// proof-serving callers from decoding and validating the retained record twice. The
    /// finality subject must equal that record's canonical complete-block wire hash.
    ///
    /// # Errors
    ///
    /// Returns an error if the finality record, retained block record, canonical header/wire
    /// binding, SCCP archive, or finality cryptography is invalid.
    pub(crate) fn v2_finality_artifact_with_archive(
        &self,
        height: u64,
    ) -> Result<
        Option<(
            BlockHeader,
            V2FinalityArtifact,
            Vec<crate::bridge::ValidatedSccpOutboundMessageProjectionV1>,
        )>,
    > {
        let _prune_guard = self.prune_lock.lock();
        self.v2_finality_artifact_with_archive_under_prune_guard(height)
    }
    /// Read verified finality and the immutable local merge-reference witness.
    ///
    /// The witness is bounded serving authority; recipients independently verify
    /// its compact reference and merge QC, so this API cannot create authority.
    ///
    /// # Errors
    ///
    /// Returns an error if finality, its association, or retained record is invalid.
    pub(crate) fn v2_finality_artifact_with_merge_reference(
        &self,
        height: u64,
    ) -> Result<
        Option<(
            BlockHeader,
            V2FinalityArtifact,
            Option<CertifiedMergeLedgerReference>,
        )>,
    > {
        let _prune_guard = self.prune_lock.lock();
        Ok(self
            .v2_finality_artifact_with_retained_witness_under_prune_guard(height)?
            .map(|(header, artifact, _, reference)| (header, artifact, reference)))
    }
    /// Inner finality reader for callers that already hold `prune_lock`.
    ///
    /// Keeping the complete canonical-header, retained-wire, and cryptographic
    /// validation here lets multi-artifact publication revalidate finality in
    /// the same prune critical section without recursively locking.
    fn v2_finality_artifact_with_archive_under_prune_guard(
        &self,
        height: u64,
    ) -> Result<
        Option<(
            BlockHeader,
            V2FinalityArtifact,
            Vec<crate::bridge::ValidatedSccpOutboundMessageProjectionV1>,
        )>,
    > {
        Ok(self
            .v2_finality_artifact_with_retained_witness_under_prune_guard(height)?
            .map(|(header, artifact, archive, _)| (header, artifact, archive)))
    }
    fn v2_finality_artifact_with_retained_witness_under_prune_guard(
        &self,
        height: u64,
    ) -> Result<
        Option<(
            BlockHeader,
            V2FinalityArtifact,
            Vec<crate::bridge::ValidatedSccpOutboundMessageProjectionV1>,
            Option<CertifiedMergeLedgerReference>,
        )>,
    > {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.v2_finality_artifact_with_retained_witness_under_prune_and_canonical_guards(height)
    }
    /// Inner finality reader for callers that already hold `prune_lock` and
    /// `canonical_chain_lock`, in that order.
    ///
    /// Geometry retirement and archive validation also hold
    /// `lane_geometry_lock` and `sidecar_lock`. Keeping this reader free of
    /// lock acquisition lets those paths authenticate retained Native AMX
    /// evidence without recursively acquiring the canonical-chain mutex.
    fn v2_finality_artifact_with_archive_under_prune_and_canonical_guards(
        &self,
        height: u64,
    ) -> Result<
        Option<(
            BlockHeader,
            V2FinalityArtifact,
            Vec<crate::bridge::ValidatedSccpOutboundMessageProjectionV1>,
        )>,
    > {
        Ok(self
            .v2_finality_artifact_with_retained_witness_under_prune_and_canonical_guards(height)?
            .map(|(header, artifact, archive, _)| (header, artifact, archive)))
    }
    fn v2_finality_artifact_with_retained_witness_under_prune_and_canonical_guards(
        &self,
        height: u64,
    ) -> Result<
        Option<(
            BlockHeader,
            V2FinalityArtifact,
            Vec<crate::bridge::ValidatedSccpOutboundMessageProjectionV1>,
            Option<CertifiedMergeLedgerReference>,
        )>,
    > {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let blocks_dir = self.active_blocks_dir.lock().clone();
        let directory = Self::v2_finality_artifact_dir_for(&blocks_dir);
        let path = Self::v2_finality_artifact_path_for(&blocks_dir, height);
        let Some((record, read_identity)) = self.decode_v2_finality_record_at(&path, &directory)?
        else {
            return Ok(None);
        };
        let Some(block_height) = NonZeroUsize::new(usize::try_from(height)?) else {
            return Err(Error::NoritoFrame(norito::core::Error::Message(
                "v2 finality artifact height must be non-zero".into(),
            )));
        };
        let block_hash = self.get_durable_block_hash(block_height);
        self.ensure_prune_recovery_not_required()?;
        let Some(block_hash) = block_hash else {
            return Err(Error::BlockHeightGap {
                expected_next_height: u64::try_from(self.exact_durable_blocks_count()?)?
                    .saturating_add(1),
                actual_height: height,
            });
        };
        Self::validate_v2_finality_record_at(&path, height, block_hash, &record)?;
        let (
            retained_header,
            proposal_wire_hash,
            executed_block_wire_len,
            executed_block_wire_hash,
            archive,
            merge_reference,
        ) = self
            .retained_block_record_at(&blocks_dir, height, block_hash)?
            .ok_or(Error::MissingRetainedBlockRecord { height })?;
        if retained_header != record.block_header {
            return Err(Error::ConflictingRetainedBlockRecord { height });
        }
        Self::validate_v2_finality_wire_bindings(
            height,
            &record.artifact,
            proposal_wire_hash,
            executed_block_wire_len,
            executed_block_wire_hash,
        )?;
        self.verify_v2_finality_artifact_at(&path, &directory, &record.artifact, &read_identity)?;
        Ok(Some((
            record.block_header,
            record.artifact,
            archive,
            merge_reference,
        )))
    }
    /// Recover a validated durable v2 finality artifact together with the
    /// same non-forgeable receipt minted by the write path.
    ///
    /// Final artifact paths are immutable: an idempotent repeat is accepted,
    /// while a conflicting rewrite is rejected by
    /// [`Self::store_v2_finality_artifact`]. Therefore a successfully read and
    /// canonical-block-checked artifact is sufficient to reconstruct its
    /// receipt during startup replay.
    pub fn v2_finality_artifact_with_receipt(
        &self,
        height: u64,
    ) -> Result<Option<(V2FinalityArtifact, KuraV2CommitReceipt)>> {
        let Some(artifact) = self.v2_finality_artifact(height)? else {
            return Ok(None);
        };
        let receipt = v2_commit_receipt(&artifact);
        Ok(Some((artifact, receipt)))
    }
    fn staged_kagemusha_topup_finality_from_witness(
        height: u64,
        block_hash: HashOf<BlockHeader>,
        witness: &ExecWitness,
        expected: ExecutionCommitment,
    ) -> Result<Option<StagedKagemushaTopUpFinalitySidecar>> {
        let writes = witness
            .writes
            .iter()
            .map(|entry| crate::sumeragi::smt::KvPair::new(entry.key.clone(), entry.value.clone()))
            .collect::<Vec<_>>();
        let commitment = crate::sumeragi::smt::build_kagemusha_topup_block_commitment(&writes)
            .map_err(|error| Error::KagemushaTopUpFinalitySidecar(error.to_owned()))?;
        let Some(commitment) = commitment else {
            if expected.topup_anchor_count != 0 || expected.topup_anchor_root.is_some() {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "signed execution commitment advertises top-ups absent from the witness"
                        .to_owned(),
                ));
            }
            return Ok(None);
        };
        if expected.ordinary_writes_root != commitment.ordinary_writes_root
            || expected.topup_anchor_root != Some(commitment.topup_anchor_root)
            || expected.post_state_root != commitment.post_state_root
            || usize::try_from(expected.topup_anchor_count).ok() != Some(commitment.leaves.len())
            || commitment.leaves.len() != commitment.proofs.len()
        {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "witness-derived top-up subtree differs from the signed execution commitment"
                    .to_owned(),
            ));
        }
        let leaves = commitment
            .leaves
            .iter()
            .zip(&commitment.proofs)
            .map(|(leaf, path)| {
                let operation_id = leaf
                    .key
                    .get(1..)
                    .and_then(|bytes| <[u8; 32]>::try_from(bytes).ok())
                    .ok_or_else(|| {
                        Error::KagemushaTopUpFinalitySidecar(
                            "witness top-up operation id has the wrong width".to_owned(),
                        )
                    })?;
                let anchor_digest = <[u8; 32]>::try_from(leaf.value.as_slice()).map_err(|_| {
                    Error::KagemushaTopUpFinalitySidecar(
                        "witness top-up anchor digest has the wrong width".to_owned(),
                    )
                })?;
                Ok(KagemushaTopUpFinalityLeaf {
                    operation_id,
                    anchor_digest,
                    leaf_index: path.leaf_index,
                    leaf_count: path.leaf_count,
                    siblings: path.siblings.clone(),
                })
            })
            .collect::<Result<Vec<_>>>()?;
        Ok(Some(StagedKagemushaTopUpFinalitySidecar {
            format: KagemushaTopUpFinalitySidecarFormat::Current,
            version: KagemushaTopUpFinalitySidecar::VERSION,
            height,
            block_hash,
            ordinary_writes_root: commitment.ordinary_writes_root,
            topup_anchor_root: commitment.topup_anchor_root,
            post_state_root: commitment.post_state_root,
            leaves,
        }))
    }
    fn validate_staged_kagemusha_topup_finality(
        staged: &StagedKagemushaTopUpFinalitySidecar,
        artifact: &V2FinalityArtifact,
    ) -> Result<()> {
        let commitment = artifact.commit_qc.execution_commitment;
        if staged.format != KagemushaTopUpFinalitySidecarFormat::Current
            || staged.version != KagemushaTopUpFinalitySidecar::VERSION
            || staged.height != artifact.height
            || staged.block_hash != artifact.block_hash
            || staged.ordinary_writes_root != commitment.ordinary_writes_root
            || Some(staged.topup_anchor_root) != commitment.topup_anchor_root
            || staged.post_state_root != commitment.post_state_root
            || usize::try_from(commitment.topup_anchor_count).ok() != Some(staged.leaves.len())
            || staged.leaves.is_empty()
            || staged
                .leaves
                .windows(2)
                .any(|pair| pair[0].operation_id >= pair[1].operation_id)
        {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "staged top-up sidecar differs from the exact finality artifact".to_owned(),
            ));
        }
        for (index, leaf) in staged.leaves.iter().enumerate() {
            if leaf.operation_id == [0; 32]
                || leaf.anchor_digest == [0; 32]
                || usize::try_from(leaf.leaf_index).ok() != Some(index)
                || usize::try_from(leaf.leaf_count).ok() != Some(staged.leaves.len())
            {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "staged top-up leaf identity or position is non-canonical".to_owned(),
                ));
            }
            let mut key = Vec::with_capacity(33);
            key.push(crate::sumeragi::smt::KAGEMUSHA_V4_TOPUP_ANCHOR_WITNESS_KEY_TAG);
            key.extend_from_slice(&leaf.operation_id);
            let pair = crate::sumeragi::smt::KvPair::new(key, leaf.anchor_digest);
            let path = crate::sumeragi::smt::KagemushaTopUpMerkleProof {
                leaf_index: leaf.leaf_index,
                leaf_count: leaf.leaf_count,
                siblings: leaf.siblings.clone(),
            };
            if !crate::sumeragi::smt::verify_kagemusha_topup_write_inclusion(
                &pair,
                &path,
                staged.ordinary_writes_root,
                staged.post_state_root,
            ) {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "staged top-up Merkle path does not match the signed post-state root"
                        .to_owned(),
                ));
            }
        }
        Ok(())
    }
    fn validate_kagemusha_topup_finality_sidecar(
        sidecar: &KagemushaTopUpFinalitySidecar,
        artifact: &V2FinalityArtifact,
    ) -> Result<()> {
        let staged = StagedKagemushaTopUpFinalitySidecar {
            format: sidecar.format,
            version: sidecar.version,
            height: sidecar.height,
            block_hash: sidecar.block_hash,
            ordinary_writes_root: sidecar.ordinary_writes_root,
            topup_anchor_root: sidecar.topup_anchor_root,
            post_state_root: sidecar.post_state_root,
            leaves: sidecar.leaves.clone(),
        };
        Self::validate_staged_kagemusha_topup_finality(&staged, artifact)?;
        if sidecar.finality_artifact_hash != HashOf::new(artifact) {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "top-up sidecar is bound to another finality artifact".to_owned(),
            ));
        }
        Ok(())
    }
    fn decode_staged_kagemusha_topup_finality(
        &self,
        path: &Path,
    ) -> Result<Option<(StagedKagemushaTopUpFinalitySidecar, StableSidecarRead)>> {
        let directory = self.kagemusha_topup_finality_staging_dir();
        let Some(snapshot) = self.read_regular_sidecar_snapshot(
            path,
            &directory,
            MAX_KAGEMUSHA_TOPUP_FINALITY_SIDECAR_BYTES,
        )?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let sidecar = StagedKagemushaTopUpFinalitySidecar::decode_all(&mut cursor)
            .map_err(Error::NoritoFrame)?;
        if sidecar.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "staged top-up sidecar is not the canonical Norito encoding",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((sidecar, snapshot)))
    }
    fn decode_kagemusha_topup_finality_sidecar(
        &self,
        path: &Path,
    ) -> Result<Option<(KagemushaTopUpFinalitySidecar, StableSidecarRead)>> {
        let directory = self.kagemusha_topup_finality_sidecar_dir();
        let Some(snapshot) = self.read_regular_sidecar_snapshot(
            path,
            &directory,
            MAX_KAGEMUSHA_TOPUP_FINALITY_SIDECAR_BYTES,
        )?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let sidecar =
            KagemushaTopUpFinalitySidecar::decode_all(&mut cursor).map_err(Error::NoritoFrame)?;
        if sidecar.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "final top-up sidecar is not the canonical Norito encoding",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((sidecar, snapshot)))
    }
    fn validate_staged_kagemusha_active_receiver_finality(
        staged: &StagedKagemushaActiveReceiverFinalitySidecarV1,
        artifact: &V2FinalityArtifact,
    ) -> Result<()> {
        let commitment = artifact.commit_qc.execution_commitment;
        let snapshot = staged
            .witness_proof
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        let validation_fee_snapshot = staged
            .validation_fee_policy_witness
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        let casting_snapshot = staged
            .parliament_timed_ovn_casting_witness
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        let rebuilt_casting_snapshot =
            ParliamentTimedOvnCastingSnapshotCommitmentV1::from_ordered_bindings(
                staged.height,
                &staged.parliament_timed_ovn_casting_bindings,
            )
            .map_err(|error| {
                Error::KagemushaActiveReceiverFinalitySidecar(format!(
                    "invalid retained Parliament timed-OVN casting bindings: {error}"
                ))
            })?;
        if staged.version != KagemushaActiveReceiverFinalitySidecarV1::VERSION
            || staged.height != artifact.height
            || staged.block_hash != artifact.block_hash
            || staged.ordinary_writes_root != commitment.ordinary_writes_root
            || staged.post_state_root != commitment.post_state_root
            || snapshot.evaluated_height != staged.height
            || !staged.witness_proof.verify(commitment.ordinary_writes_root)
            || validation_fee_snapshot.evaluated_height != staged.height
            || !staged
                .validation_fee_policy_witness
                .verify(commitment.ordinary_writes_root)
            || casting_snapshot.evaluated_height != staged.height
            || casting_snapshot != rebuilt_casting_snapshot
            || !staged
                .parliament_timed_ovn_casting_witness
                .verify(commitment.ordinary_writes_root)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "active-receiver witness stage differs from the exact finality artifact".to_owned(),
            ));
        }
        commitment.validate().map_err(|error| {
            Error::KagemushaActiveReceiverFinalitySidecar(format!(
                "active-receiver finality execution commitment is invalid: {error}"
            ))
        })?;
        Ok(())
    }
    fn validate_kagemusha_active_receiver_finality_sidecar(
        sidecar: &KagemushaActiveReceiverFinalitySidecarV1,
        artifact: &V2FinalityArtifact,
    ) -> Result<()> {
        Self::validate_staged_kagemusha_active_receiver_finality(
            &StagedKagemushaActiveReceiverFinalitySidecarV1 {
                version: sidecar.version,
                height: sidecar.height,
                block_hash: sidecar.block_hash,
                ordinary_writes_root: sidecar.ordinary_writes_root,
                post_state_root: sidecar.post_state_root,
                witness_proof: sidecar.witness_proof.clone(),
                validation_fee_policy_witness: sidecar.validation_fee_policy_witness.clone(),
                parliament_timed_ovn_casting_witness: sidecar
                    .parliament_timed_ovn_casting_witness
                    .clone(),
                parliament_timed_ovn_casting_bindings: sidecar
                    .parliament_timed_ovn_casting_bindings
                    .clone(),
            },
            artifact,
        )?;
        if sidecar.finality_artifact_hash != HashOf::new(artifact) {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "active-receiver sidecar is bound to another finality artifact".to_owned(),
            ));
        }
        Ok(())
    }
    fn decode_staged_kagemusha_active_receiver_finality(
        &self,
        path: &Path,
    ) -> Result<
        Option<(
            StagedKagemushaActiveReceiverFinalitySidecarV1,
            StableSidecarRead,
        )>,
    > {
        let directory = self.kagemusha_active_receiver_staging_dir();
        let Some(snapshot) = self.read_regular_sidecar_snapshot(
            path,
            &directory,
            MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES,
        )?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let sidecar = norito::with_decode_limits(
            kagemusha_active_receiver_decode_limits(snapshot.bytes.len()),
            || StagedKagemushaActiveReceiverFinalitySidecarV1::decode_all(&mut cursor),
        )
        .map_err(Error::NoritoFrame)?;
        if sidecar.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "staged active-receiver sidecar is not canonical Norito",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((sidecar, snapshot)))
    }
    fn decode_kagemusha_active_receiver_finality_sidecar(
        &self,
        path: &Path,
    ) -> Result<Option<(KagemushaActiveReceiverFinalitySidecarV1, StableSidecarRead)>> {
        let directory = self.kagemusha_active_receiver_sidecar_dir();
        let Some(snapshot) = self.read_regular_sidecar_snapshot(
            path,
            &directory,
            MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES,
        )?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let sidecar = norito::with_decode_limits(
            kagemusha_active_receiver_decode_limits(snapshot.bytes.len()),
            || KagemushaActiveReceiverFinalitySidecarV1::decode_all(&mut cursor),
        )
        .map_err(Error::NoritoFrame)?;
        if sidecar.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "final active-receiver sidecar is not canonical Norito",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((sidecar, snapshot)))
    }
    fn stage_kagemusha_active_receiver_finality_sidecar(
        &self,
        height: u64,
        block_hash: HashOf<BlockHeader>,
        witness: &ExecWitness,
        expected: ExecutionCommitment,
        parliament_timed_ovn_casting_bindings: &[ParliamentTimedOvnCastingContextBindingV1],
    ) -> Result<()> {
        self.durable_mutation_authorized()?;
        let (witness_proof, ordinary_writes_root) =
            crate::receiver_snapshot::active_receiver_witness_proof_v1(witness)
                .map_err(Error::KagemushaActiveReceiverFinalitySidecar)?;
        let (validation_fee_policy_witness, validation_fee_root) =
            crate::receiver_snapshot::validation_fee_policy_witness_proof_v1(witness)
                .map_err(Error::KagemushaActiveReceiverFinalitySidecar)?;
        let (parliament_timed_ovn_casting_witness, casting_root) =
            crate::receiver_snapshot::parliament_timed_ovn_casting_witness_proof_v1(witness)
                .map_err(Error::KagemushaActiveReceiverFinalitySidecar)?;
        if ordinary_writes_root != expected.ordinary_writes_root
            || validation_fee_root != ordinary_writes_root
            || casting_root != ordinary_writes_root
            || !witness_proof.verify(expected.ordinary_writes_root)
            || !validation_fee_policy_witness.verify(expected.ordinary_writes_root)
            || !parliament_timed_ovn_casting_witness.verify(expected.ordinary_writes_root)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "witness-derived active-receiver proof differs from the signed ordinary-write root"
                    .to_owned(),
            ));
        }
        let snapshot = witness_proof
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        if snapshot.evaluated_height != height {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "active-receiver snapshot height differs from its block".to_owned(),
            ));
        }
        let validation_fee_snapshot = validation_fee_policy_witness
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        if validation_fee_snapshot.evaluated_height != height {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "validation-fee snapshot height differs from its block".to_owned(),
            ));
        }
        let casting_snapshot = parliament_timed_ovn_casting_witness
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        let rebuilt_casting_snapshot =
            ParliamentTimedOvnCastingSnapshotCommitmentV1::from_ordered_bindings(
                height,
                parliament_timed_ovn_casting_bindings,
            )
            .map_err(|error| {
                Error::KagemushaActiveReceiverFinalitySidecar(format!(
                    "invalid Parliament timed-OVN casting bindings: {error}"
                ))
            })?;
        if casting_snapshot != rebuilt_casting_snapshot {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "Parliament timed-OVN casting leaves differ from the synthetic snapshot".to_owned(),
            ));
        }
        let staged = StagedKagemushaActiveReceiverFinalitySidecarV1 {
            version: KagemushaActiveReceiverFinalitySidecarV1::VERSION,
            height,
            block_hash,
            ordinary_writes_root,
            post_state_root: expected.post_state_root,
            witness_proof,
            validation_fee_policy_witness,
            parliament_timed_ovn_casting_witness,
            parliament_timed_ovn_casting_bindings: parliament_timed_ovn_casting_bindings.to_vec(),
        };
        let bytes = staged.encode();
        if bytes.len() > MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES {
            return Err(Error::KagemushaActiveReceiverFinalitySidecarTooLarge {
                actual: bytes.len(),
                max: MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES,
            });
        }
        let _guard = self.sidecar_lock.lock();
        let directory = self.kagemusha_active_receiver_staging_dir();
        create_dir_all_with_context(&directory)?;
        if let Some(parent) = directory.parent() {
            sync_dir(parent).map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        }
        let path = self.kagemusha_active_receiver_staging_path(height);
        if let Some((existing, identity)) =
            self.decode_staged_kagemusha_active_receiver_finality(&path)?
        {
            if existing == staged
                && identity.bytes == bytes
                && identity.bytes_hash == Hash::new(&bytes)
            {
                return Ok(());
            }
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "conflicting staged active-receiver sidecar at one height".to_owned(),
            ));
        }
        if !self.write_atomic_synced_noclobber(&path, &bytes)? {
            let Some((existing, _)) =
                self.decode_staged_kagemusha_active_receiver_finality(&path)?
            else {
                return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                    "staged active-receiver sidecar disappeared during publication".to_owned(),
                ));
            };
            if existing != staged {
                return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                    "no-clobber race published a conflicting active-receiver stage".to_owned(),
                ));
            }
        }
        let Some((persisted, identity)) =
            self.decode_staged_kagemusha_active_receiver_finality(&path)?
        else {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "staged active-receiver sidecar disappeared after publication".to_owned(),
            ));
        };
        if persisted != staged
            || identity.bytes != bytes
            || identity.bytes_hash != Hash::new(&bytes)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "staged active-receiver sidecar changed during readback".to_owned(),
            ));
        }
        Ok(())
    }
    fn remove_exact_staged_kagemusha_active_receiver_finality(
        &self,
        path: &Path,
        read_identity: &StableSidecarRead,
    ) -> Result<()> {
        let directory = self.kagemusha_active_receiver_staging_dir();
        let Some(current) = self.regular_sidecar_metadata(path, &directory)? else {
            return Ok(());
        };
        if !Self::stable_sidecar_metadata_unchanged(&read_identity.metadata, &current) {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "staged active-receiver sidecar changed before cleanup".to_owned(),
            ));
        }
        std::fs::remove_file(path).map_err(|error| Error::IO(error, path.to_path_buf()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory))?;
        Ok(())
    }
    fn promote_kagemusha_active_receiver_finality_sidecar(
        &self,
        artifact: &V2FinalityArtifact,
        receipt: &KuraV2CommitReceipt,
    ) -> Result<()> {
        self.durable_mutation_authorized()?;
        if receipt.height != artifact.height
            || receipt.block_hash != artifact.block_hash
            || receipt.context_id != artifact.context_id()
            || receipt.subject != artifact.subject
            || receipt.certificate != artifact.commit_qc.as_ref()
            || receipt.artifact_hash != HashOf::new(artifact)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "finality receipt does not identify the active-receiver artifact".to_owned(),
            ));
        }
        let durable = self.v2_finality_artifact(artifact.height)?.ok_or_else(|| {
            Error::KagemushaActiveReceiverFinalitySidecar(
                "active-receiver promotion has no durable finality artifact".to_owned(),
            )
        })?;
        if durable != *artifact || HashOf::new(&durable) != receipt.artifact_hash {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "durable finality differs from active-receiver promotion receipt".to_owned(),
            ));
        }
        let _guard = self.sidecar_lock.lock();
        let final_path = self.kagemusha_active_receiver_sidecar_path(artifact.height);
        let staged_path = self.kagemusha_active_receiver_staging_path(artifact.height);
        if let Some((existing, _)) =
            self.decode_kagemusha_active_receiver_finality_sidecar(&final_path)?
        {
            Self::validate_kagemusha_active_receiver_finality_sidecar(&existing, artifact)?;
            if let Some((staged, identity)) =
                self.decode_staged_kagemusha_active_receiver_finality(&staged_path)?
            {
                Self::validate_staged_kagemusha_active_receiver_finality(&staged, artifact)?;
                self.remove_exact_staged_kagemusha_active_receiver_finality(
                    &staged_path,
                    &identity,
                )?;
            }
            return Ok(());
        }
        let Some((staged, staged_identity)) =
            self.decode_staged_kagemusha_active_receiver_finality(&staged_path)?
        else {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "finality is durable but its active-receiver witness stage is missing".to_owned(),
            ));
        };
        Self::validate_staged_kagemusha_active_receiver_finality(&staged, artifact)?;
        let final_sidecar = KagemushaActiveReceiverFinalitySidecarV1 {
            version: staged.version,
            height: staged.height,
            block_hash: staged.block_hash,
            ordinary_writes_root: staged.ordinary_writes_root,
            post_state_root: staged.post_state_root,
            finality_artifact_hash: receipt.artifact_hash,
            witness_proof: staged.witness_proof,
            validation_fee_policy_witness: staged.validation_fee_policy_witness,
            parliament_timed_ovn_casting_witness: staged.parliament_timed_ovn_casting_witness,
            parliament_timed_ovn_casting_bindings: staged.parliament_timed_ovn_casting_bindings,
        };
        Self::validate_kagemusha_active_receiver_finality_sidecar(&final_sidecar, artifact)?;
        let bytes = final_sidecar.encode();
        if bytes.len() > MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES {
            return Err(Error::KagemushaActiveReceiverFinalitySidecarTooLarge {
                actual: bytes.len(),
                max: MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES,
            });
        }
        let directory = self.kagemusha_active_receiver_sidecar_dir();
        create_dir_all_with_context(&directory)?;
        if let Some(parent) = directory.parent() {
            sync_dir(parent).map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        }
        if !self.write_atomic_synced_noclobber(&final_path, &bytes)? {
            let Some((existing, _)) =
                self.decode_kagemusha_active_receiver_finality_sidecar(&final_path)?
            else {
                return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                    "final active-receiver sidecar disappeared during publication".to_owned(),
                ));
            };
            if existing != final_sidecar {
                return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                    "no-clobber race published a conflicting active-receiver sidecar".to_owned(),
                ));
            }
        }
        let Some((persisted, identity)) =
            self.decode_kagemusha_active_receiver_finality_sidecar(&final_path)?
        else {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "final active-receiver sidecar disappeared after publication".to_owned(),
            ));
        };
        if persisted != final_sidecar
            || identity.bytes != bytes
            || identity.bytes_hash != Hash::new(&bytes)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "final active-receiver sidecar changed during readback".to_owned(),
            ));
        }
        self.remove_exact_staged_kagemusha_active_receiver_finality(
            &staged_path,
            &staged_identity,
        )?;
        Ok(())
    }
    /// Return the finalized fixed-key receiver snapshot witness proof for one block.
    pub fn kagemusha_active_receiver_witness_proof_v1(
        &self,
        height: u64,
    ) -> Result<Option<KagemushaActiveReceiverWitnessProofV1>> {
        let Some(artifact) = self.v2_finality_artifact(height)? else {
            return Ok(None);
        };
        let _guard = self.sidecar_lock.lock();
        let path = self.kagemusha_active_receiver_sidecar_path(height);
        let Some((sidecar, _)) = self.decode_kagemusha_active_receiver_finality_sidecar(&path)?
        else {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "finality artifact has no active-receiver witness sidecar".to_owned(),
            ));
        };
        Self::validate_kagemusha_active_receiver_finality_sidecar(&sidecar, &artifact)?;
        Ok(Some(sidecar.witness_proof))
    }
